export default [{"id":410,"title":"ثَوْرَة يَزيد بن المُهَلَّب في العِراق ومَقْتَلُه .","date":["العام الهجري :101","العام الميلادي :719"],"text":"كان يَزيدُ بن المُهَلَّب قد سُجِنَ أيَّام عُمَر بن عبدِ العزيز لِتَأْدِيَة المَظالِم التي عليه، فلمَّا عَلِمَ بِمَرَضِ عُمَر بن عبدِ العزيز هَرَب مِن السِّجْن خَوفًا مِن يَزيد بن عبدِ الملك، فلمَّا تَوَلَّى يَزيدُ بن عبدِ الملك سَجَنَ آلَ المُهَلَّب؛ لكنَّ يَزيد بن المُهَلَّب اسْتَطاع أن يَفُكَّهم وتَغَلَّبَ على البَصْرَة ثمَّ سَجَنَ أَميرَها وبَعَث عُمَّالَه إلى الأَهوازِ وفارِس، وأَرسَل أخاه إلى خُراسان، ونَزَل هو واسِط، ثمَّ أَرسَل يَزيدُ بن عبدِ الملك أخاه مَسلمَة لِقِتال ابنِ المُهَلَّب، ثمَّ دارت مَعركَة كان مِن نَتائِجِها قَتْلُ يَزيد بن المُهَلَّب وإخْوَتِه: حَبيب ومحمَّد. وكان اجْتِماع يَزيد بن المُهَلَّب ومَسلمَة بن عبدِ الملك بن مَرْوان ثَمانِيَة أيَّام مِن شَهرِ صَفَر سَنَة 102هـ."},{"id":411,"title":"وَفاةُ الخَليفَة الصَّالِح عُمَر بن عبدِ العزيز .","date":["العام الهجري :101","الشهر القمري : رجب","العام الميلادي :720"],"text":"هو عُمَر بن عبدِ العزيز بن مَرْوان بن الحَكَم بن العاص بن أُمَيَّة بن عبدِ شَمس القُرشِي الأُمَوي، أَميرُ المؤمنين، أُمُّهُ أُمُّ عاصِم لَيْلَى بِنتُ عاصِم بن عُمَر بن الخَطَّاب، ويُقال له: أَشَجُّ بَنِي مَرْوان. وكان يُقال: الأَشَجُّ والنَّاقِصُ أَعْدَلا بَنِي مَرْوان. فهذا هو الأَشَجُّ، بُويِعَ له بالخِلافَة بعدَ ابنِ عَمِّه سُليمان بن عبدِ الملك عن عَهْدٍ منه له بذلك. ويُقال: كان مَولِدُه في سَنَة إحدى وسِتِّين. دَخَل عُمَرُ بن عبدِ العزيز إلى إصْطَبْل أَبيهِ وهو غُلامٌ، فضَرَبَهُ فَرَسٌ فشَجَّهُ، فجَعَل أَبوهُ يَمسَح عنه الدَّمَ، ويقول: إن كُنْتَ أَشَجَّ بَنِي أُمَيَّة إنَّك إذًا لَسَعيد. أوَّل ما اسْتُبِينَ مِن عُمَر بن عبدِ العَزيز حِرْصُه على العِلْمِ ورَغْبَتُه في الأَدَبِ -أنَّ أباه وَلِيَ مِصرَ وهو حَديثُ السِّنِّ، يُشَكُّ في بُلوغِه، فأَرادَ إخْراجَه معه، فقال: يا أَبَه، أَوَ غَيْر ذلك لَعلَّه يكون أَنفَع لي ولك؟ تُرَحِّلُنِي إلى المَدينَة فأَقْعُد إلى فُقَهاء أَهلِها وأَتَأَدَّب بآدابِهم. فوَجَّهَه إلى المَدينَة، فقَعَد مع مَشايِخ قُريش، وتَجَنَّبَ شَبابَهم، وما زال ذلك دَأْبُه حتَّى اشْتَهَر ذِكْرُه، فلمَّا مات أَبوهُ أَخَذه عَمُّهُ أَميرُ المؤمنين عبدُ الملك بن مَرْوان فخَلطَه بِوَلدِه، وقَدَّمَه على كَثيرٍ منهم، وزَوَّجَه بابْنَتِه فاطِمَة. وَلَّاه الوَليدُ وِلايةَ المَدينَة، ثمَّ جَعلَه على الحِجاز مِن 86 – 93هـ، ثمَّ بُويِعَ بالخِلافَة بعدَ سُليمان بِوَصِيَّةٍ منه له, انْتَشَر في عَهدِه العَدلُ والمُساواةُ، ورَدُّ المَظالِم التي كان أَسلافُه مِن بَنِي أُمَيَّة قد ارْتَكَبوها، وعَزْلُ جَميعِ الوُلاة الظَّالِمين ومُعاقَبتُهم، كما أعاد العَمَل بالشُّورَى، كما اهْتَمَّ بالعُلومِ الشَّرعِيَّة، وأَمَر بِتَدوين الحَديثِ النَّبَوِيِّ. اسْتَمَرَّت خِلافَتُه سَنتينِ وخَمسة أَشهُر وأربعة أَيَّام سار فيها بسيرة الخلفاء الراشدين, تُوفِّي عُمَرُ عن تِسعٍ وثَلاثين، وقِيلَ أَربعين سَنَة، وكان سَبَبُ وَفاتِه أنَّه سُقِيَ السُّمَّ، وذلك أنَّ بَنِي أُمَيَّة قد تَبَرَّموا وضاقوا ذَرْعًا مِن سِياسَة عُمَر التي قامَت على العَدْل، وحَرَمَتْهُم مِن مَلَذَّاتِهم وتَمَتُّعِهم بِمِيزات لا يَنالها غَيرُهم، ورَدّ المَظالِم التي كانت في أَيديهِم، وحالَ بينهم وبين ما يَشتَهون، فكاد له بَعضُ بَنِي أُمَيَّة بِوَضْعِ السُّمِّ في شَرابِه، فوَضَع مَوْلًى له سُمًّا في شَرابِه، وأُعْطِيَ على ذلك أَلفَ دِينارٍ، فأُخْبِرَ أنَّه مَسموم، فقال: لقد عَلِمتُ يومَ سُقِيتُ السُّمَّ. ثمَّ اسْتَدعَى مَولاهُ الذي سَقاهُ، فقال له وَيْحَك، ما حَمَلَك على ما صَنعتَ؟ فقال: ألفُ دِينارٍ أُعْطِيتُها. فقال: هاتِها. فأَحْضَرها فوَضَعها في بَيتِ المالِ، ثمَّ قال له: اذْهَب حيث لا يَراك أَحَدٌ فَتَهْلَك."},{"id":412,"title":"يَزيدُ بن عبدِ الملك يَتَوَلَّى الخِلافَة بعدَ وَفاةِ عُمَر بن عبدِ العزيز .","date":["العام الهجري :101","الشهر القمري : رجب","العام الميلادي :720"],"text":"دامَت خِلافَةُ عُمَر بن عبدِ العزيز سَنَتينِ وخَمسة أَشهُر، فلمَّا تُوفِّي صارت الخِلافَةُ إلى يَزيد بن عبدِ الملك بِناءً على الكِتاب الذي كَتبَه سُليمانُ أن يَلِيَ الأمْرَ بعدَ عُمَر يَزيدُ فصار بذلك الخَليفَة."},{"id":413,"title":"غَزْوُ السَّمْح بن مالِك الخَوْلاني فَرنسا واسْتِشهادُه في مَعركَة طولوز .","date":["العام الهجري :102","العام الميلادي :720"],"text":"غَزا السَّمْحُ بن مالِك الخَوْلاني فَرنسا فاخْتَرق جِبالَ البرانس وزَحَف على مُقاطَعَتي سبتمانيا وبروفانس، ثمَّ أَغارَ على اكيتانيا، وحاصَر طلوشة (طولوز) فخَرَج له دُوق اكيتانيا بجَيشٍ كَبيرٍ ونَشبَت مَعركَة عَظيمَة بين الطَّرَفين، اسْتُشْهِدَ فيها السَّمْح، وتَوَلَّى إمْرَةَ الجُنْدِ عبدُ الرَّحمن الغافِقي فانْسَحَب بِفُلول الجَيْشِ إلى أربونه."},{"id":414,"title":"غَزْوُ بِلادِ الصُّغْدِ  .","date":["العام الهجري :104","العام الميلادي :722"],"text":"عَبَر سَعيدُ خُذَيْنَة والي خُراسان النَّهْرَ وغَزا الصُّغْدَ، وكانوا قد نَقَضوا العَهْدَ وأعانوا التُّرْكَ على المسلمين، فقال النَّاسُ لسَعيدٍ: إنَّك قد ترَكتَ الغَزْوَ، وقد أغار التُّرْكُ، وكَفَرَ أَهلُ الصُّغْد. فقَطَع النَّهْرَ وقَصَد الصُّغْدَ، فلَقِيَه التُّرْكُ وطائِفَة مِن الصُّغْدِ فهَزَمهم المسلمون، فقال سَعيدٌ: لا تَتَّبِعوهم فإنَّ الصُّغْدَ بُستان أَميرِ المؤمنين وقد هَزَمتُموهم، أَفَتُريدون بَوارَهُم؟ وقد قاتَلْتُم يا أَهلَ العِراق الخُلَفاء غَيرَ مَرَّةٍ، فهل أَبادوكُم؟ وسار المسلمون فانْتَهوا إلى وادٍ بينهم وبين المَرَج، فقَطَعَه بَعضُهم وقد أَكْمَن لهم التُّرْكُ، فلمَّا جاءَهم المسلمون خَرجوا عليهم، فانْهزَم المسلمون حتَّى انْتَهوا إلى الوادي، فصَبَروا حتَّى انْكَشفوا لهم. وقيل: بل كان المُنْهَزِمون مَسْلَحَة المسلمين، فما شَعَروا إلَّا والتُّرْك قد خَرَجوا عليهم مِن غَيْضَةٍ وعلى الخَيْلِ شُعْبَة بن ظَهير، فأَعجَلَهم التُّرْك عن الرُّكوبِ، فقاتَلَهم شُعبةُ فقُتِلَ وقُتِلَ نَحو مِن خمسين رَجُلًا وانْهَزَم أَهلُ المَسْلَحَة، وأَتى المسلمين الخَبَرُ، فَرَكِبَ الخَليلُ بن أَوْس العَبْشَمِي -أَحَدُ بَنِي ظالِم- ونادَى: يا بَنِي تَميمٍ إِلَيَّ أنا الخَليلُ! فاجْتَمَع معه جَماعَةٌ، فحَمَل بهم على العَدُوِّ فكَفُّوهم حتَّى جاء الأَميرُ والنَّاسُ فانْهَزَم العَدُوُّ، فصار الخَليلُ على خَيْلِ بَنِي تَميمٍ حتَّى وَلِيَ نَصْرُ بن سِيار، ثمَّ صارت رِياسَتُهم لأَخيهِ الحَكَم بن أَوْسٍ، فلمَّا كان العام المُقبِل بَعَث رِجالًا مِن تَميمٍ إلى وَرَغْسَر فقالوا: لَيْتَنا نَلقَى العَدُوَّ فنُطارِدُهم. وكان سَعيد إذا بَعَث سَرِيَّةً فأصابوا أو غَنِموا وسَبَوْا رَدَّ السَّبْيَ وعاقَبَ السَّرِيَّة."},{"id":415,"title":"عَزْلُ عبدِ الرَّحمن بن الضَّحَّاك عن المَدينَة ومَكَّة .","date":["العام الهجري :104","العام الميلادي :722"],"text":"عَزَل يَزيدُ بن عبدِ الملك عبدَ الرَّحمن بن الضَّحَّاك عن المَدينَة ومَكَّة، وكان عامِلَهُ عليهما ثلاثَ سِنين، ووَلَّى عبدَ الواحِد النَّضْري، وكان السَّبَب في عَزْلِه أنَّه خَطَب فاطِمَة بِنتَ الحُسين بن عَلِيٍّ فقالت: ما أُريدُ النِّكاحَ، ولقد قَعَدتُ على بَنِيِّ هؤلاء. فأَلَحَّ عليها وقال: لئن لم تَفعَلي لأَجْلِدَنَّ أَكبرَ بَنِيك في الخَمْرِ. فبَعَثَتْ كِتابًا إلى الخَليفَة تُخبِرُه بِخَبرِه. فأَخَذ الكِتابَ فَقَرأهُ وجَعَل يَضرِب بِخَيْزران في يَدهِ ويَقولُ: لقد اجْتَرأ ابنُ الضَّحَّاك، هل مِن رَجُلٍ يُسْمعني صَوتَه في العَذابِ؟ قِيلَ له: عبدُ الواحِد بن عبدِ الله النَّضْرِي. فكَتَب بِيَدِه إلى عبدِ الواحد: قد وَلَّيْتُكَ المَدينَة فاهْبِط إليها واعْزِل عنها ابنَ الضَّحَّاك، وأَغْرِمْهُ أَربعين ألفَ دِينارٍ، وعَذِّبْهُ حتَّى أَسمعَ صَوتَه وأنا على فِراشي. وكان ابنُ الضَّحَّاك قد آذَى الأَنْصارَ طُرًّا، فهَجاهُ الشُّعَراءُ وذَمَّهُ الصَّالِحون، ولمَّا وَلِيَهم النَّضْرِيُّ أَحسَن السِّيرةَ فأَحَبُّوه، وكان خَيِّرًا يَسْتَشيرُ فيما يُريدُ فِعلَه القاسِمَ بن محمَّد وسالِمَ بن عبدِ الله بن عُمَر."},{"id":416,"title":"غَزْوُ مُسلِم بن سَعيد بِلادَ التُّرْك .","date":["العام الهجري :105","العام الميلادي :723"],"text":"غَزَا مُسلِمُ بن سَعيد التُّرْكَ فعَبَر النَّهرَ وعاثَ في بِلادِهم ولم يَفتَح شَيئًا وقَفَلَ، فأَتْبَعَه التُّرْكُ ولَحِقُوهُ على النَّهرِ فعَبَر بالنَّاسِ ولم يَنالوا منه، ثمَّ غَزا بَقِيَّةَ السَّنَة وحاصَر افشين حتَّى صالَحُوه على سِتَّة آلافِ رَأسٍ، ثمَّ دَفَعوا إليه القَلعَة، ثمَّ غَزَا سَنَة سِتٍّ ومائة وتَباطَأ عنه النَّاسُ, ولمَّا قَطَع مُسلمٌ النَّهرَ وصار ببُخارَى أَتاهُ كِتابٌ مِن خالدِ بن عبدِ الله القَسْرِي بِوِلايَتِه على العِراق، ويَأمُره بإتمام غَزاتِه, فسارَ إلى فَرْغانَة، فلمَّا وَصلَها بَلغَه أن خاقان قد أَقبَل إليه وأنَّه في مَوضِعٍ ذَكَروه، فارْتَحَل، فسار ثلاث مَراحِل في يَومٍ، وأَقبَل إليهم خاقان فلَقِيَ طائِفَة مِن المسلمين وأَصابَ دَوابَّ لِمُسلمِ بن سَعيد، وقُتِلَ أخو غَوْزَك وثار النَّاسُ في وُجوهِهِم فأخرجوهم مِن العَسْكَر، ورَحَل مُسلمٌ بالنَّاس فسار ثمانِيةَ أيَّام وَهُم مُطيفون بهم، فلمَّا كانت التَّاسِعَة أَرادوا النُّزولَ فشاوَرَ النَّاسَ، فأَشاروا عليه بالنُّزولِ وقالوا: إذا أَصبَحنا وَرَدْنا الماءَ، والماءُ مِنَّا غَيرَ بَعيدٍ. فنَزلوا ولم يَرفَعوا بِناء في العَسكَر، وأَحرقَ النَّاسُ ما ثَقُلَ مِن الآنِيَة والأَمْتِعَة، فحَرَقوا ما قِيمتُه ألف ألف، وأَصبَح النَّاسُ فساروا فوَرَدُوا النَّهْرَ وأَهلُ فَرْغانَة والشَّاش دُونَه، فقال مُسلِم بن سَعيد: أَعْزِمُ على كُلِّ رَجُلٍ إلَّا اخْتَرَطَ سَيفَه، ففَعَلوا وصارت الدُّنيا كُلُّها سُيوفًا، فتَرَكوا الماءَ وعَبَروا. فأَقام يَومًا ثمَّ قَطَع مِن غَدٍ واتَّبَعَهم ابنٌ لِخَاقان، فأَرسَل إليه حميد بن عبدِ الله، وهو على السَّاقَة: فقال له: قِفْ لي فإنَّ خَلفِي مائتي رَجُل مِن التُّرْك حتَّى أُقاتِلَهم. وهو مُثْقَلٌ جِراحَةً، فوَقَف النَّاسُ وعَطَف على التُّرْكِ فقاتَلَهم، وأَسَر أَهلَ الصُّغْدِ وقائِدَهم وقائِدَ التُّرْك في سَبعَة ومَضَى البَقِيَّةُ، ورَجَع حُميد فرُمِيَ بنُشَّابَة في رُكْبَتِه فمات. وعَطِشَ النَّاسُ، وكان عبدُ الرَّحمن العامِري حَمَل عشرين قِرْبَة على إبِلِه فسَقاها النَّاسَ جُرَعًا جُرَعًا، اسْتَسْقَى مُسلمُ بن سَعيدٍ، فأَتوه بإناءٍ، فأَخَذه جابِرٌ أو حارِثَة بن كَثير أخو سُليمان بن كَثير مِن فِيهِ، فقال مُسلمٌ: دَعوه فما نازَعَنِي شَرْبَتِي إلَّا مِن حَرٍّ دَخَلَهُ. وأتوا خُجَنْدَة، وقد أَصابَهم مَجاعةٌ وجَهْدٌ، فانْتَشَر النَّاسُ."},{"id":417,"title":"غَزْوُ عَنْبَسَة بن سُحَيْم الكَلْبِي فَرنسا (بِلادَ غالَة) .","date":["العام الهجري :105","العام الميلادي :723"],"text":"غَزَا عَنْبَسَةُ بن سُحَيْمٍ الكَلْبِي أَميرُ الأَندَلُس بَلدَ الفِرِنْج في جَمعٍ كَثيرٍ، ونازَل مَدينَة قَرْقَسُونة وحَصَر أَهلَها، فصالَحوه على نِصْف أَعمالِها، وعلى جَميعِ ما في المَدينَة من أَسرَى المسلمين وأَسلابِهم، وأن يُعطوا الجِزْيَة، ويَلتَزِموا بأَحكام الذِّمَّة مِن مُحارَبة مَن حارَبَه المسلمون، ومَسالَمة مَن سالَموه، فعاد عنهم عَنْبَسَة، ثمَّ تَوَغَّلَ داخِلَ فَرنسا وغَزَا إقليمَ الرون وبرفانس وليون وبورغونيا حتَّى وَصَل أَعالِي الرون. وتُوفِّي في شَعبان سَنة سَبعٍ ومائة عندَ انْصِرافه مِن غَزوِ الإفْرِنْج."},{"id":418,"title":"وَفاةُ يَزيدَ بن عبدِ الملك .","date":["العام الهجري :105","الشهر القمري : رجب","العام الميلادي :723"],"text":"هو يَزيدُ بن عبدِ الملك بن مَرْوان بن الحَكَم بن أبي العاص بن أُمَيَّة بن عبدِ شَمسِ بن عبدِ مَناف أبو خالدٍ القُرَشِي الأُمَوي، أَميرُ المؤمنين، وأُمُّهُ عاتِكَة بِنتُ يَزيدَ بن مُعاوِيَة. بُويِعَ له بالخِلافَة بعدَ عُمَر بن عبدِ العزيز في رَجب مِن سَنة إحدى ومائة، بِعَهْدٍ مِن أَخيهِ سُليمان أن يكون الخَليفَة بعدَ عُمَر بن عبدِ العَزيز رَحِمَه الله، تُوفِّي يومَ الجُمُعَة لِخَمسٍ بَقِينِ من رَجب."},{"id":419,"title":"تَوَلِّي هِشامِ بن عبدِ الملك الخِلافَة .","date":["العام الهجري :105","الشهر القمري : رجب","العام الميلادي :723"],"text":"تَوَلَّى هِشامٌ الخِلافَةَ بعدَ وَفاةِ أَخيهِ يَزيد بن عبدِ الملك وبِعَهْدٍ منه إليه بذلك."},{"id":420,"title":"ظُهورُ فِئَةٍ مِن الخَوارِج باليَمَن .","date":["العام الهجري :107","العام الميلادي :725"],"text":"خَرَج باليَمَنِ رَجُلٌ يُقالُ له: عَبَّاد الرُّعَيْنِي، فدَعا إلى مَذهَب الخَوارِج، واتَّبَعَه فِرْقَةٌ مِن النَّاس وحَكَموا، فقاتَلَهم يُوسُف بن عُمَر الثَّقَفِي فقَتَلَه وقَتَل أَصحابَه، وكانوا ثلاثمائة."},{"id":421,"title":"وَفاةُ سُليمان بن يَسار أَحَد الفُقَهاء السَّبْعَة  .","date":["العام الهجري :107","العام الميلادي :725"],"text":"هو أبو أَيُّوب سُليمانُ بن يَسارٍ، وُلِدَ في خِلافَة عُثمان سَنة أربع وثلاثين, مَوْلَى أُمِّ المؤمنين مَيْمونَة بِنتِ الحارِث، أَحَدُ الفُقَهاء السَّبْعَة بالمَدينَة، كان عالِمًا ثِقَةً عابِدًا وَرِعًا حُجَّةً، كَثيرَ الصِّيام، فَقيهًا كَبيرًا، أَبوهُ فارِسِيٌّ، رَوَى عن مَولاتِه مَيْمونَة، وعن عائِشَة، وأبي هُريرةَ، وغَيرِهم مِن الصَّحابَة، كان مِن أَوْعِيَة العِلْم بحيث إنَّ بَعضَهم قد فَضَّلَه على سَعيدِ بن المُسَيِّب، وكان سَعيدُ بن المُسيب يُحِيلُ عليه المُسْتَفْتِين, ويقول عنه: \"إنَّه أَعلَم مَن بَقِيَ اليومَ\"، يقول الإمامُ مالِكٌ عنه: \"كان سُليمان بن يَسار مِن عُلَماء النَّاسِ بعدَ سَعيدِ بن المُسَيِّب، وكان كَثيرًا ما يُوافِقُه\"، وتُوفِّي في المَدينَة."},{"id":422,"title":"غَزْوُ أَسَد القَسْرِي للغَوْرِ غرب أفغانستان .","date":["العام الهجري :107","العام الميلادي :725"],"text":"غَزَا أَسَدُ القَسْرِي جِبالَ نمروذ مَلِك القَرْقِيسِيان، مما يَلِي جِبالَ الطَّالقان، فصالَحَه نمروذ وأَسلَم على يَديهِ. وفيها غَزَا أَسَدٌ القَسْرِي الغَوْرَ -وهي جِبالُ هَراةَ- عَمَدَ أَهلُها إلى حَواصِلِهم وأَموالِهم وأَثقالِهم فجَعَلوا ذلك كُلَّه في كَهفٍ مَنيعٍ، لا سَبيلَ لِأَحَدٍ عليه، وهو مُسْتَعْلٍ جِدًّا، فأَمَر أَسَدُ بالرِّجالِ فحُمِلُوا في تَوابيت ودَلَّاهُم إليه، وأَمَر بِوَضْعِ ما هنالك في التَّوابيت ورَفَعوهم فسَلِموا وغَنِموا."},{"id":423,"title":"وَفاةُ القاسِم بن محمَّد بن أبي بَكرٍ أَحَد الفُقَهاء السَّبْعَة في المَدينَة .","date":["العام الهجري :107","العام الميلادي :725"],"text":"هو القاسِمُ بن محمَّد بن أبي بَكْرٍ الصِّدِّيق، أَحَدُ الفُقَهاء السَّبعَة بالمَدينَة، مِن سادات التَّابِعين, كان ثِقَةً عالِمًا، مات أَبوهُ وعُمُرُه سَبعُ سَنوات, تَرَبَّى في حِجْرِ عَمَّتِه عائِشَة رَضِيَ الله عنها فتَفَقَّهَ عليها، فكان فَقيهًا إمامًا وَرِعًا كَثيرَ الحَديثِ، قال أبو الزِّناد: ما رَأيتُ أَحَدًا أَعلمَ بالسُّنَّةِ مِن القاسِم بن محمَّد، وما كان الرَّجُل يُعَدُّ رَجُلًا حتَّى يَعرِفَ السُّنَّة، وما رَأيتُ أَحَدًا أَحَدَّ ذِهْنًا مِن القاسِم. قِيلَ: إنَّه مات بقُدَيْد، فقال: كَفِّنُونِي في ثِيابِي التي كُنتُ أُصَلِّي فيها، قَميصي ورِدائي، هكذا كُفِّنَ أبو بَكرٍ. وأَوْصَى أن لا يُبْنَى على قَبرِه."},{"id":424,"title":"وَفاةُ عَنْبَسَة بن سُحَيْمٍ الكَلْبِي  .","date":["العام الهجري :107","العام الميلادي :725"],"text":"هو عَنْبَسَة بن سُحَيْمٍ الكَلْبِي -نِسْبَةً إلى قَبيلَة كَلْب اليَمانِيَّة، المَعروفَة بِتَأْيِيدِها للأُمَويِّين- والي الأَندَلُس، ومِن قادَةِ الدَّولَة الأُمَويَّة الأَفْذاذ، له فُتوحات واسِعَة في أوروبا، وقد أُصِيبَ بجِراحاتٍ في بَعضِ الوَقائِع مع الفِرِنْج، فكانت سَبَبَ وَفاتِه، رَحِمَه الله, وكانت وِلايَتُه على الأَندَلُس أربعَ سِنين وأربعة أَشهُر."},{"id":425,"title":"فَتْحُ المسلمين حِصْن طِيبَة بِأَرضِ الرُّوم .","date":["العام الهجري :109","العام الميلادي :727"],"text":"غَزَا مُعاوِيَةُ بن هِشام أَرضَ الرُّوم ففَتَح حِصْنًا يُقالُ له طِيبَة، فأُصِيبَ معه قَومٌ مِن أَهلِ أَنطاكِيَّة."},{"id":426,"title":"دُخولُ أَهلِ الذِّمَّة بسَمَرْقَنْد الإسلام بَعدَ وَضْعِ الجِزْيَة عنهم .","date":["العام الهجري :110","العام الميلادي :728"],"text":"دَعَا أَشْرَسُ بن عبدِ الله السُّلَمِي نائِبُ خُراسان أَهلَ الذِّمَّة بِسَمَرْقَنْد ومَن وَراء النَّهْر إلى الدُّخولِ في الإسلامِ، ويَضَع عنهم الجِزْيَة فأَجابوه إلى ذلك، وأَسلَم غالبُهم، ثمَّ طالَبَهم بالجِزْيَة فنَصَبوا له الحَرْب وقاتَلوه، ثمَّ كانت بينه وبين التُّرْك حُروبٌ كَثيرَة."},{"id":427,"title":"وَفاةُ الشَّاعِرَيْن الفَرَزدَق وجَرير  .","date":["العام الهجري :110","العام الميلادي :728"],"text":"الفَرَزدَق هو هَمَّام بن غالِب التَّميمِي أبو فِراس، له مَواقِف وأَشعار في الذَّبِّ عن آلِ البَيتِ، كان غالِبَ شِعْرِه الفَخْرُ، تُوفِّي وعُمُرُه يُقارِب المِائة. وجَدُّهُ صَعْصَعَة بن ناجِيَة صَحابِيٌّ، وَفَدَ إلى رَسولِ الله صلَّى الله عليه وسلَّم، وكان يُحْيِي المَوْءُودَة في الجاهِلِيَّة. قال: الفَرَزدَق وَفَدْتُ مع أبي على عَلِيٍّ، فقال: مَن هذا؟ قال: ابني وهو شاعِرٌ. قال: عَلِّمْهُ القُرآنَ فهو خَيْرٌ له مِن الشِّعْرِ. قال الفَرَزدَق: نَظَر أبو هُريرةَ إلى قَدَمي فقال: يا فَرَزدَق إنِّي أَرَى قَدَمَيك صَغِيرتَين، فاطْلُب لَهُما مَوْضِعًا في الجَنَّة. فقلتُ: إنَّ ذُنوبي كَثيرَة. فقال: لا تَيْأَس. و لمَّا سُئِلَ عن قَيْدٍ في رِجْلِه قال: حَلَفْتُ أن لا أَنْزَعَه حتَّى أَحفَظَ القُرآنَ. قال له بَعضُهم: ألا تَخافُ مِن الله في قَذْفِ المُحْصَنات؟ فقال: واللهِ للهُ أَحَبُّ إِلَيَّ مِن عَيْنَيَّ اللَّتَيْنِ أُبصِرُ بهما، فكيف يُعَذِّبُني؟. أمَّا جَرير فهو جَريرُ بن عَطِيَّة بن الخَطَفِيِّ، أبو حَزْرَةَ، الشَّاعِر البَصْرِي. اشْتَهَر جَريرٌ بِرِقَّةِ شُعورِه وحُسْنِ خُلُقِه. سَمَّتْهُ أُمُّهُ جَريرًا -وهو الحَبْلُ الغَليظُ- لأنَّ أُمَّهُ رَأتْ وهي حامِل به أنَّها وَلَدَتْ جَريرًا يعني الحَبْلَ، فسَمَّتْهُ بذلك، تُوفِّي وهو ابنُ اثنين وثمانين عامًا، وكان في عَصْرِه مِن الشُّعَراء الذين يُقارَنون به الفَرَزدَق، والأَخْطَل، وكان بين الثَّلاثة تَناظُر بالأَشْعار وتَساجُل، وكان جَريرٌ أَشْعَرَهُم وأَخْيَرَهُم. لمَّا مات الفَرَزدَق وبَلَغ خَبرُه جَريرًا بَكَى وقال: أمَّا والله إنِّي لأَعلَمُ أنِّي قَليلُ البَقاءِ بَعدَه، ولقد كان نَجْمًا واحِدًا وكُلُّ واحِد مِنَّا مَشغولٌ بِصاحِبِه، وقَلَّما مات ضِدٌّ أو صَديقٌ إلَّا وتَبِعَهُ صاحِبُه. وكذلك كان، مات جَريرٌ بَعدَه بِأَشهُر."},{"id":428,"title":"انتصار مَسلَمَة بن عبدِ الملك على التُّرْك في غَزَاةِ الطِّين .","date":["العام الهجري :110","الشهر القمري : جمادى الآخرة","العام الميلادي :728"],"text":"قاتَل مَسلَمةُ بن عبدِ الملك مَلِكَ التُّرْكِ الأَعظَم خاقان، فزَحَف إلى مَسلَمة في جُموعٍ عَظيمَة فتَواقَفوا نَحوًا مِن شَهرٍ، ثمَّ هَزَم الله خاقان زَمَن الشِّتاءِ، ورَجَع مَسلَمَةُ سالِمًا غانِمًا، فسَلَك على مَسْلَك ذي القَرْنَيْنِ في رُجوعِه إلى الشَّام، وتُسَمَّى هذه الغَزَاة غَزَاة الطِّين، وذلك أنَّهم سَلَكوا على مَغارِق ومَواضِع غَرِقَ فيها دَوابٌّ كَثيرَة، وتَوَحَّل فيها خَلْقٌ كَثيرٌ، فما نَجَوْا حتَّى قاسُوا أَهْوالًا صِعابًا وشَدائِدَ عِظامًا."},{"id":429,"title":"وَفاةُ الحَسَن البَصْرِي .","date":["العام الهجري :110","الشهر القمري : رجب","العام الميلادي :728"],"text":"هو أبو سَعيدٍ الحَسَنُ بن يَسار البَصْرِي، وُلِدَ قَبلَ سَنَتين مِن نِهايَة خِلافَة عُمَر بن الخَطَّاب في المَدينَة عام 21هـ. كانت أُمُّهُ تَخدُم أُمَّ سَلَمَة، ورُبَّما أَرْسَلَتْها في الحاجَةِ فتَشْتَغِلُ عن وَلَدِها الحَسَن وهو رَضيعٌ فتُشاغِلُه أُمُّ سَلَمَة بِثَدْيَيْها فيُدِرَّان عليه فيَرْتَضِعُ منهما، فكانوا يَرَون أنَّ تلك الحِكْمَةَ والعُلومَ التي أُوتِيها الحَسَن مِن بَرَكَةِ تلك الرَّضاعَة مِن الثَّدْيِ المَنْسوبِ إلى رَسولِ الله صلَّى الله عليه وسلَّم، ثمَّ كان وهو صَغيرٌ تُخْرِجُه أُمُّه إلى الصَّحابَة فيَدْعون له، وكان في جُملَةِ مَن يَدعو له عُمَرُ بن الخَطَّاب، قال: اللَّهُمَّ فَقِّههُ في الدِّين، وحَبِّبْهُ إلى النَّاس. وقد كان الحَسَنُ جامِعًا للعِلْمِ والعَمَل، عالِمًا رَفيعًا فَقيهًا ثِقَةً مَأْمونًا عابِدًا زاهِدًا ناسِكًا، كَثيرَ العِلْمِ والعَمَل، فَصيحًا جَميلًا وَسيمًا، وقَدِمَ مَكَّة فأُجْلِسَ على سَريرٍ وجَلَس العُلَماء حَولَه واجْتَمَع النَّاسُ إليه فحَدَّثَهُم."},{"id":430,"title":"وَفاةُ محمَّد بن سِيرينَ .","date":["العام الهجري :110","الشهر القمري : شوال","العام الميلادي :729"],"text":"هو محمَّدُ بن سِيرينَ أبو بَكر بن أبي عَمرٍو الأَنصارِي، مَوْلَى أَنَسِ بن مالِكٍ النَّضْرِي، كان أبوه مِن سَبْيِ عَيْنِ التَّمْر، أَسَرَهُ في جُملَةِ السَّبْيِ خالدُ بن الوَليدِ، فاشْتَراهُ أَنسُ بن مالِك ثمَّ كاتَبَهُ. وُلِدَ ابنُ سِيرينَ لِسَنَتينِ بَقِيَتا في خِلافَة عُثمان، كان مِن جُلَّةِ التَّابِعين، قال هِشامُ بن حَسَّان: هو أَصْدَقُ مَن أَدركْتُ مِن البَشَرِ. ولمَّا مات أَنسُ بن مالِك أَوْصى أن يُغَسِّلَه محمَّدُ بن سِيرينَ، قال ابنُ عَوْنٍ: كان محمَّد يأتي بالحَديثِ على حُروفِه. قال أَشْعَثُ: كان ابنُ سِيرينَ إذا سُئِلَ عن الحَلالِ والحَرامِ تَغَيَّرَ لَونُه حتَّى يكونَ كأنَّه ليس بالذي كان. قال مُوَرِّقٌ العِجْلِي: ما رَأيتُ أَحَدًا أَفْقَهَ في وَرَعِه ولا أَوْرَعَ في  فِقْهِهِ مِن محمَّدِ بن سِيرينَ. كان مَشهورًا في تَعبيرِ الرُّؤى والأَحلامِ، وأمَّا الكِتابُ المَوجودُ اليومَ على أنَّه مِن تَألِيفِه فغَيْر صَحيح، فهو لم يُؤَلِّف كِتابًا في تَفسير الرُّؤى، وتَعْبِيراتُه للرُّؤَى مَبْثُوثَة في كُتُب التَّراجِم والتَّاريخ."},{"id":431,"title":"غَزْوُ أَبناء هِشامِ بن عبدِ الملك قَيْسارِيَّة .","date":["العام الهجري :111","العام الميلادي :729"],"text":"غَزَا مُعاوِيَةُ بن هِشامٍ الصَّائِفَة اليُسْرَى، وغَزَا سَعيدُ بن هِشامٍ الصَّائِفَة اليُمْنَى حتَّى أَتَى قَيْسارِيَّة."},{"id":432,"title":"فَتْحُ الأمويين مَدينَة البَيْضاء بِبِلادِ الخَزَر .","date":["العام الهجري :111","العام الميلادي :729"],"text":"اسْتَعمَل هِشامُ بن عبدِ الملك الحَجَّاحَ بن عبدِ الله الحَكَمِيَّ على أرمينية، وعَزَل أَخاه مَسلَمَة بن عبدِ الملك، فدَخَل بِلادَ الخَزَر مِن ناحِيَة تفليس وفَتَح مَدينَتَهم البَيْضاءَ وانْصَرَف سالِمًا، فجَمَعَت الخَزَرُ وحَشَدَت وسارَت إلى بِلادِ الإسلامِ."},{"id":433,"title":"غَزْوُ الجُنَيْدِ المُرِّيِّ التُّرْك (غَزْوَة الشِّعْب) .","date":["العام الهجري :112","العام الميلادي :730"],"text":"خَرَج الجُنَيْدُ المُرِّيُّ غازِيًا يُريدُ طَخارِسْتان، فوَجَّه عُمارَةَ بن حُرَيْم إلى طَخارِسْتان في ثمانِيَة عَشر ألفًا، ووَجَّهَ إبراهيمَ بن بَسَّام اللَّيْثِيَّ في عَشرةِ آلافٍ إلى وَجْهٍ آخَر، وجاشَت التُّرْكُ فأتوا سَمَرْقَنْد وعليها سَوْرَةُ بن الحُرِّ، فكَتَب سورةُ إلى الجُنَيْدِ: إنَّ خاقان جاشَ التُّرْكَ فخَرَجتُ إليهم فلم أَطِقْ أن أَمنَع حائِطَ سَمَرْقَنْد، فالغَوْثَ الغَوْثَ. وعَبَرَ الجُنيدُ فنَزَل كِشَّ وتَأَهَّبَ للمَسيرِ، وبَلَغ التُّرْك فغَوَّرُوا الآبارَ التي في طَريقِ كِشٍّ فأَخَذ الجُنيدُ طَريقَ العَقَبَة فارْتَقى في الجَبَلِ ودَخَل الشِّعْبَ، فصَبَّحَهُ خاقان في جَمعٍ عَظيمٍ، وزَحَف إليه أَهْلُ الصُّغْدِ وفَرْغانَة والشَّاش وطائِفَة مِن التُّرْك، فحَمَل خاقان على المُقَدِّمَة وأَخَذ الرَّايَة ابنُ مَجاعَة فقُتِلَ، وتَداوَلَها ثمانية عشر رَجُلًا فقُتِلوا، وصَبَر النَّاسُ يُقاتِلون حتَّى أَعْيوا، فكانت السُّيوف لا تَقطَع شَيْئًا، فقَطَع عَبيدُهُم الخَشَب يُقاتِلون به حتَّى مَلَّ الفَريقان، فكانت المُعانَقَة ثمَّ تَحاجَزوا فبَيْنا النَّاسُ كذلك إذ أَقْبَل رَهَجٌ وطَلَعَت فُرْسانٌ، فنادَى الجُنيدُ: الأرضَ الأرضَ! فتَرَجَّلَ وتَرَجَّل النَّاسُ، ثمَّ نادَى: لِيُخَنْدِق كُلُّ قائِدٍ على حِيالِه. فخَنْدَقوا وتَحاجَزوا ثمَّ طَلَب الجُنيدُ النَّجْدَة فعَرَفت التُّرْك بذلك فكَمُنَت له وقَتَلَته، فخَرَج مِن الشِّعْب واشْتَدَّ الأَمْرُ حتَّى قال الجُنيدُ: كُلُّ عَبدٍ قاتَل فهو حُرٌّ. فقاتَلوا قِتالًا عَجِبَ منه النَّاسُ حتَّى انْكَشَف العَدُوُّ ورَجَع الجُنيدُ إلى سَمَرْقَنْد."},{"id":434,"title":"غَزْوُ الجَرَّاح الحَكَمِي بِلاد اللَّان \n  .","date":["العام الهجري :112","الشهر القمري : رمضان","العام الميلادي :730"],"text":"غَزَا الجَرَّاح بن عبدِ الله الحَكَمي بِلادَ الخَزَر شمال القوقاز، وهم إيرانيون، فاجْتَمَع الخَزَرُ والتُّرْك مِن ناحِيَة اللَّان، فلَقِيَهم الجَرَّاح فيمَن معه مِن أَهلِ الشَّام وأذربيجان، فاقْتَتَلوا أَشَدَّ قِتالٍ رَآهُ النَّاسُ، فصَبَر الفَريقان، وتَكاثَرَت الخَزَرُ والتُّرْكُ على المسلمين فاسْتُشْهِد هو ومَن معه مِن الجُنْدِ بأردبيل، ولمَّا قُتِلَ الجَرَّاح طَمِعَ الخَزَرُ وأَوْغَلوا في البِلادِ حتَّى قاربوا المَوْصِل، وعَظُمَ الخَطْبُ على المسلمين. فلمَّا بَلَغ ذلك هِشامَ بن عبدِ الملك بَعَث سَعيدَ بن عَمرٍو الحَرَشِي بجَيْشٍ وأَمَرَهُ بالإسراعِ إليهم، فلَحِقَ التُّرْكَ وَهُم يَسيرون بأَسارَى المسلمين نحو مَلِكِهم خاقان، فاسْتَنْقَذ منهم الأَسارَى ومَن كان معهم مِن نِساء المسلمين، ومِن أَهلِ الذِّمَّةِ أيضًا، وقَتَل مِن التُّرْك مَقْتَلَةً عَظيمَةً جِدًّا، وأَسَر منهم خَلْقًا كثيرًا فقَتَلهم صَبْرًا، ولم يَكْتَفِ الخَليفَة بذلك حتَّى أَرسَل أخاه مَسلمَةَ بن عبدِ الملك في أَثَر التُّرْك، فسار إليهم في بَرْدٍ شَديدٍ وشِتاءٍ عَظيمٍ، فوَصَل إلى بابِ الأَبوابِ،وسار بمن معه في طَلَبِ الأَتراك ومَلِكِهم خاقان."},{"id":435,"title":"وفاة الجراح الحكمي\n  .","date":["العام الهجري :112","الشهر القمري : رمضان","العام الميلادي :730"],"text":"هو أبو عُقْبَة الجَرَّاح بن عبدِ الله الحَكَمي مُقَدِّم الجُيوش، فارِس الكَتائِب. وَلِيَ البَصْرَة من جِهَة الحَجَّاج، ثمَّ وَلِيَ خُراسان وسِجِسْتان لعُمَر بن عبدِ العزيز. وكان بَطلًا، شُجاعًا, عابِدًا، قارِئًا, كَبيرَ القَدْرِ, مَهيبًا طُوالًا، كان إذا مَرَّ في جامِع دِمَشق يَميلُ رَأسَه عن القَنادِيل مِن طُولِه. قال الجَرَّاح: تَرَكتُ الذُّنوبَ حَياءً أربعين سَنة، ثمَّ أَدْرَكَنِي الوَرَعُ. كان أَميرًا على أرمينية، فقَتَلَتْهُ الخَزَرُ، ففَزِعَ النَّاسُ لِقَتْلِه في البُلدان, ولمَّا قُتِلَ طَمِعَ الخَزَرُ في المسلمين وأَوْغَلوا في البِلادِ، وغَلَبَت الخَزَر على أذربيجان، حتَّى بَلَغوا قَريبًا مِن المَوْصِل. كان البَلاءُ بِمَقْتَلِه على المسلمين عَظيمًا، بَكَوا عليه في كُلِّ جُنْدٍ. كان رَحِمَه الله خَيِّرًا فاضِلًا صالِحًا، رَثاهُ كَثيرٌ مِن الشُّعَراء."},{"id":436,"title":"مُعاوِيَةُ بن هِشام يَغزو الرُّومَ  .","date":["العام الهجري :113","العام الميلادي :731"],"text":"غَزَا مُعاوِيَةُ بن هِشام أَرضَ الرُّومَ مِن ناحِيَة مَرْعَش."},{"id":437,"title":"مَسْلمَة بن عبدِ الملك يَتَوغَّل في بِلادِ التُّرْك .","date":["العام الهجري :113","العام الميلادي :731"],"text":"تَوَغَّلَ مَسلمَةُ بن عبدِ الملك في بِلاد التُّرْكِ فقَتَل منهم خَلْقًا كَثيرًا، ودانَت له تلك المَمالِك مِن ناحِيَة بَلَنْجَر وأَعْمالِها."},{"id":438,"title":"عبدُ الرَّحمن الغافِقِيُّ يَتَوَلَّى إِمارةَ الأَندَلُس ويَغزو بِلادَ الفِرِنْجَة .","date":["العام الهجري :114","العام الميلادي :732"],"text":"تَوَلَّى عبدُ الرَّحمن الغافِقِيُّ أُمورَ القِيادَةِ على الشَّاطِئ الشَّرقيِّ مِن الأَندَلُس مِن قِبَل عُبيدَة بن عبدِ الرَّحمن القَيْسِي صاحِب أفريقيا في عَهْدِ هِشامِ بن عبدِ الملك مُدَّةَ سَنتينِ ونِصف، وطِيلَة تلك المُدَد كان يَقوم بالغَزْوِ والفَتْح، وكانت انْتِصاراتُه على البَرْبَر مَشهودَةً، وساعَد على ذلك حُسْنُ مُعامَلتِه للبَرْبَر ممَّا كان له الأَثَر الكَبير في دُخولِ كَثيرٍ منهم إلى الإسلام، وقاتَل معه الكَثيرُ في حُروبِه وكان عبدُ الرَّحمن قد أَوْغَل داخِل فَرنسا ثمَّ بَقِيَ كذلك حتَّى حَصَلت مَعركَة بَلاط الشُّهَداء التي اسْتُشْهِد فيها هو وكَثيرٌ ممَّن كان معه."},{"id":439,"title":"هَزيمَة المسلمين في مَعركَة بَلاط الشُّهَداء .","date":["العام الهجري :114","الشهر القمري : رمضان","العام الميلادي :732"],"text":"وَلَّى هِشامُ بن عبدِ الملك عبدَ الرَّحمن الغافِقِي إمارَةَ الأَندَلُس فتَأَهَّبَ لِفَتحِ بِلادِ الغال (فرنسا) فدَعا العَرَبَ مِن اليَمَن والشَّام إلى مُناصَرَتِه فأَقْبَلوا إليه، فاجْتاز جِبالَ البِرانس بجَيْشٍ مِن العَرَب والبَرْبَر، وأَوْغَل في مُقاطَعَتي اكيتانيا ووبرغونية وبوردو، ثمَّ تَقدَّم يُريدُ الإيغال داخِلَ البِلادِ، فجَمَع له شارل مارتل جُموعَه وأَلَّفَ جَيشًا كَبيرًا مِن الغاليين والجرمن فنَشَبَت حَرْبٌ دامِيَة شَديدَة في بواتيه بِقُرْبِ نَهرِ اللوار، وقد اسْتُشْهِد فيها عبدُ الرَّحمن الغافِقِي ومعه الكَثيرُ مِن جَيشِه الذي هُزِمَ وانْسَحَب لَيلًا ولم يَبْق للمسلمين في بِلادِ الغال سِوى مُقاطَعة سبتمانيا."},{"id":440,"title":"وُقوعُ طاعونٍ بالشَّام وقَحْطٍ بخُراسان .","date":["العام الهجري :115","العام الميلادي :733"],"text":"في هذه السَّنَة وَقَع الطَّاعون بالشَّام، وفيها وَقَع بخُراسان قَحْطٌ شَديدٌ، فكَتَب الجُنيدُ المُرِّيُّ إلى الكور بِحَمْلِ الطَّعام إلى مَرْو، أَعْطَى الجُنيدُ رَجُلًا دِرْهَمًا فاشْتَرَى به رَغيفًا، فقال لهم أَتَشْكون الجُوعَ ورَغيفٌ بِدِرْهَم؟ لقد رَأَيْتُني بالهِنْدِ وإنَّ الحَبَّة مِن الحُبوب لَتُباع عددًا بِدِرْهَم."},{"id":441,"title":"تَوَلِّي مَرْوان بن محمَّد أرمينية والجَزيرَة وأذربيجان .","date":["العام الهجري :116","العام الميلادي :734"],"text":"اسْتَعمَل هِشامُ بن عبدِ الملك مَرْوانَ بن محمَّد بن مَرْوان -وهو ابنُ عَمِّه- على الجَزيرَة الفراتية وأذربيجان وأرمينية، وكان سَبَبُ ذلك أن مَرْوان بن محمَّد قال لهِشام: قد كان مِن دُخولِ الخَزَر إلى بِلادِ الإسلام وقَتْل الجَرَّاح وغَيرِه مِن المسلمين ما دَخَل به الوَهَنُ على المسلمين, أنَّ مَسلمَة بن عبد الملك، ما وَطِئ مِن بِلادِهم إلَّا أَدْناها، وكان قُصاراه السَّلامَة، وقد أَردتُ أن تَأذَن لي في غَزْوَةٍ أُذْهِبُ بها عَنَّا العارَ، وأَنْتَقِمُ مِن العَدُوِّ. فأَذِنَ له واسْتَعمَله على أرمينية, فسار إلى أرمينية والِيًا عليها، وسَيَّرَ هِشامٌ الجُنودَ مِن الشَّامِ والعِراقِ والجَزيرَة، فاجْتَمَع عِندَه مِن الجُنودِ والمُتَطَوِّعَة مائة وعشرون ألفًا، فأَظْهَر أنَّه يُريدُ غَزْوَ اللَّان وقَصَد بِلادَهم، وأَرسَل إلى مَلِك الخَزَر يَطلُب منه المُهادَنَة، فأَجابَه إلى ذلك، وأَرسَل إليه مَن يُقرِّرُ الصُّلْحَ، فأَمسَك الرَّسولَ عنده إلى أن فَرَغ مِن جِهازِه وما يُريدُ، ثمَّ أَغْلَظ لهم القَوْلَ وآذَنَهم بالحَرْبِ، وسَيَّرَ الرَّسولَ إلى صاحِبِه بذلك، فما وَصَل الرَّسولُ إلى صاحِبِه إلَّا ومَرْوان قد وافاهُم، فأَعْلَم صاحِبَه الخَبَرَ، وأَخبَره بما جَمَع له مَرْوان وحَشَد واسْتَعَدَّ. فاسْتَشار مَلِكُ الخَزَر أَصحابَه، فقالوا: إنَّ هذا قد اغْتَرَّكَ ودَخَل بِلادَك، فإن أَقَمْتَ إلى أن تَجْمَع لم يَجْتَمِع عندك إلى مُدَّة فيَبْلُغ مِنك ما يُريد، وإن أنت لَقِيتَه على حالِك هذه هَزَمَك وظَفَر بك، والرَّأيُ أن تَتَأَخَّر إلى أَقْصَى بِلادِك وتَدَعَه وما يُريدُ. فقَبِلَ رَأيَهم وسار حيث أَمَروه. ودَخَل مَرْوان بِلادَهم وأَوْغَل فيها وأَخْرَبَها، وغَنِمَ وسَبَى وانْتَهي إلى آخِرِها وأَقام فيها عِدَّةَ أيَّامٍ حتَّى أَذَلَّهم وانْتَقَم منهم، ودَخَل بِلادَ مَلِك السَّرير فأَوْقَع بِأَهلِه، وفَتَح قِلاعًا، ودان له المَلِكُ، وصالَحه على ألفِ رَأسٍ، وخمسمائة غُلام، وخمسمائة جارِيَة سُود الشُّعور، ومائة ألف مُدْيٍ تُحْمَل إلى البابِ، وصالَح مَرْوان أهلَ تومان على مائة رَأسٍ، وعشرين ألف مُدْيٍ، ثمَّ دَخَل أَرضَ زريكران، فصالَحَه مَلِكُها، ثمَّ أَتَى إلى أَرضِ حمزين، فأبى حمزين أن يُصالِحَه، فحَصَرَهُم فافْتَتَح حِصْنَهم، ثمَّ أَتَى سغدان فافْتَتَحَها صُلْحًا، ووَظَّفَ على طيرشانشاه عشرة آلاف مُدْيٍ كُلَّ سَنة تُحْمَل إلى البابِ، ثمَّ نَزَل على قَلْعَة صاحِب اللكز، وقد امْتَنَع من أَداءِ الوَظيفَة، فخَرَج مَلِكُ اللكز يُريد مَلِكَ الخَزَر، فقَتَله راعٍ بِسَهْمٍ وهو لا يَعرِفُه، فصالَح أَهلُ اللكز مَرْوانَ، واسْتَعْمَل عليهم عامِلًا، وسار إلى قَلعَة شروان، وهي على البَحرِ، فأَذْعَن بالطَّاعَة، وسار إلى الدّوداني فأَقْلَع بهم ثمَّ عاد."},{"id":442,"title":"ثَورةُ بِلادِ ما وَراء النَّهرِ على الأُمَويِّين .","date":["العام الهجري :116","العام الميلادي :734"],"text":"غَضِبَ هِشامُ بن عبدِ الملك على أَميرِ خُراسان الجُنيدِ المُرِّيِّ فوَلَّى بَدَلًا عنه عاصِمَ بن عبدِ الله الهِلالِيَّ، وأَمَره أن يَسيرَ إليه وأن يَقتُلَه إن وَجَده حَيًّا، وكان الجُنيدُ مَريضًا ومات قَبلَ وُصولِ عاصِمٍ، فلمَّا وَصَل عاصِمٌ أَخَذ بالإساءَةِ إلى قادَةِ الجُنيدِ وأَظهَر القَسوَة، ممَّا أَثار عليه النَّاس، فخَرَج عليه الحارِثُ بن سُريجٍ وسار إلى الفارياب، وسَيَّرَ إليه عاصِمٌ جَيشًا وحَصَل قِتالٌ بينهم في بَلْخ هُزِمَ فيه جَيشُ عاصِم، وسار الحارِثُ فاسْتَولى على عِدَّةِ مُدُن واجْتَمَع له الكَثيرُ مِن النَّاس وقَوِيَ أَمرُه، وقِيلَ إنَّه كان يَدعو إلى بَيْعَةِ الرِّضا."},{"id":443,"title":"غَزوُ مَرْوان بن محمَّد بن مَرْوان وارقيس  .","date":["العام الهجري :118","العام الميلادي :736"],"text":"غزا مَرْوانُ بن محمَّد بن مَرْوان مِن أرمينية ودخَل أرضَ وارقيس فهرَب وارقيس إلى الحرور ونزَل حِصنَه، فحَصَره مَرْوانُ ونصَب عليه المَجانيقَ، فقَتَل وارقيسَ بعضُ مَن اجتاز به وأَرسلَ رَأسَه إلى مَرْوان، فنَصبَه لأهلِ حِصنِه، فنزلوا على حُكمِه، فقَتَل المُقاتِلَة وسَبَى الذُّرِّيَّة."},{"id":444,"title":"وَفاةُ عبدِ الله بن عامِر أَحَد القُرَّاءِ السَّبْعَة .","date":["العام الهجري :118","الشهر القمري : محرم","العام الميلادي :736"],"text":"هو عبدُ الله بن عامِر بن يَزيدَ بن تَميمٍ اليَحْصُبِيُّ، أَحَدُ القُرَّاء السَّبعَة، إمامُ أَهلِ الشَّامِ في القِراءَةِ، والذي انْتَهت إليه مَشيَخَةُ الإقْراءِ بها، أَخَذ القِراءَةَ عَرَضًا عن أبي الدَّرْداء وعن المُغيرَة بن أبي شِهابٍ صاحِب عُثمان، وقِيلَ: عُرِضَ على عُثمان بن عَفَّان. ولا زال أَهلُ الشَّامِ قاطِبَةً على قِراءَةِ ابن عامِر تِلاوَةً وصَلاةً وتَلْقينًا إلى قَريبِ الخمسمائة، كان مِن أفاضِل المسلمين وخِيارِ التَّابِعين، ومِن أَجِلَّةِ الرُّواةِ، لا يُتَّهُم في دِينِه، ولا يُشَكُّ في يَقينِه، ولا يُرتابُ في أَمانَتِه، ولا يُطْعَن عليه في رِوايَتِه، وكان إمامَ الجامِع بِدِمَشق، وكان رَئيس الجامِع لا يَرَى فيه بِدْعَةً إلَّا غَيَّرَها، تُوفِّي بدِمَشق يومَ عاشوراء."},{"id":445,"title":"وَفاةُ عبدِ الله بن كَثيرٍ أَحدُ القُرَّاء السَّبعَة .","date":["العام الهجري :120","العام الميلادي :737"],"text":"هو عبدُ الله بن كَثيرِ بن عَمرِو بن عبدِ الله بن زاذان بن فيروزان، أَحَدُ القُرَّاء السَّبعَة، إمامُ أَهلِ مَكَّة في القِراءَةِ، ولَقِيَ فيها عددًا مِن الصَّحابَة، وكان فَصيحًا بَليغًا مُفَوَّهًا، أَبيضَ اللِّحْيَة، طَويلًا، جَسيمًا، أَسْمَر، أَشْهَلَ العَينينِ، يَخضِب بالحِنَّاء، عليه السَّكينَة والوَقار، تُوفِّي في مَكَّة."},{"id":446,"title":"هِشامُ بن عبدِ الملك يعَزل خالد القَسري عن أَعمالِه .","date":["العام الهجري :120","الشهر القمري : جمادى الأولى","العام الميلادي :738"],"text":"قام هِشامُ بن عبدِ الملك بِعَزلِ خالِدِ بن عبدِ الله القَسري البَجَلي ووَلَّى بَدلًا منه يُوسُف بن عُمَر الثَّقَفي، وقد اختَلفَت الرِّوايات بِشأنِ سَببِ عَزلِه."},{"id":447,"title":"التُّرك يُهاجِمون المسلمين بالقُربِ مِن نَهرِ بَلْخ  .","date":["العام الهجري :121","العام الميلادي :738"],"text":"سار أَسدُ بن عبدِ الله القَسري أَميرُ خُراسان بجُيوشِه إلى مَدينَة خُتَّل فافْتَتَحها، وتَفرَّقت في أَرضِها جُنودُه يَقتُلون ويَأسِرون ويَغنَمون، فجاءَت العُيونُ إلى مَلِك التُّركِ خاقان أنَّ جَيشَ أَسَد قد تَفرَّق في بِلادِ خُتَّل، فاغْتَنَم خاقان هذه الفُرصَة فرَكِب مِن فَوْرِه في جُنودِه قاصِدًا إلى أَسَد، وتَزَوَّد خاقان وأَصحابُه سِلاحًا كَثيرًا، وقَديدًا ومِلحًا، وساروا في خَلْقٍ عَظيمٍ، وجاء إلى أَسَد فأَعلَموه بِقَصدِ خاقان له في جَيشٍ عَظيمٍ كَثيفٍ، فتَجهَّز لذلك وأَخَذ أُهْبَتَهُ، فأَرسَل مِن فَوْرِه إلى أَطرافِ جَيشِه، فلَمَّها وأَشاعَ بَعضُ النَّاس أنَّ خاقان قد هَجَم على أَسدِ بن عبدِ الله فقَتلَه وأَصحابَه، لِيَحصُل بذلك خِذلانٌ لِأَصحابِه، فلا يَجتَمِعون إليه، فرَدَّ اللهُ كَيدَهم في نُحورِهم، وجَعَل تَدميرَهم في تَدبيرِهم، وذلك أنَّ المسلمين لمَّا سَمِعوا بذلك أَخَذتهم حَمِيَّةُ الإسلام وازدادوا حَنَقًا على عَدوِّهم، وعَزَموا على الأَخذِ بالثَّأرِ، فقَصَدوا المَوضِعَ الذي فيه أَسَد، فإذا هو حَيٌّ قد اجتَمعَت عليه العَساكِر مِن كُلِّ جانِب، وسار أَسَد نحو خاقان حتَّى أتى جَبَل المِلْح، وخاض نَهرَ بَلْخ ففاجَأَهُم التُّركُ مِن وَرائِهم وقَتَلوا منهم عَددًا ثمَّ بَقوا عِدَّةَ أَشهُر كذلك حتَّى الْتَقوا مَرَّةً أُخرى وَكَرَّ عليهم المسلمون وأَعمَلوا فيهم، وكان الحارثُ بن سُريج الذي خَرَج على عاصِم قد الْتَجَأ إلى خاقان التُّرك وحارَب معه وقد هَرَبا سَوِيًّا مِن هذه الحَرب وغَنِمَ المسلمون الكَثيرَ مِن أَموالِهم وأَمتِعَتِهم ودَوابِّهم."},{"id":448,"title":"انْتِفاضةُ زَيدِ بن عَلِيٍّ بالعِراق وظُهورُ طائِفَة الزَّيدِيَّة .","date":["العام الهجري :122","العام الميلادي :739"],"text":"لمَّا أَخَذ زَيدُ بن عَلِيٍّ زين العابدين بن الحُسينِ البَيْعَةَ ممَّن بايَعهُ مِن أَهلِ الكوفَة، أَمرَهم في أوَّلِ هذه السَّنَة بالخُروجِ والتَّأَهُّبِ له، فشَرَعوا في أَخذِ الأُهْبَةِ لذلك. فانطَلَق رَجلٌ يُقالُ له: سُليمان بن سُراقَة. إلى يُوسُف بن عُمَر الثَّقَفي نائِب العِراق فأَخبَره - وهو بالحِيرَةِ يَومَئذٍ - خَبَرَ زَيدِ بن عَلِيٍّ هذا ومَن معه مِن أَهلِ الكوفَة، فبَعَث يُوسُف بن عُمَر يَتَطلَّبه ويُلِحُّ في طَلَبِه، فلمَّا عَلِمَت الشِّيعَةُ ذلك اجْتَمعوا عند زَيدِ بن عَلِيٍّ فقالوا له: ما قَولُك -يَرحمُك الله- في أبي بَكرٍ وعُمَر؟ فقال: غَفَر اللهُ لهما، ما سَمِعتُ أَحدًا مِن أَهلِ بَيتِي تَبَرَّأَ منهما، وأنا لا أَقولُ فيها إلَّا خَيرًا، قالوا: فلِمَ تَطلُب إذًا بِدَمِ أَهلِ البَيت؟ فقال: إنَّا كُنَّا أَحَقَّ النَّاس بهذا الأَمرِ، ولكنَّ القَومَ اسْتَأثَروا علينا به ودَفَعونا عنه، ولم يَبلُغ ذلك عندنا بِهم كُفرًا، قد وُلُّوا فعَدَلوا، وعَمِلوا بالكِتابِ والسُّنَّة. قالوا: فلِمَ تُقاتِل هؤلاء إذًا؟ قال: إنَّ هؤلاء لَيسوا كأُولئِك، إنَّ هؤلاء ظَلَموا النَّاسَ وظَلَموا أَنفُسَهم، وإنِّي أَدعو إلى كِتابِ الله وسُنَّةِ نَبِيِّهِ صلَّى الله عليه وسلَّم، وإحياءِ السُّنَنِ وإماتَةِ البِدَع، فإنْ تَسمَعوا يكُن خَيرًا لكم وَلِي، وإنْ تَأْبَوا فلَستُ عليكم بِوَكيل فَرَفضوه وانصَرَفوا عنه، ونَقَضوا بَيْعَتَه وتَرَكوه، فلهذا سُمُّوا الرَّافِضَة مِن يَومِئذ، ومَن تابَعَه مِن النَّاس على قَولِه سُمُّوا الزَّيْدِيَّة ثمَّ إنَّ زَيدًا عَزَم على الخُروجِ بِمَن بَقِيَ معه مِن أَصحابِه، فَوَاعَدَهم لَيلةَ الأَربعاء مِن مُسْتَهَلِّ صَفَر، فبَلَغ ذلك يُوسُف فأَمَر عامِلَه بأن يَحبِس النَّاسَ في المَسجِد لَيلَتها حتَّى لا يَخرجوا إليه، ثمَّ خَرَج زَيدٌ مع الذين اجتمعوا معه فسار إليه نائِبُ الكوفَة الحَكَمُ وسار إليه يُوسُف بن عُمَر في جَيشٍ، وحَصل قِتالٌ في عِدَّةِ أَماكن بينهم حتَّى أُصيبَ زَيدٌ بِسَهم في جَبهَتِه ثمَّ دُفِن، ثمَّ جاء يُوسُف وأَخرَجَه وصَلَبَه، وقِيلَ: بَقِيَ كذلك طَويلًا ثمَّ أُنزِلَ وحُرِق، فما حصل لزيد بن علي هو نفس ما حصل للحسين بن علي رضي الله عنه في كربلاء."},{"id":449,"title":"ثورة البَرْبَر على العَرَب في المَغرِب الأَقصى .","date":["العام الهجري :122","العام الميلادي :739"],"text":"ثارت البَرْبَرُ بالمَغرِب فخَرَج مَيسَرة المدغري وقام على عُمَرَ بن عبدِ الله المُرادي بِطَنجَة فقَتَله وثارت البَرابِرُ مع أَميرِهم مَيسَرة الحَقير، ثمَّ خَلَّف مَيسَرةُ على طَنجَة عبدَ الأعلى بن حُدَيج، وزَحَف إلى إسماعيل بن عُبيدِ الله بن الحَبْحاب إلى السُّوس فقَتلَه، ثمَّ كانت وَقائعُ كَثيرةٌ بين أَهلِ المَغرِب الأقصى وأَهلِ أفريقيا، وكان المَغرِبُ حِينئذٍ قَومًا ظَهرَت فيهم دَعوةُ الخَوارِج، ولهم عَددٌ كَثيرٌ وشَوْكَة كَبيرَة، وهُم بِرْغَواطة وكان السَّببُ في ثَورةِ البَرْبَر وقِيامِ مَيسرَة إنها أَنكرَت على عامِل ابنِ الحَبْحاب سُوءَ سِيرَتِه، وكان الخُلَفاء بالمَشرِق يَستَحِبُّون طَرائفَ المَغرِب ويَبعَثون فيها إلى عامِل أفريقيا فيَبعَثون لهم البَرْبَر السنيات، فلمَّا أَفضى الأَمرُ إلى ابنِ الحَبْحاب مَنَّاهُم بالكَثيرِ وتَكلَّف لهم أو كَلَّفوه أَكثرَ ممَّا كان، فاضْطَرَّ إلى التَّعَسُّف وسُوءِ السِّيرَة، فحِينئذٍ عَدَت البَرابِرُ على عامِلِهم فقَتَلوه وثاروا بأَجمَعِهم على ابنِ الحَبْحاب."},{"id":450,"title":"مَوقِعَة أكرونيون وهَزيمَة المسلمين .","date":["العام الهجري :122","العام الميلادي :739"],"text":"خَرَج إليون مِن القُسطنطينيَّة ومعه مائةُ أَلفِ فارِس، فأُخبِرَ بذلك البَطَّال وهو عبدُ الله الأنطاكي فأَخبَر البَطَّالُ أَميرَ عَساكِر المسلمين بذلك، وكان الأَميرُ مالِك بن شَبيب، وقال له: المَصلَحةُ تَقتَضِي أن نَتحَصَّن في مَدينَة حَرَّان فنَكُون بها حتَّى يَقدُم علينا سُليمانُ بن هِشام بالمَدَد، فأَبَى عليه ذلك ودَهمَهم الجَيشُ، فاقْتَتَلوا قِتالًا شَديدًا والأَبطالُ تَحومُ بين يدي البَطَّال ولا يَتَجاسر أَحدٌ أن يُنَوِّه باسمِه خَوفًا عليه مِن الرُّوم، فاتَّفَق أن ناداهُ بَعضُهم وذَكَر اسمَه غَلَطًا منه، فلمَّا سمع ذلك فِرسانُ الرُّوم حَمَلوا عليه حَملةً واحِدةً، فاقْتَلعوه مِن سَرْجِه بِرِماحِهم فأَلقوه إلى الأَرضِ، ورَأى النَّاسَ يُقتَلون ويُأسَرون، وقُتِلَ الأميرُ الكَبيرُ مالِكُ بن شَبيب، وانكَسَر المسلمون وانطلقوا إلى تلك المدينة الخَراب فتَحَصَّنوا فيها، وانطَلَق ليون إلى المسلمين الذين تَحَصَّنوا فحاصَرَهم، فبينما هم في تلك الشِّدَّةِ والحِصار إذ جاءَتهُم البُرُدُ بِقُدومِ سُليمان بن هِشام بالمَدَدِ، ففَرَّ ليون في جَيشِه هارِبًا راجِعًا إلى بِلادِه -قَبَّحَهُ الله- فدَخَل القُسطنطينيَّة وتَحصَّن بها."},{"id":451,"title":"البَرْبَر يَنتصِرون في مَوقِعة الأَشراف بالمَغرِب .","date":["العام الهجري :123","العام الميلادي :740"],"text":"بعدَ أن تَفَشَّت الخَوارِج في المَغرِب وهُم الصُّفْرِيَّة وَلَّوْا عليهم مَيسرَة المدغري المعروف بِمَيسرَة الحَقير، فأَعلَن الثَّورَةَ على عُبيدِالله بن الحَبْحاب فاستولى على طَنجَة وقَتَل عامِلَها عُمَرَ بن عبدِ الله المُرادي ووَلَّى عبدَ الأعلى الرُّومي، فتَوَجَّه الأَخيرُ إلى السُّوس لِقِتال إسماعيل بن عُبيدِ الله بن الحَبْحاب، وكان أَبُوه وَلَّاه على السُّوس، وقُتِلَ في المعركة عبدُ الأعلى فسَيَّرَ مَيسرَة لِقِتالِ إسماعيل على رَأسِ جَيشٍ مِن البَرْبَر فقاتَلوا وقَتَلوا إسماعيل، فوَجَّه عُبيدُ الله بن الحَبْحاب جَيشًا بِقِيادَة خالد بن أبي عُبيدَة الفِهري لِقِتالِ مَيسرَة فتَحاجَز الفَريقان وعاد مَيسرَةُ إلى طَنجَة فنَقِمَ عليه البَرْبَرُ وقَتَلوه ووَلَّوْا عليهم خالدَ بن حُميد الزَّناتي فالْتَقى جَيشُ البَرْبَر مع جَيشِ خالد الفِهري بالقُربِ مِن طَنجَة فكانت مَعركةً ضارِيةً شَديدةً كانت نَتيجَتُها هَزيمةَ جَيشِ خالد الفِهري وقَتْلَ الكَثيرِ منهم، وسُمِّيَت وَقعةَ الأَشراف لِكَثَرةِ الأشراف في جَيشِ خالد الفِهري والذين قُتِلَ الكَثيرُ منهم."},{"id":452,"title":"نَصرِ بن سِيار يغزو التُّرك، ويأَسْر مَلكهم كور صول .","date":["العام الهجري :123","العام الميلادي :740"],"text":"غَزا نَصرُ بن سِيار أَميرُ خُراسان غَزَوات مُتعدِّدَة في التُّرك، وأَسَرَ مَلِكَهم كور صول في بَعضِ تلك الحُروب وهو لا يَعرِفُه، فلمَّا تَيَقَّنه وتَحَقَّقه، سأَل منه كور صول أن يُطلِقَه على أن يُرسِلَ له أَلفَ بَعير مِن إِبِل التُّرك -وهي البَخاتي- وأَلفَ بِرْذَون، وهو مع ذلك شَيخٌ كَبيرٌ جِدًّا، فشاوَرَ نَصرُ مَن بِحَضرَتِه مِن الأُمراء في ذلك، فمنهم مَن أشار بإطلاقه، ومنهم مَن أشار بِقَتلِه. ثمَّ سأله نَصرُ بن سِيار كم غَزوَتَ مِن غَزوَة؟ فقال: ثِنْتَينِ وسبعين غَزوَة. فقال له نَصر: ما مِثلُك يُطلَق، وقد شَهِدتَ هذا كُلَّه. ثمَّ أَمَر به فضُرِبَت عُنقُه وصَلَبَه، فلمَّا بَلَغ ذلك جَيشَه مِن قَتلِه باتوا تلك اللَّيلةَ يَجْعَرُون ويَبْكون عليه، وجَذُّوا لِحاهُم وشُعورَهم وقَطَعوا آذانَهم وحَرَقوا خِيامًا كَثيرة، وقَتَلوا أَنعامًا كَثيرَة، فلمَّا أَصبحَ أَمَرَ نَصرٌ بإِحراقِه لِئَلَّا يأخذوا جُثَّتَه، فكان حَرقُه أَشَدَّ عليهم مِن قَتلِه، وانصرفوا خائِبين صاغِرين خاسِرين، ثمَّ كَرَّ نَصر على بِلادِهم فقَتَل منهم خَلقًا وأَسَر أُمَمًا لا يُحصون كَثرَةً."},{"id":453,"title":"ظُهورُ الدَّعوَة العَبَّاسِيَّة وتَكامُل أُسُسِها .","date":["العام الهجري :124","العام الميلادي :741"],"text":"كان بَدءُ الدَّعوَة مِن قِبَل محمَّد بن عَلِيِّ بن عبدِ الله بن عَبَّاس، ووَصَلت الدَّعوة إلى خُراسان، ثمَّ لمَّا تُوفِّي محمَّد بن عَلِيٍّ في عام 124 هـ سار بالأَمرِ مِن بَعدِه ابنُه إبراهيمُ وساعَد في قُوَّةِ الأَمرِ ظُهورُ أبي مُسلِم الخُراساني الذي كان يَخدِمُ في سِجْنِ يُوسُف بن عُمَر أَحدَ المَسجونين بِتُهمَةِ الدَّعوَة العَبَّاسِيَّة وكان بُكيرُ بن ماهان أَحَدَ الدُّعاة الكِبار للدَّعوَةِ العَبَّاسِيَّة في خُراسان قد اشْتَراهُ أبا مُسلِم وأَرسلَه إلى إبراهيم بن محمَّد فأَعطاهُ لأبي موسى السَّرَّاج لِيُؤَدِّبَه فسَمِعَ منه وحَفِظ، وقِيلَ غير ذلك في نَسَبِ أبي مُسلِم، وقِيلَ: إنَّ إبراهيم طَلَب منه تَغيير اسْمِه حتَّى تَتَمكَّن الدَّعوة العَبَّاسِيَّة فالله أعلم."},{"id":454,"title":"وَفاةُ ابنِ شِهاب الزُّهري .","date":["العام الهجري :124","الشهر القمري : رمضان","العام الميلادي :742"],"text":"هو محمَّدُ بن مُسلِم بن عُبيدِ الله بن شِهاب الزُّهري، أوَّلُ مَن دَوَّنَ الحَديثَ، أَحدُ كِبارِ الحُفَّاظ والفُقَهاء، حَدَّث عن عَددٍ مِن الصَّحابة كَأَنَسٍ وابنِ عُمَر، وأَرسَل عن النَّبِيِّ صلَّى الله عليه وسلَّم أَحاديثَ كَثيرَة، كان مِن مَشاهير القُرَّاء، له مُؤَلَّفات في المَغازي والتَّاريخ والقُرآن، اسْتَقَرَّ في الشَّام وبَقِيَ إلى أن قِيلَ ليس في الدُّنيا له نَظير، تُوفِّي في قَريَةِ شَغْب أوَّل حُدودِ فِلَسطين مع الحِجاز، فرَحِمَه الله تَعالى وجَزاهُ عن الإسلامِ والمسلمين خَيرًا."},{"id":455,"title":"قَتلُ الجَعْدِ بن دِرهَم رَأسِ طائفة المُعَطِّلَة .","date":["العام الهجري :124","الشهر القمري : ذي الحجة","العام الميلادي :742"],"text":"هو الجَعْدُ بن دِرهَم، رَأسُ المُعَطِّلَة، أَصلُه مِن خُراسان، أَسلَم أَبوهُ وصار مِن مَوالي بَنِي مَرْوان، وقد وُلِدَ في خُراسان وهاجَر بعدَ ذلك إلى دِمَشق حيث أقام هناك، وهو أوَّلُ مَن ابْتَدَع: أن الله ما اتَّخَذَ إبراهيمَ خَليلًا، ولا كَلَّمَ موسى، وأن ذلك لا يَجوزُ على الله. كان الجَعْدُ زِنْديقًا، شَهِدَ عليه مَيمونُ بن مِهران، فطَلَبَه هِشام، فظَفَر به، وسَيَّرَهُ إلى خالدِ بن عبدِ الله القَسري في العِراق فقَتَلَه يومَ النَّحْر، ومنه أَخَذ الجَهْمُ بن صَفوان مَقالَتَه في التَّعطيل."},{"id":456,"title":"وَفاةُ الخَليفَة الأُموي هِشامِ بن عبدِ الملك .","date":["العام الهجري :125","الشهر القمري : ربيع الآخر","العام الميلادي :743"],"text":"هو هِشامُ بن عبدِ الملك بن مَرْوان بن الحَكَم بن أبي العاص بن أُمَيَّة بن عبدِ شَمسٍ، أبو الوَليد القُرَشي الأُمَوي الدِّمَشقي، أَميرُ المؤمنين، بُويِعَ له بالخِلافَة بعدَ أَخيهِ يَزيد بن عبدِ الملك بِعَهْدٍ منه إليه، وذلك يوم الجُمُعة لِأَربعٍ بَقِينَ مِن شَعبان سَنةَ خمَسٍ ومائة، وكان له مِن العُمُر يَومئذٍ أربعٌ وثَلاثون سَنَة، وكان جَميلًا أَبيضَ أَحْوَل، يَخضِبُ بالسَّواد، وهو الرَّابعُ مِن وَلَدِ عبدِ الملك لِصُلْبِه الذين وَلُوا الخِلافَة، فكان هِشام آخِرَهم، وكان في خِلافَتِه حازِمُ الرَّأي، وكان ذَكِيًّا مُدَبِّرًا للأمور، له بَصَرٌ بها جَليلِها وحَقيرِها، اشْتَهَرَ هِشام في خِلافَتِه بالحِلْمِ والعِفَّة، وكان قد نَظَّمَ الدَّواوينَ وزاد في مَوارِدِ الدَّولَة، لم يكُن أَحَدٌ مِن بَنِي مَرْوان أَشَدَّ نَظَرًا في أَمرِ أَصحابِه ودَواوينِه، ولا أَشَدَّ مُبالغةً في الفَحصِ عنهم مِن هِشام. أَمرَ بِقَتلِ غَيلان القَدَري. يُؤخَذ عليه تَغافلُه عن دُعاةِ بَنِي العَبَّاس الذين نَشَطوا في عَهدِه، ولَعلَّ كَراهيَة هِشام للعُنفِ وسَفْك الدِّماء كانت سَببًا في تَغاضِيه عنهم حتَّى اسْتَفحَل أَمرُهم قُبيلَ وَفاتِه، بحيث لم يَستَطِع خُلفاؤه وَقْفَ مَدِّ الدَّعوة العَبَّاسِيَّة؛ لذا لمَّا مات هِشام اضْطرَب مُلْكُ بني أُمَيَّة، بَقي في الخِلافَة عشرين سَنَة إلَّا شَهرين، وصلَّى عليه ابنُه مَسلَمة، ودُفِنَ في الرُّصافَة."},{"id":457,"title":"الوَليدُ بن يَزيد يَتَوَلَّى الخِلافَة الأُمويَّة .","date":["العام الهجري :125","الشهر القمري : ربيع الآخر","العام الميلادي :743"],"text":"كان يَزيدُ بن عبدِ الملك قد عَهِدَ الأمرَ مِن بَعدِه لأَخيهِ هِشام ثمَّ لابنِه الوَليد مِن بَعدِه، وكان الوَليدُ بن يَزيد ماجِنًا غارِقًا في شُربِ الخَمرِ، حاوَل عَمَّه هِشامٌ أَكثرَ مِن مَرَّة عَزْلَة مِن الخِلافَة لكنَّه لم يَفعل, فلمَّا تُوفِّي هِشام بُويِعَ بالخِلافَة للوَليدِ بن يزيد وعُمُره خمسٌ وثَلاثون سَنَة. أَكثَر الوَليدُ بن يَزيد العَطاءَ للنَّاس, وسار في النَّاس سِيرَةً حَسنَة في بِدايَةِ خِلافَتِه فاسْتَوثَقَت له الأَقاليمُ بالبَيْعَة, لكن غَلَبَ عليه مُجونُه ومُعاقَرتُه للخَمرَة."},{"id":458,"title":"تولي أبو الخَطَّار وِلايةُ الأَندَلُس .","date":["العام الهجري :125","الشهر القمري : رجب","العام الميلادي :743"],"text":"كان أبو الخَطَّار لمَّا بايَعَ وُلاةَ الأندَلُس مِن قَيسٍ قد قال شِعرًا وعَرَّض فيه بِيَومِ مَرْج راهِط، وما كان مِن بَلاءِ كَلْبٍ فيها مع مَرْوان بن الحَكَم، وقِيام القَيْسِيِّين مع الضَّحَّاك بن قَيسٍ الفِهري على مَرْوان, فلمَّا بَلَغ شِعرُه هِشامَ بن عبدِ الملك عَلِم أنَّه رَجلٌ مِن كَلْبٍ، وكان هِشام قد استَعمَل على أفريقيا حَنضَلة بن صَفوان الكَلْبي سَنَة أربع وعشرين ومائة، فكَتَب إليه هِشامٌ أن يُوَلِّي الخَطَّارَ الأندَلُس، فوَلَّاه وسَيَّرهُ إليها."},{"id":459,"title":"اغْتِيالُ الخَليفَة الأُمَوي الوَليد بن يَزيد .","date":["العام الهجري :126","الشهر القمري : جمادى الآخرة","العام الميلادي :744"],"text":"لمَّا تَوَلَّى الوليدُ بن يَزيد بن عبدِ الملك الخِلافَة سار في أوَّلِ أَمرِه سِيرَةً حَسنَة مع أنَّه كان قد اشْتُهِرَ عنه أنَّه صاحِبُ شَرابٍ، ولكن الذي وَلَّد النِّقمَة عليه أنَّه عَقَد لِوَلدَيْهِ بالخِلافَة مِن بَعدِه الحَكَم وعُثمان، وهُما لم يَبلُغا سِنَّ الرُّشْد بعدُ، كما أَسرَف في شَرابِه وانْتِهاك المُحَرَّمات فثَقُلَ ذلك على النَّاس ونَقِموا عليه ممَّا حَداهم إلى أن بايَعوا سِرًّا لابنِ عَمِّه يَزيد بن الوَليد، فنادى يَزيدُ بِخَلعِ الوَليد الذي كان غائِبًا في عَمَّان الأردن، وكان قد وَضَع نائِبًا له على دِمَشق ففَرَّ منها وأَرسَل يَزيدُ جماعةً مِن أَصحابِه بِقِيادة عبدِ العزيز بن الحَجَّاج بن عبدِ الملك إلى الوَليد بن يَزيد فقَتَلوه في قَصرِه البَخْراء الذي كان للنُّعمانِ بن بَشير، فكانت مُدَّةُ خِلافَتِه سَنَة وثلاثة أَشهُر تَقريبًا."},{"id":460,"title":"يزيد بن الوليد بن عبد الملك (الناقص) يَتَوَلَّى الخِلافَة .","date":["العام الهجري :126","الشهر القمري : جمادى الآخرة","العام الميلادي :744"],"text":"بُويِعَ لِيَزيد بن الوَليدِ الذي يُقالُ له: النَّاقِص، وإنَّما سُمِّيَ النَّاقِصَ لأنَّه نَقَصَ الزِّيادَة التي كان الوَليدُ زادَها في عَطِيَّاتِ النَّاس، وهي عشرة عشرة، ورَدَّ العَطاءَ إلى ما كان أيَّام هِشام، لمَّا قُتِلَ الوليد بن يَزيد خَطَب يَزيدُ بن وَليد النَّاسَ فذَمَّ الوَليدَ بن يَزيد وأنَّه قَتلَه لِفِعلِه الخَبيث. قال: (... ظَهَر الجَبَّارُ العَنيد، المُستَحِلُّ الحُرْمَة، والرَّاكِب البِدعَة، والمُغَيِّر السُّنَّة، فلمَّا رأيتُ ذَلِكَ أَشفَقتُ إذ غَشِيَتكم ظُلْمَة لا تَقلَع عَنكم عَلَى كَثرَةٍ مِن ذُنوبِكم، وقَسوَةٍ مِن قُلوبِكم، وأَشفَقتُ أن يَدعو كَثيرٌ مِن النَّاس إِلَى ما هُوَ عَليهِ، فيُجيبُه مَن أَجابَه مِنكم، فاستَخرتُ اللَّه فِي أَمرِي، وسَألتُه ألا يِكِلَني إِلَى نَفسِي، ودَعوتُ إلى ذلك مَن أَجابَني مِن أَهلِي وأَهلِ وِلايَتِي، وهو ابْنُ عَمِّي فِي نَسَبي وكُفْئِي فِي حَسَبي، فأَراحَ اللَّه مِنه العِبادَ، وطَهَّر مِنه البِلادَ، وِلايَةً مِن اللَّه، وعَونًا بِلا حَوْلٍ مِنَّا ولا قُوَّة، ولكن بِحَوْلِ اللَّه وقُوَّتِه ووِلايَتِه وعَوْنِه. ثمَّ قال: أيُّها النَّاس إنَّ لكم عَليَّ أن لا أَضَعَ حَجرًا على حَجَر ولا لَبِنَة، ولا أَكتَري نَهرًا، ولا أُكثِر مالًا، ولا أُعطِيَه زَوجةً ووَلدًا، ولا أَنقُل مالًا عن بَلدٍ حتَّى أَسُدَّ ثَغرَه وخَصاصَة أَهلِه بما يُغنيهم، فما فَضَل نَقلتُه إلى البَلدِ الذي يَليهِ، ولا أُجَمِّرَكُم في ثُغورِكم فأَفتِنَكم، ولا أُغلِق بابي دونكم، ولا أَحمِل على أَهلِ جِزْيَتِكم، ولكم أُعطِياتُكم كُلَّ سَنَة، وأَرزاقُكم في كُلِّ شَهر حتَّى يكونَ أَقصاكُم كَأدناكُم، فإن وَفَّيتُ لكم بما قلتُ فعليكم السَّمعُ والطَّاعة وحُسْنُ الوِزارَة، وإن لم أَفِ فلكم أن تَخلَعوني إلَّا أن أَتوبَ، وإن عَلِمتُم أَحدًا ممَّن يُعرَف بالصَّلاح يُعطيكم مِن نَفسِه مِثلَ ما أُعطيكم وأَردتُم أن تُبايِعوه فأنا أوَّلُ مَن يُبايعهُ. أيُّها النَّاس لا طاعةَ لِمَخلوقٍ في مَعصِيةِ الخالِق)."},{"id":461,"title":"بداية الانقسام والاختلاف بين بني أمية .","date":["العام الهجري :126","الشهر القمري : جمادى الآخرة","العام الميلادي :744"],"text":"لمَّا استَلَم يَزيدُ بن الوَليدِ الخِلافَة بعدَ أن قُتلَ ابنُ عَمِّه الوَليد بن يَزيد اضْطَربَت الأُمور عليه واختَلفَت كَلمةُ بَنِي مَرْوان، وخرج سُليمانُ بن هِشام مِن السِّجْن واسْتَولى على الأَموالِ، وكان في سِجْن الوَليد بن يَزيد في عَمَّان ثمَّ حَضَر دِمَشق، وثار أَهلُ حِمص يُطالِبون بِدَمِ الوَليد بن يَزيد وخَلعَوا أَميرَهم، وثار أَهلُ فِلَسطين وبايَعوا يَزيدَ بن سُليمان، وأَهلُ الأردن كذلك ثاروا وبايَعوا محمَّدَ بن عبدِ الملك، وكان مَرْوان بن محمَّد في أرمينية يُحرِّض على الأَخذِ بِدَمِ الوَليد بن يَزيد، ثمَّ إنَّ يَزيد بن الوليد بايَعَ لأَخيهِ إِبراهيم مِن بَعدِه ومِن بَعدِه لِعبدِ العزيز بن الحَجَّاج؛ ولكن لم يَلبَث أن تُوفِّي يَزيد بالطَّاعون في 7 ذي الحِجَّة مِن العام نَفسِه فلم تَدُم خِلافتُه أَكثرَ مِن سِتَّة أَشهُر."},{"id":462,"title":"تَوَلِّي مَرْوان بن محمَّد الخِلافَة بعدَ قَتلِ إبراهيم بن الوَليد .","date":["العام الهجري :127","العام الميلادي :744"],"text":"لمَّا تُوفِّي يَزيدُ بن الوليد وكان قد عَهِدَ لأَخيهِ إبراهيم، فلمَّا سَمِع مَرْوانُ بن محمَّد بن عبدِ الملك بذلك، واسْتِلام إبراهيم بن الوَليد، قَفَل مِن خُرسان بالجزيرة وسار إلى دِمَشق وأَخَذ البَيْعَة لِنَفسِه، فمالَ إليه مِن قِنِّسرين ومِن حِمص الكثيرُ، ثمَّ جَرَت مَعركةٌ بينه وبين جُنْدِ إبراهيم انْتَصَر فيها مَرْوان، ثمَّ لمَّا وَصَل لِدِمَشق هَرَب إبراهيم وقَتَله عبدُ العزيز بن الحَجَّاج، فلم تَدُم خِلافَة إبراهيم سِوَى سبعين يومًا، ثمَّ بُويِعَ بالخِلافَة لمَرْوان بعدَ أن قُتِلَ وَلدَا الوَليدِ: الحَكَمُ وعُثمانُ، ثمَّ استَقرَّت له الأُمورُ شيئًا فشيئًا."},{"id":463,"title":"تتابع الثَوَرات على مَرْوان بن محمَّد وبَنِي أُميَّة .","date":["العام الهجري :127","العام الميلادي :744"],"text":"في هذه السَّنَة ثارَ بعضُ اليَمانِيَّة على مَرْوان بن محمَّد في حِمص وتَدمُر وكذلك في فِلَسطين، فقام بإرسالِ مَن يَقمَعُهم مُستَعينًا بالقَيْسِيَّة، كما خَرَج في الكوفَة عبدُ الله بن مُعاوِيَة الطَّالِبي على بَنِي أُميَّة وبايَعَه بعضُ أَصحابِه ثمَّ هَرَب معهم إلى حلوان وغَلَب على الرَّيِّ وأَصبَهان وهَمدان، وفي الأندَلُس ثارَ بعضُ القَيْسِيَّة بقِيادَة ثَوابَة بن سَلامَة الذي تَولَّى بعدُ إِمارةَ الأندَلُس."},{"id":464,"title":"وَفاةُ عاصِم بن أبي النُّجودِ أَحَدُ القُرَّاء السَّبعَة  .","date":["العام الهجري :127","العام الميلادي :744"],"text":"هو عاصِمُ بن بَهْدَلَة أبي النُّجودِ، أَحَدُ القُرَّاء السَّبعَة، وهو مِن صِغارِ التَّابعين، لَقِيَ عاصِمٌ بعضَ صَحابَة رَسولِ الله صلَّى الله عليه وسلَّم وأَخَذ عنهم، كالحارِث بن حَسَّان البَكري الذُّهلي رضي الله عنه، ورِفاعَة بن يَثْرِبي التَّميمي رضي الله عنه، انتَهَت إليه رِئاسَةُ الإقْراء بالكوفَة بعدَ أبي عبدِ الرَّحمن السُّلَمي في مَوضِعه، جَمَع بين الفَصاحَة والإتقانَ والتَّحريرَ والتَّجويدَ، وكان أَحسنَ النَّاسِ صَوتًا بالقُرآن، والقِراءَة المَشهورَة اليوم في أَكثرِ الأمصارِ هي عن حَفْص عن عاصِم هذا، تُوفِّي في الكوفَة."},{"id":465,"title":"خَلْعُ أبي الخَطَّار أَميرِ الأندَلُس .","date":["العام الهجري :127","العام الميلادي :744"],"text":"كان سَببُ ذلك أنَّه لمَّا قَدِمَ الأندَلُس أَميرًا أَظهَر العَصبِيَّة لليَمانِيَّة على المُضَرِيَّة، فاتَّفَق في بعضِ الأيَّام أنَّه اختَصَم رَجلٌ مِن كِنانَة ورَجلٌ مِن غَسَّان، فاسْتَعان الكِنانيُّ بالصُّمَيلِ بن حاتِم بن ذي الجَوْشَن الضَّبابي، فكلَّم فيه أبا الخطَّار، فاسْتَغلَظ له أبو الخطَّار، فأجابه الصُّمَيل، فأُمِرَ به فأُقِيمَ وضُرِب قَفاهُ، فمالَت عِمامتُه، فلمَّا خرَج قِيلَ له: نَرَى عِمامَتك مالَت! فقال: إن كان لي قومٌ فسَيُقِيمُونَها. وكان الصُّمَيْلُ مِن أَشرافِ مُضَر، فلمَّا جَرى له ذلك جَمَعَ قَومَه وأَعلمَهم، فقالوا له: نحن تَبَعٌ لك. قال: أُريدُ أن أُخرِجَ أبا الخَطَّار مِن الأندَلُس. فقال له بعضُ أَصحابِه: افْعَل واسْتَعِن بمَن شِئتَ ولا تَسْتَعِن بأبي عَطاء القَيسي. وكان مِن أَشرافِ قَيس، وكان يَنظُر الصُّميلَ في الرِّياسَة ويَحسُده. وقال له غيرُه: الرَّأيُ أنَّك تأتي أبا عَطاء وتَشُدُّ أَمرَك به فإنَّه تُحرِّكُه الحَمِيَّة ويَنصُرك، وإن تَركتَه مال إلى أبي الخَطَّار وأَعانَه عليك لِيَبلُغ فيك ما يُريد، والرَّأيُ أيضًا أن تَستَعِينَ عليه بأَهلِ اليَمن فَضلًا عن مَعْد. ففَعَل ذلك وسار مِن لَيلتِه إلى أبي عَطاء، وكان يَسكُن مَدينَة إسْتِجَة، فعَظَّمَه أبو عَطاء وسَألَه عن سَببِ قُدومِه، فأَعلمَه، حتَّى قام فرَكِبَ فَرسَه ولَبِسَ سِلاحَه وقال له: انهَض الآنَ حيث شِئتَ فأنا معك. وأَمَر أَهلَه وأَصحابَه باتِّباعِه، فساروا إلى مَرْو، وبها ثَوابَة بن سَلامَة الحُداني، وكان مُطاعًا في قَومِه، وكان أبو الخطَّار قد استَعمَله على إشبيلية وغيرها، ثمَّ عَزلَه ففَسَد عليه، فدَعاهُ الصُّمَيل إلى نَصرِه ووَعَدَهُ أنَّه إذا أخرجوا أبا الخطَّار صار أَميرًا، فأجاب إلى نَصرِه ودَعا قَومَه فأجابوه فساروا إلى شدونة، وسار إليهم أبو الخطَّار مِن قُرطُبة، فالتقوا واقْتَتَلوا في رَجب مِن هذه السَّنَة، وصَبَر الفَريقان ثمَّ وَقَعت الهزيمةُ على أبي الخطَّار وقُتِلَ أَصحابُه أَشدَّ قَتْلٍ وأُسِرَ أبو الخطَّار. ولمَّا انهَزَم أبو الخطَّار سار ثَوابةُ بن سَلامَة والصُّمَيل إلى قُرطُبة فمَلكاها، واسْتَقَرَّ ثَوابةُ في الإمارة فثارَ به عبدُ الرحمن بن حَسَّان الكلبي وأَخرَج أبا الخطَّار مِن السِّجْن، فاسْتَجاش اليَمانِيَّة فاجْتَمَع له خَلْقٌ كثيرٌ، وأَقبلَ بهم إلى قُرطُبة، وخَرَج إليه ثَوابةُ فيمَن معه مِن اليَمانِيَّة والمُضَريَّة مع الصُّمَيل. فلمَّا تَقاتَل الطَّائفتان نادى رَجلٌ مِن مُضَر: يا مَعشرَ اليَمانِيَّة، ما بالُكُم تَتَعرضون للحَربِ على أبي الخطَّار وقد جعلنا الأَميرَ منكم؟ يعني ثَوابَة، فإنَّه مِن اليَمَن... فلمَّا سَمِع النَّاسُ كَلامَه قالا: صَدَق والله، الأَميرُ مِنَّا فما بالُنا نُقاتِل قَومَنا؟ فتَركوا القِتالَ وافتَرقَ النَّاسُ، فهرَب أبو الخطَّار فلَحِقَ باجة، ورَجَع ثَوابةُ إلى قُرطُبة، فسُمِّيَ ذلك العَسكَر عَسكَر العافِيَة."},{"id":466,"title":"وَفاةُ الجَهْم بن صَفوان رَأس الجَهْمِيَّة .","date":["العام الهجري :128","العام الميلادي :745"],"text":"هو أبو مُحْرِز الجَهْم بن صَفوان التِّرمذي مِن مَوالي بَنِي راسِب, نَشأَ الجَهمُ في سَمرقَند وقَضى فَترةً مِن حَياتِه في تِرمِذ، كان بارِعًا في عِلْم الكلام, ثمَّ انتَقَل إلى الكوفَة وبها الْتَقى بالجَعْدِ بن دِرهَم ومنه أخَذ مَقالَة التَّعطيل، والجَبْر، وفَناء الجَنَّة والنَّار، ونَفْي الصِّفات، وأنَّ الإيمان هو مُجرَّد المَعرِفة ثمَّ القول بخَلْق القُرآن، واشْتهَر الجَهمِيَّة بِنَفْي الصِّفات عن الله تَعالى زاعِمينَ تَنزيهَه عن مُشابَهة المَخلوقين، فعندهم ليس لله صِفَة إلَّا الذَّات، ويَنفون كُلَّ الصِّفات التي وَردَت في الكِتاب والسُّنَّة، وكان قد خرج مع الحارِث بن سُريَج الذي تَمرَّد على الدَّولة الأُمويَّة فقَتلَه سالِمُ بن أَحْوَز بمَرْو."},{"id":467,"title":"بَداية الدَّعوَة العَبَّاسِيَّة في خُراسان .","date":["العام الهجري :129","العام الميلادي :746"],"text":"في هذه السَّنَة وَجَّه إِبراهيمُ بن محمَّدِ بن عَلِيِّ بن عبدِ الله بن عَبَّاس الإمامُ أبا مُسلِم الخُراساني، واسمُه عبدُ الرَّحمن بن مُسلِم، إلى خُراسان، وعُمُره تِسع عَشرة سَنَة، وكتَبَ إلى أَصحابِه: إنِّي قد أَمَّرتُه بأَمري فاسمعوا له وأَطيعوا، فإنِّي قد أَمَّرتُه على خُراسان وما غَلَب عليه بعدَ ذلك. فأتاهم، فلم يَقبَلوا قوله وخَرَجوا مِن قابِل فالْتَقوا بمكَّة عند إبراهيم، فأَعلَمَه أبو مُسلِم أنَّهم لم يُنَفِّذوا كِتابَه وأَمْرَه. فقال إبراهيمُ قد عَرَضتُ هذا الأمرَ على غيرِ واحدٍ وأَبَوْهُ عليَّ. فأَعلَمَهم أنَّه قد أَجمَع رَأيَه على أبي مُسلِم، وأَمرَهم بالسَّمعِ والطَّاعة له، ثمَّ قال له: إنَّك رَجلٌ مِنَّا أهل البيتِ، احْفَظ وَصِيَّتي، انظُر هذا الحيَّ مِن اليَمَن فالْزَمهُم واسْكُن بين أَظهُرِهم، فإنَّ الله لا يُتِمُّ هذا الأمرَ إلَّا بهم."},{"id":468,"title":"أبو مُسلِم الخُراساني يُجاهِر بالدَّعوة العَبَّاسِيَّة .","date":["العام الهجري :129","العام الميلادي :746"],"text":"طلَب إبراهيمُ بن محمَّد بن عَلِيِّ بن عبدِ الله بن عَبَّاس مِن أبي مُسلِم أن يَحضُر إليه إلى مَكَّة لِيَعلَم منه أَخبارَ الدَّعوة، فجاءَه كِتابٌ منه أن يَرجِع إلى خُراسان ويُعلِن بالدَّعوة بعد أن كانت سِرِّيَّة، فأَظهَر أبو مُسلِم الدَّعوة وطلَب مِن سُليمان بن كَثير أن يُصلِّي بالنَّاس العيد، فأَرسَل إليهم نَصرُ بن سِيار قُوَّةً؛ ولكنَّ جُندَ أبي مُسلِم كانوا قد اسْتولَوا على هَراة، وكُشِفَ أمرُ إبراهيمَ مِن الرَّسائل وكان يُقيمُ بالحميمية فقُبِضَ عليه وسُجِن."},{"id":469,"title":"اسْتِيلاءُ الخَوارِج على صَنعاء ومَكَّة والمَدينَة .","date":["العام الهجري :130","العام الميلادي :747"],"text":"خَرَج بِحَضرمَوت طالبُ الحَقِّ عبدُ الله بن يحيى الكِندي إمامُ الإباضِيَّة؛ تَغلَّب عليها واجْتَمع عليه الإباضِيَّةُ. ثمَّ سار إلى صَنعاء وبها القاسِمُ بن عُمَر الثَّقفي فوقَع بينهم قِتالٌ كَثيرٌ، انْتَصر فيه طالبُ الحَقِّ وهَرَب القاسِمُ وقُتِلَ أخوه الصَّلْتُ، واسْتَولى طالبُ الحَقِّ على صَنعاء وأَعمالَها، ثمَّ جَهَّز إلى مَكَّة عشرةَ آلاف وبها عبدُ الواحد بن سُليمان بن عبدِ الملك بن مَرْوان فغَلَبوا على مَكَّة وخَرَج منها عبدُ الواحد، وكان على الجَيشِ أبو حَمزَة المُختار ثمَّ سارَ إلى المَدينَة وحَصَل قِتالٌ بينهم فاسْتَولى كذلك على المَدينَة، ثمَّ تَوجَّه إلى الشَّام فأَرسَل له مَرْوان جَيشًا بِقِيادة عبدِ الملك بن محمَّد بن عَطِيَّة الذي هَزَم جَيشَ أبي حَمزَة وأَكمَل سَيْرَهُ إلى المَدينَة ومَكَّة وصَنعاء."},{"id":470,"title":"وَفاةُ نَصرِ بن سِيار وتَمَكُّن أبي مُسلِم الخُرساني مِن بِلادِ خُراسان .","date":["العام الهجري :131","العام الميلادي :748"],"text":"هو الأمير أبو الليث نصر بن سيار المروزي, نائب مَرْوان بن محمَّد صاحب خراسان, خرج عليه أبو مسلم الخرساني صاحب الدعوة العباسية، وحاربه, فعجز عنه نصر, واستصرخ بمَرْوان غير مرة لكن مَرْوان عجز نجدته لاشتغاله باختلال أمر أذربيجان والجزيرة, فتقهقر نصر, وجاءه الموت على حاجة, فتُوفِّي بساوة, وقد ولي إمرة خراسان عشر سنين. وكان من رجال الدهر سؤددا وكفاءة."},{"id":471,"title":"وَفاةُ واصِل بن عَطاء رَأس المُعْتَزِلَة .","date":["العام الهجري :131","العام الميلادي :748"],"text":"هو أبو حُذيفَة واصِلُ بن عَطاء المَخزومي، كان تِلميذًا للحَسَن البَصري، سُمِّيَ هو وأَصحابُه بالمُعتَزِلَة لاعْتِزالِهم مَجلِس الحَسَن البَصري، وذلك بِسَببِ مَسألَة مُرتَكِب الكَبيرة، فالحَسنُ يقول بأنَّه لا يَزالُ مُؤمِنًا ولكنَّه فاسِق. فخالَفَه واصِل ومعه عَمرُو بن عُبيد فقال: فاسِق لكنَّه غيرُ مُؤمِن فهو في مَنزِلَة بين المَنزِلَتين وهو مع ذلك مُخَلَّد في النَّار إن مات على كَبيرَتِه، ثمَّ تَطَّور أَمرُ المُعتزِلَة حتَّى صار مَذهبًا مَعروفًا يَقومُ على أُسُسٍ خَمسَة هي: التَّوحيد: والمَقصودُ فيه نَفيُ الصِّفات، وبَنَو عليه بالتَّالي أن القُرآن مَخلُوق، وحُرِّيَّةُ الاخْتِيار، وأنَّ الإنسان يَخلُق أَفعالَه، والوَعْد والوَعيد، والأَمْر بالمَعروفِ والنَّهْي عن المُنكَر، والمَنْزِلَة بين المَنْزِلَتين، ثمَّ تَكوَّنَت فِرَقٌ نَشأَت عن أُصولِ المُعتَزِلَة، له مُؤَلَّفات منها: المَنزِلَة بين المَنزِلتَين والتَّوحيد. تُوفِّي في المَدينَة المُنوَّرة."},{"id":472,"title":"العَبَّاسِيُّون يُسَيطِرون على العِراق .","date":["العام الهجري :132","العام الميلادي :749"],"text":"كان إبراهيمُ بن محمَّدِ بن عَلِيٍّ زَعيمُ الدَّعوة العَبَّاسِيَّة قد سَجنَه مَرْوانُ ثمَّ قَتلَه، واخْتُلِف في كَيفيَّة ذلك، ثمَّ استَلَم بعدَه أَخوهُ المُلَقَّب بالسَّفَّاح عبدُ الله أبو العَبَّاس الذي تَوجَّه إلى الكوفَة فبُويِعَ له بالخِلافَة، وكانت خُراسان قد أُخْضِعَت أصلًا سابِقًا للعبَّاسِيِّين."},{"id":473,"title":"خُروجُ أبي محمَّد السُّفياني على العَبَّاسِيِّين .","date":["العام الهجري :132","العام الميلادي :749"],"text":"تَراسَل أَهلُ قِنِّسرين مع أَهلِ حِمص وتَزمَّروا واجْتَمَعوا على أبي محمَّد السُّفياني، وهو أبو محمَّد زِيادُ بن عبدِ الله بن يَزيد بن مُعاوِيَة بن أبي سُفيان، فبايَعوه بالخِلافَة، وقام معه نحو مِن أربعين ألفًا فقَصَدهم عبدُ الله بن عَلِيٍّ فالْتقَوا بمَرْج الأخرم، فاقْتَتَلوا مع مُقدِّمَة السُّفياني وعليها أبو الوَرْدِ فاقْتَتَلوا قِتالًا شَديدًا وهَزَموا عبدَ الصَّمد وقُتِلَ مِن الفَريقين أُلوف، فتَقدَّم إليهم عبدُ الله بن عَلِيٍّ ومعه حُميدُ بن قَحْطَبَة فاقْتَتَلوا قِتالًا شديدًا جِدًّا، وجَعَل أصحابُ عبدِ الله يَفِرُّون وهو ثابتٌ هو وحُميد. وما زال حتَّى هُزِمَ أَصحابُ أبي الورد، وثَبت أبو الورد في خَمسمائة فارسٍ مِن أَهلِ بَيتِه وقَومِه، فقُتِلوا جميعًا وهَرَب أبو محمَّد السُّفياني ومَن معه حتَّى لَحِقوا بتَدمُر، وآمنَ عبدُ الله أَهلَ قِنِّسرين وسَوَّدوا وبايَعوه ورَجَعوا إلى الطَّاعة، ثمَّ كَرَّ عبدُ الله راجِعًا إلى دِمَشق وقد بَلغَه ما صَنَعوا، فلمَّا دَنا منها تَفرَّقوا عنها ولم يكُن منهم قِتالٌ فأَمَّنَهم ودَخَلوا في الطَّاعَة. وأمَّا أبو محمَّد السُّفياني فإنَّه ما زال مُضَيَّعًا ومُشَتَّتًا حتَّى لَحِقَ بأَرضِ الحِجاز فقاتَلَه نائِبُ أبي جَعفَر المَنصور في أيَّامِ المنصورِ فقَتلَه وبَعَث بِرَأسهِ وبِابْنَيْنِ له أَخذَهُما أَسِيرَيْنِ فأطْلَقَهُما المنصورُ في أيَّامِه."},{"id":474,"title":"بداية حكم أبي العباس السفاح أول خلفاء الدولة العباسية .","date":["العام الهجري :132","العام الميلادي :749"],"text":"بعد أن هُزِمَ مَروان بن محمد ومن معه في معركةِ الزاب وهرب، وكان إبراهيم بن محمد قد قُتِلَ، فكان بعده أخوه عبد الله أبو العبَّاس السفَّاح، فبايعه الناسُ في الكوفة، فكان أوَّلَ خُلَفاءِ بني العباس، وبه افتُتِح عصرُ الدولةِ العباسيَّة."},{"id":475,"title":"مَعركَة نَهرِ الزَّاب الأعلى وهَزيمَة الأُمَويِّين أمامَ العَبَّاسِيِّين .","date":["العام الهجري :132","الشهر القمري : جمادى الآخرة","العام الميلادي :750"],"text":"كان أَمرُ الدَّعوة العَبَّاسِيَّة قد اسْتَفحَل خِلالَ السَّنوات الماضِيَة وقَوِيَ أَمرُها جِدًّا في خُراسان وما حولها، حتَّى بَدأَت البُعوثُ تَسيرُ إلى العِراق فخَرَج مَرْوان بن محمَّد بِجَيشٍ إليهم مِن حَرَّان حتَّى بلَغ الزَّاب وحَفَر خَندقًا وكان في عِشرين ومائة ألف، وسار أبو عَوْن وهو القادِمُ إلى العِراق للدَّعوة العَبَّاسِيَّة إلى الزَّاب، فوَجَّه أبو سَلمَة إلى أبي عَوْن عُيينَة بن موسى، والمِنْهالِ بن فَتَّان، وإسحاق بن طَلحَة، كُلُّ واحدٍ في ثلاثةِ آلاف، فعَبَر عُيينَة بن موسى في خَمسةِ آلاف، فانْتَهى إلى عَسكرِ مَرْوان، فقاتَلَهم حتَّى أَمْسَوا، ورَجَع إلى عبدِ الله بن عَلِيٍّ وأَصبحَ مَرْوان فعَقَد الجِسرَ وعَبَر عليه، فنَهاهُ وُزراؤهُ عن ذلك، فلم يَقبَل وسَيَّرَ ابنَه عبدَ الله، فنَزَل أَسفلَ مِن عَسكرِ عبدِ الله بن عَلِيٍّ، فبَعَث عبدُ الله بن عَلِيٍّ المُخارِقَ في أَربعةِ آلاف نحو عبدِ الله بن مَرْوان، فسَرَّح إليه ابنُ مَرْوان الوَليدَ بن مُعاوِيَة بن مَرْوان بن الحَكَم، فالْتَقَيا، فانْهزَم أصحابُ المُخارِق وثَبت هو فأُسِرَ هو وجَماعَة وسَيَّرَهم إلى مَرْوان مع رُؤوسِ القَتلى، وأَرسَل مَرْوان إلى عبدِ الله يَسأَله المُوادَعَة فلم يَقبَل ثمَّ حَصَل قِتالٌ بينهم كانت فيه هَزيمةُ مَرْوان ومَن معه وَفَرَّ مَرْوان إلى حَرَّان."},{"id":476,"title":"مَصرَعُ مَرْوان بن محمَّد آخِر خُلَفاء بَنِي أُمَيَّة وانْدِثارُ الدَّولة الأُمويَّة .","date":["العام الهجري :132","الشهر القمري : ذي الحجة","العام الميلادي :750"],"text":"لمَّا انْهزَم مَرْوانُ وجَيشُه في الزَّاب هَرَب إلى حَرَّان فمَكَث فيها قَليلًا ثمَّ هَرَب إلى مِصرَ عن طَريقِ حِمص ثمَّ دِمَشق ثمَّ فِلَسطين فتَبِعَه العَبَّاسِيُّون حتَّى قَتلَوه في كَنيسَة أبي صير، فكان آخِرَ خُلَفاء بَنِي أُميَّة وبِمَقْتَلِه انْتَهَت الدَّولةُ الأُمويَّة ويَبدأُ عَهْدُ الدَّولة العَبَّاسِيَّة."},{"id":477,"title":"وَفاةُ مَرْوان بن محمَّد آخِر خُلَفاء بَنِي أُميَّة .","date":["العام الهجري :132","الشهر القمري : ذي الحجة","العام الميلادي :750"],"text":"هو مَرْوانُ بن محمَّد بن مَرْوان بن الحَكَم بن أبي العاص بن أُميَّة، القُرَشي الأُمَوي (مَرْوان الحِمار) أبو عبدِ الملك، أَميرُ المؤمنين، آخِرُ خُلَفاء بَنِي أُميَّة، بُويِعَ له بالخِلافَة بعدَ قَتلِ الوَليدِ بن يَزيد، وبعدَ مَوتِ يَزيد بن الوَليد ثمَّ قَدِمَ دِمَشق، وخَلَع إبراهيمَ بن الوَليد، واسْتَتَبَّ له الأَمرُ في صَفَر سَنَة سَبعٍ وعِشرين ومائة, وكان يُقالُ له: مَرْوان الجَعْدي، نِسبَةً إلى رَأي الجَعْدِ بن دِرهَم، وقِيلَ: كان الجَعْدُ مُؤَدِّبَه وإليه نُسِب. ويُلَقَّب بالحِمارِ لِصَبرِهِ في الحَربِ, وَلَّاهُ هِشام نِيابَةَ أذربيجان وأرمينية والجَزيرَة في سَنَة أربع عشرة ومائة، ففَتَح بِلادًا كَثيرَة وحُصونًا مُتعدِّدَة في سِنين كَثيرَة، وكان لا يُفارِق الغَزْوَ، قاتَل طَوائِفَ مِن النَّاس والتُّرك والخَزَر واللَّان وغَيرَهم، فكَسَرهُم وقَهَرهُم، وقد كان شُجاعًا، بَطَلًا مِقدامًا، حازِمَ الرَّأي، وهو آخِرُ مَن مَلَك مِن بَنِي أُميَّة، كانت خِلافَتُه منذُ سَلَّمَ إليه إبراهيمُ بن الوَليد إلى أن بُويِعَ للسَّفَّاح خمس سِنين وشَهرًا، وبَقِيَ مَرْوانُ بعدَ بَيْعَةِ السَّفَّاحِ تِسعةَ أَشهُر."},{"id":478,"title":"العباسيون يبنون مدينة العسكر عاصمة لمصر .","date":["العام الهجري :133","العام الميلادي :750"],"text":"لَمَّا قَدِمَ صالح بن علي العباسيُّ وأبو عون بجموعِهما إلى مصر في طلَبِ مروان بن محمد نزَلَت عساكرُهما الصَّحراءَ جنبَ جبل يشكُر، الذي هو الآنَ جامِعُ أحمدَ بنِ طولون، وكان فَضاءً. فلمَّا رأى أبو عون ذلك أمَرَ أصحابَه بالبناءِ فيه، فبَنَوا وبنى هو به أيضًا دارَ الإمارة، ومسجِدًا عُرِفَ بجامع العَسكر. وعَمِلَت الشرطةُ أيضًا في العسكر، وقيل لها: الشرطةُ العليا، فأصبَحَت كالعاصمةِ لمصرَ؛ لأنَّه قد صارت مسكنًا للأمراءِ بعد ذلك."},{"id":479,"title":"دخول قسطنطين مَلِكُ الروم إلى ملطية .","date":["العام الهجري :133","العام الميلادي :750"],"text":"أقبل قُسطنطين- مَلِكُ الروم- إلى ملطية وكمخ، فنازل كمخ، فأرسَلَ أهلُها إلى أهل ملطية يستنجدونَهم، فسار إليهم منها ثمانمئة مقاتل، فقاتلهم الرومُ، فانهزم المسلمون، ونازل الرومُ ملطيةَ وحصَروها، والجزيرةُ يومئذ مفتونةٌ بالحروب الداخلية، وعامِلُها موسى بن كعب بحران. فأرسل قسطنطين إلى أهل ملطية: إنِّي لم أحصُرْكم إلَّا على عِلمٍ مِن المسلمين واختلافِهم، فلكم الأمانُ وتعودون إلى بلاد المسلمينَ حتى أحتَرِثَ ملطية. فلم يجيبوه إلى ذلك، فنصب المجانيقَ، فأذعَنوا وسلَّموا البلادَ على الأمانِ، وانتقلوا إلى بلاد الإسلامِ وحَملوا ما أمكنَهم حَملُه، وما لم يقدِروا على حملِه ألقَوه في الآبارِ والمجاري. فلما ساروا عنها أخرَبَها الروم ورحلوا عنها عائدينَ، وتفرَّقَ أهلُها في بلاد الجزيرة، وسار مَلِكُ الروم إلى قاليقلا فنزل مرج الخصي، وأرسل كوشان الأرمني فحصرها، فنقب إخوانٌ من الأرمنِ من أهل المدينةِ ردمًا كان في سورها، فدخل كوشان ومن معه المدينةَ وغَلبوا عليها وقتَلوا رجالَها وسَبَوا النساء وساق القائِم إلى ملك الروم."},{"id":480,"title":"غزو أبي داود خالد بن إبراهيم كش .","date":["العام الهجري :134","العام الميلادي :751"],"text":"غزا أبو داود خالدُ بن إبراهيم أهلَ كش، فقتل الأخريدَ ملكَها، وهو سامِعٌ مطيع، وقتل أصحابَه وأخذ منهم من الأواني الصينيَّة المنقوشة المذَهَّبة ما لم يُرَ مثلُها، ومن السُّروجِ ومتاع الصين كلِّه من الديباج والطرفِ شَيئًا كثيرًا فحمَلَه إلى أبي مسلم وهو بسمرقند، وقتَل عدَّةً مِن دهاقينِهم، واستحيا طاران أخا الأخريدِ ومَلكه على كش, ثم رجع أبو داود إلى بلخ."},{"id":481,"title":"أمر أبي مسلم الخرساني بناء سور سمرقند .","date":["العام الهجري :134","العام الميلادي :751"],"text":"أمرَ أبو مسلم الخرساني ببناء سور سمرقند، بعد انصرافه من سمرقند وفتكه بأهل الصغد وبخارى؛ واستخلف زيادَ بن صالح على سمرقند وبخارى"},{"id":482,"title":"عبد الله بن حبيب يغزو جزيرة صقلية .","date":["العام الهجري :135","العام الميلادي :752"],"text":"غزا عبد الله بن حبيبٍ جزيرةَ صقليَّة وغنم بها وسبى وظفَرَ بها ما لم يظفَرْه أحد قبله بعد أن غزا تلمسان."},{"id":483,"title":"تحصين الروم لصقلية وعدوانهم منها على المسلمين  .","date":["العام الهجري :135","العام الميلادي :752"],"text":"لما اشتغل ولاةُ إفريقية بالفتنةِ مع البربر، أمَّن الروم في صقليَّة فعمَرَوها من جميع الجهاتِ وعَمَروا فيها الحصونَ والمعاقِلَ، وصاروا يُخرجون كلَّ عامٍ مراكِبَ تطوف بالجزيرةِ وتذُبُّ عنها، وربما طارقوا تجَّارًا من المسلمين فيأخذونَهم."},{"id":484,"title":"وفاة ربيعة الرأي .","date":["العام الهجري :136","العام الميلادي :753"],"text":"هو الإمام، الفقيه الحافِظٌ، عالم الوقت، أبو عثمان ويقال: أبو عبد الرحمن ربيعةُ بنُ أبي عبد الرحمن فروخ القرشي، التيمي مولاهم، المشهور بربيعة الرأي، من موالي آل المنكدر. أحد أئمة الاجتهاد ومن أوعية العلم. أدرك جماعة من الصحابة رضي الله عنهم, وروى عن أنسِ بن مالكٍ، وعن كثير من التابعين، كان بصيرًا بالرأي، حتى لُقِّبَ بهذا اللقب، عليه تفقَّه الإمام مالك، كان صاحِبَ الفتوى في المدينة، وكان صاحِبَ اجتهادٍ، كريمًا عابدًا، أقدمه السفاح الأنبار ليوليه القضاء, فتوفِّي فيها, وقيل توفي بالمدينة, وطلبه المنصورُ للقضاءِ. قال الإمام مالكٌ: ذهَبَت حلاوةُ الفِقهِ منذ مات ربيعةُ، قال: الشافعي، حدثنا سفيان: كنا إذا رأينا طالبا للحديث يغشى ثلاثة ضحكنا منه: ربيعة، ومحمد بن أبي بكر بن حزم، وجعفر بن محمد؛ لأنهم كانوا لا يتقنون الحديث."},{"id":485,"title":"وفاة الخليفة العباسي أبي عبد الله السفاح .","date":["العام الهجري :136","الشهر القمري : ذي الحجة","العام الميلادي :754"],"text":"هو الخليفة أبو العباس عبدُ الله السَّفَّاح بن محمد الإمام بن علي السجاد بن عبد الله الحبر بن العباس، القرشيُّ الهاشمي أمير المؤمنين، وهو أول خلفاء العباسيين. ولِد السَّفاح سنة 105 بالحميمة ونشأ به وهي من أرض الشراة من أرض البلقاء بالشام. كان السَّفاح شابا، مليحا، مهيبا، أبيض، طويلا، وقورا. هرب أبو العباس مع أهله من جيش مروان الحمار، وأتوا الكوفة لما استفحل لهم الأمر بخراسان. حتى طُلِب أخوه إبراهيم، فقتَله مروان الحمارُ بحرَّان، فانتقلوا إلى الكوفة، فآواهم أبو سلمة الخلال في سرب بداره. بويع أبي العباس السفاح بالخلافةِ بعد مقتل أخيه إبراهيم في حياة مروان سنة ثِنتين وثلاثين ومائة، توفي بالجدري بالأنبار، وكان عمره ثلاثًا وثلاثين سنة. وقيل: ثمانيًا وعشرين سنة. وكانت خلافته أربع سنين وتسعة أشهر."},{"id":486,"title":"أبو جعفر المنصور يَتَوَلَّى الخلافة العباسية .","date":["العام الهجري :136","الشهر القمري : ذي الحجة","العام الميلادي :754"],"text":"عقد السَّفَّاح عبدُ الله بن محمد بن علي بن عبد الله بن عباس لأخيه أبي جعفرٍ عبدِ الله بن محمَّد بالخلافة مِن بعدِه، وجعله وليَّ عهد المسلمين، ومِن بعد أبي جعفرٍ ولد أخيه عيسى بن موسى بن محمد بن علي، وجعل العهدَ في ثوبٍ وخَتَمه بخاتمه وخواتيمِ أهل بيته، ودفعه إلى عيسى بن موسى. فلما توفي السفَّاح كان أبو جعفر بمكَّة، فأخذ البيعةَ لأبي جعفرٍ عيسى بن موسى، وكتب إليه يُعلِمُه وفاة َالسفَّاح والبيعةَ له بعد أن دامت خلافةُ السفَّاح أربع سنين."},{"id":487,"title":"ثورة عبد الله بن علي على ابن أخيه المنصور .","date":["العام الهجري :137","العام الميلادي :754"],"text":"كان عبد الله بن علي في الصائفة في الجنود حين مات السفَّاح، وكان المنصور يخشى أن يثورَ عليه، ولَمَّا وصل الكتاب إلى عبد الله بموت السفَّاح وهو في الصائفة دعا لنفسه، وذلك أنَّه قال: إنَّ السفاحَ لَمَّا أراد قتلَ مروان انتدب الناسَ من يقتُلُه من أهل بيته- يعني بيت العباسيين- فإنَّه يكونُ وليَّ عَهدِه، فانتدب لذلك عبد الله، فهو الأحق بالأمر من المنصورِ، فبايعه بعضُ قوَّاده، فسار إلى الكوفة وحاصرها أربعينَ يومًا، ولَمَّا رجع المنصور من الحجِّ ومعه أبو مسلم الخرساني، سيَّرَه لقتال عبد الله، فاقتتلوا وبَقُوا على ذلك خمسة أشهر، ثم مكَرَ بهم أبو مسلم فانهزم جيش عبد الله وفرَّ، وبقي متخفِّيًا بالبصرة إلى أن أعطى الأمانَ أبو مسلم."},{"id":488,"title":"قتل المنصور الأمير أبا مسلم الخراساني .","date":["العام الهجري :137","الشهر القمري : شعبان","العام الميلادي :755"],"text":"هو الأمير أبو مسلم عبد الرحمن بن مسلم بن عثمان بن يسار، بن شذوس بن جودرن من ولد بزرجمهر بن البختكان الخراساني الفارسي صاحب الدعوة، وهازم جيوش الدولة الأموية، والقائم بإنشاء الدولة العباسية. وقيل كان اسمه إبراهيم بن عثمان بن يسار غيره بطلب من الإمام إبراهيم بن محمد لمزيد من التخفي. قال الذهبي: \"كان أبو مسلم من أكبر الملوك في الإسلام، كان ذا شأن عجيب، ونبأ غريب، من رجل يذهب على حمار بإكاف من الشام حتى يدخل خراسان، ثم يملك خراسان بعد تسعة أعوام، ويعود بكتائب أمثال الجبال، ويقلب دولة، ويقيم دولة أخرى! كان قصيرا، أسمرا، جميلا، حلوا، نقي البشرة، أحور العين، عريض الجبهة، حسن اللحية، طويل الشعر، طويل الظهر، خافض الصوت، فصيحا بالعربية وبالفارسية، حلو المنطق، وكان لا يكاد يقطب في شيء من أحواله، تأتيه الفتوحات العظام، فلا يظهر عليه أثر السرور، وتنزل به الفادحة الشديدة، فلا يرى مكتئبا, وكان إذا غضب، لم يستفزه الغضب, وكان لا يأتي النساء في العام إلا مرة واحدة، يشير إلى شرف نفسه وتشاغلها بأعباء الملك\". كان مولده بأصبهان سنة 100, وضعته أمه يتيما فنشأ عند عيسى بن معقل، فلما ترعرع اختلف مع ولده إلى المكتب، فخرج أديباً لبيباً يشار إليه من صغره, وكان راوية للشعر، عارفا بالأمور، لم ير ضاحكا ولا مازحا إلا في وقته. كان بدء أمر أبي مسلم أنه قدم الكوفة جماعة من نقباء العباسيين، فصادفوا أبا مسلم، فأعجبهم عقله ومعرفته وكلامه وأدبه، ومال هو إليهم ثم عرف أمرهم وأنهم دعاة، ثم خرج معهم إلى مكة، فأهدوه للإمام إبراهيم بن محمد، فأُعجب به وبمنطقه وعقله وأدبه، وقال لهم: هذا عضلة من العضل. وأقام أبو مسلم عند الإمام إبراهيم يخدمه حضراً وسفراً. ثم إن النقباء عادوا إلى الإمام إبراهيم وسألوه رجلاً يقوم بأمر خراسان، فقال: إني قد جربت هذا الأصبهاني وعرفت ظاهره وباطنه فوجدته حجر الأرض، ثم دعا أبا مسلم وكان عمره ثمان عشر سنة وقلده الأمر وأرسله إلى خراسان, فأخذ يدعو الناس إلى رجل من بني هاشم وأقام على ذلك سنين, وبعد مقتل الإمام إبراهيم بن علي صار أبو مسلم يدعو الناس إلى أبي العباس عبد الله بن محمد الملقب السفاح. حتى مكن للعباسيين وقضى على الأمويين في الشرق وكان سفاكا للدماء قال ابن خلكان: \"قتل أبو مسلم في دولته ستمائة ألف صبراً. قيل لعبد الله بن المبارك: أبو مسلم خير أو الحجاج قال: لا أقول إن أبا مسلم خيراً من أحد، ولكن الحجاج كان شراً منه\", وقال الذهبي: \"كان أبو مسلم سفاكا للدماء، يزيد على الحجاج في ذلك، وهو أول من سن للعباسيين لبس السواد, وكان بلاء عظيما على عرب خراسان، فإنه أبادهم بحد السيف\". قال أحمد بن سيار: حدثنا الحسن بن رشيد العنبري، سمعت يزيد النحوي يقول: \"أتاني إبراهيم بن إسماعيل الصائغ، فقال لي: ما ترى ما يعمل هذا الطاغية، إن الناس معه في سعة، غيرنا أهل العلم؟ قلت: لو علمت أنه يصنع بي إحدى الخصلتين لفعلت، إن أمرت ونهيت يقيل أو يقتل، ولكني أخاف أن يبسط علينا العذاب، وأنا شيخ كبير، لا صبر لي على السياط. فقال الصائغ: لكني لا أنتهي عنه. فذهب، فدخل عليه، فأمره ونهاه، فقتله\" وكان أبو مسلم يجتمع قبل أن يعلن بدعوة العباسيين بإبراهيم الصائغ، ويعده بإقامة الحق, فلما ظهر وبسط يده، دخل عليه، فوعظه فقتله\". لما خشي المنصور من خطر أبي مسلم على دولته قرر التخلص منه, وكان المنصورُ قد غضِبَ عليه لعدَّةِ أمورٍ؛ منها: أنَّه تقدَّمَ عليه في الحجِّ، وأكثَرَ مِن النفقةِ حتى قيل فيه ما قيل، ثم إنَّه خافه بعد أن صار أمرُه في خراسان قويًّا، فبعد أن هزمَ أبو مسلم جيش عبد الله بن علي، أمَرَه المنصور بالعودةِ إليه فأبى، فاحتال له أنَّه يوليه الشامَ ومصرَ فأبى عليه كلَّ ذلك، وأرسل له رسلًا وكُتُبًا، كلُّ ذلك وهو يأبى الرجوعَ؛ حيثُ شعر أنَّ هناك مكيدةً، ومن ذلك أن المنصور كاتب أبا مسلم ليقدم عليه، فكتب إليه أبو مسلم: \"إنه لم يبق لك عدو إلا أمكنك الله منه، وقد كنا نروي عن ملوك آل ساسان: إن أخوف ما يكون الوزراء إذا سكنت الدهماء، فنحن نافرون من قربك، حريصون على الوفاء بعهدك ما وفيت، فإن أرضاك ذلك، فأنا كأحسن عبيدك، وإن أبيت نقضت ما أبرمت من عهدك، ضنا بنفسي، والسلام\" فرد عليه الجواب يطمئنه ويمنيه، وكان المنصور داهية وقته، ثمَّ لَمَّا جاءه الخبَرُ أن المنصورَ سيقاتِلُه بنفسه إن أبى الرجوعَ إليه، عاد، وقيل: إنَّه قيل له أن يقتُلَ المنصور قبل أن يقتُلَه، لكنَّ المنصور احتال عليه وأمرَ بعضَهم بالاختباءِ وراء الستورِ، فإذا صفق بيده انقضُّوا عليه، فدعاه المنصور على غدائِه وعاتبه على أفعالِه، وكل ذلك يعتذِرُ أبو مسلم ويقَبِّلُ يدَه، ولكنه لم يرضَ عنه حتى صفق بيدِه، فخرجوا وقتلوه، فكانت تلك نهايةَ أبي مسلم الخراساني، الذي كان له الأثَرُ الكبيرُ في توطيدِ دعائمِ الدَّعوة العباسيَّة. قتله المنصور وله من العمر سبع وثلاثون سنة. قال الذهبي: \" فرحنا بمصير الأمر إلى بني العباس، ولكن والله ساءنا ما جرى؛ لما جرى من سيول الدماء، والسبي، والنهب فإنا لله وإنا إليه راجعون فالدولة الظالمة مع الأمن وحقن الدماء، ولا دولة عادلة تنتهك دونها المحارم، وأنى لها العدل؟ بل أتت دولة أعجمية خراسانية جبارة، ما أشبه الليلة بالبارحة \" وقال: \"وقد كان بعض الزنادقة، والطغام من التناسخية، اعتقدوا أن الباري سبحانه وتعالى حل في أبي مسلم الخراساني المقتول، عندما رأوا من تجبره، واستيلائه على الممالك، وسفكه للدماء، فأخبار هذا الطاغية يطول شرحها\". لما قُتل أبو مسلم الخرساني، خرج بخراسان سنباذ للطلب بثأر أبي مسلم، وكان سنباذ مجوسيا، فغلب على نيسابور والري، وظفر بخزائن أبي مسلم، واستفحل أمره, فجهز المنصور لحربه جمهور بن مرار العجلي، في عشرة آلاف فارس، فانهزم سنباذ، وقتل من عسكره نحو من ستين ألفا، وعامتهم كانوا من أهل الجبال، فسبيت ذراريهم، ثم قتل سنباذ بأرض طبرستان."},{"id":489,"title":"دخول ملك الروم ملطية عنوة .","date":["العام الهجري :138","العام الميلادي :755"],"text":"خرجَ قُسطنطين ملكُ الروم إلى بلد الإسلامِ، فدخل ملطية عَنوةً وقهرًا، وغلَب أهلَها، وهدَمَ سُورَها، وعفا عمَّن فيها من المُقاتِلة والذرِّيَّة."},{"id":490,"title":"مبايعة عبد الله بن علي للخلافة .","date":["العام الهجري :138","العام الميلادي :755"],"text":"بعد أن انهزم عبد الله بن علي (عمُّ المنصور) على يدِ أبي مسلم، وبقي في البصرة، قام بالدعوة لنفسِه، وبويع، ولكن لم يتمَّ له شيءٌ، فاستجار بأخيه سليمان الذي كان أميرًا للبصرة، ثم إنه بقي كذلك حتى أظهر الطاعةَ للمنصور، ثم عزل المنصور عمَّه سليمان عن إمرة البصرة، فاختفى عبد الله بن عليٍّ وأصحابُه خوفًا على أنفسهم، فبعث المنصورُ إلى نائبه على البصرة، وهو سفيان بن معاوية، يستحِثُّه في إحضار عبد الله بن علي إليه، فبعَثَه في أصحابه فقُتل بعضُهم، وسُجِن عبد الله بن علي عمُّه، وبعَث بقيَّة أصحابه إلى أبي داود نائب خراسان فقتَلَهم هناك."},{"id":491,"title":"ذكر الفتنة في الأندلس .","date":["العام الهجري :138","العام الميلادي :755"],"text":"خرج في الأندلس الحُباب بن رواحة بن عبد الله الزهري ودعا إلى نفسِه، واجتمع إليه جمعٌ من اليمانية، فسار إلى الصميل، وهو أمير قرطبة، فحصره بها وضيَّق عليه، فاستمد الصميلُ يوسفَ الفهريَّ أمير الأندلس، فلم يفعَلْ لتوالي الغلاءِ والجوع على الأندلس، ولأنَّ يوسُفَ قد كره الصميل واختار هلاكَه ليستريحَ منه. وثار بها أيضًا عامر العبدري وجمع جمعًا واجتمعَ مع الحباب على الصميل، وقاما بدعوة بني العباس. فلما اشتدَّ الحصارُ على الصميل كتب إلى قومه يستمِدُّهم، فسارعوا إلى نُصرتِه واجتمعوا وساروا إليه، فلما سمِعَ الحباب بقُربهم سار الصميل عن سرقسطة وفارقها، فعاد الحُباب إليها ومَلَكها، واستعمل يوسُفُ الفهري الصميل على طليطلة"},{"id":492,"title":"عبد الرحمن الداخل يؤسس الدولة الأموية بالأندلس .","date":["العام الهجري :138","العام الميلادي :755"],"text":"كان عبد الرحمن بن معاوية قد انتقل إلى بلاد المغرب؛ فرارًا من عبد الله بن عليِّ بن عبد الله بن عباس، فاجتاز بمن معه من أصحابِه الذين فرُّوا معه بقومٍ يقتتلون على عصبيَّة اليمانية والمُضَرية، فبعث مولاه بدرًا إليهم فاستمالهم إليه، فبايعوه ودخل بهم ففتح بلادَ الأندلس واستحوذ عليها، وانتزعها من يوسف بن عبد الرحمن الفهري آخر ولاة بني أمية في الأندلس، والذي جمع جيشًا فيما بعد، وأعلن العصيانَ وأراد غزو قرطبة، فسار إليه عبد الرحمن وهزمه وقتله، وسكن عبد الرحمن قرطبة، واستمر في خلافتِه في تلك البلاد من هذه السنة إلى سنة 172، وقيل: إنَّه في البداية لم يُعلِن الدَّعوة الأمويَّة، بل قيل: إنه كان يدعو للخليفةِ العباسيِّ. حاول المنصورُ القضاءَ عليه بواسطة العلاء بن مغيث، لكنَّه لم يُفلِح، واستطاع عبد الرحمن أن يقتُلَه، ومِن ثَمَّ ترك عبد الرحمن الدعوة للخليفة العباسي، وسمِّي عبدُ الرحمن هذا بصقر قريش."},{"id":493,"title":"استعادة العباسيين مقاطعة ملطية من البيزنطيين .","date":["العام الهجري :139","العام الميلادي :756"],"text":"غزا العبَّاسُ بن محمد بن علي بن عبد الله بن عباس الصائفةَ مع صالحِ بنِ علي وعيسى بن علي، وبنوا ما أخربه الرومُ مِن ملطية، ثم غزَوا الصائفةَ من درب الحدثِ، فتوغلوا في أرض الروم، وغزا مع صالحٍ أختاه أم عيسى ولبابة بنتا علي، وكانتا نذَرَتا إن زال مُلكُ بني أميَّة أن تجاهِدا في سبيل الله، وغزا من درب ملطية جعفرُ بن حنظلة المرهاني، وفي هذه السَّنة كان الفداءُ بين المنصور وملك الروم، فاستفدى المنصورُ أسرى قاليقلا وغيرَهم من الروم، وبناها وعمَرها، وردَّ إليها وندب إليها جندًا من أهلِ الجزيرة وغيرهم، فأقاموا بها وحَمَوها"},{"id":494,"title":"أبو جعفر المنصور يبدأ بتوسيع المسجد الحرام .","date":["العام الهجري :139","العام الميلادي :756"],"text":"كانت هذه السنةُ خِصبةً جِدًّا، حتى سُمِّيَت سنةَ الخِصبِ، وكان فيها توسيعُ المسجدِ الحرامِ مِن قِبَلِ المنصورِ، فزاد في شِقِّه الشامي الذي فيه دارُ النخلة ودارُ الندوة في أسفله، ولم يزِدْ عليه في أعلاه ولا في شِقِّه الذي على الوادي، فاشترى من النَّاسِ دُورَهم الملاصِقةَ بالمسجدِ مِن أسفَلِه، فزاده فيه."},{"id":495,"title":"بداية تأسيس الدولة الرستمية (الإباضية) .","date":["العام الهجري :139","العام الميلادي :756"],"text":"كان قد هرب الكثيرُ من أهلِ القيروان لِمَا لاقوا مِن ظُلم عبد الملك بن أبي الجعد الورفجومي وأتباعه، فلجأ الهاربون إلى أبي الخطَّاب عبد الأعلى بن السَّمح، فبايعوه وكثُرَ أتباعُهم، فاستولى على طرابلس، ثم سار إلى قابس فأخذها، واتجه إلى القيروان فالتقى بعبد الملك فهزمه وقتَلَه، واستولى على القيروان وولَّى عليها عبد الرحمن بن رستم الإباضي."},{"id":496,"title":"الخوارج الصفارية يبنون مدينة سلجماسة بالمغرب الأقصى .","date":["العام الهجري :140","العام الميلادي :757"],"text":"استطاع عاصِمُ بن جميل أن يهزِمَ حبيبَ بن عبد الرحمن الفهري، فدخل القيروان وولَّى عليها عبد الملك بن أبي الجعد، وسار هو خلفَ حبيب حتى قتلَه فأصبح للصفرية نفوذُهم الكبير في المغرب، ثم لما انهزموا أمام الإباضيَّة اتجهوا نحو المغرب الأقصى والأوسط، واستطاع أبو قرةَ تأسيسَ دولةٍ في ناحية تلمسان، كما استطاع أبو القاسِمِ سِمكو بن واسول إرساءَ قواعِدِ دولةِ بني مدرارٍ في سجلماسة."},{"id":497,"title":"يوم الروانديَّة (الروانديَّة) .","date":["العام الهجري :141","العام الميلادي :758"],"text":"الروانديَّةُ أو الروانديَّة أصلُهم من خراسان، وهم على رأي أبي مسلمٍ الخراساني، كانوا يقولونَ بالتناسُخِ، ويزعمونَ أنَّ روح آدم انتقَلَت إلى عثمان بن نهيك، وأنَّ رَبَّهم الذي يُطعِمُهم ويسقيهم أبو جعفرٍ المنصور. وأنَّ الهيثم بن معاوية جبريل- قبَّحَهم الله- فأتَوا يومًا قصر المنصور فجعلوا يطوفونَ به، ويقولون: هذا قصر ربنا، فأرسل المنصورُ إلى رؤسائهم، فحبس منهم مئتين، فغَضِبوا من ذلك ودخَلوا السجن قهرًا، وأخرجوهم فخرج المنصور إليهم، وخرج الناس وكان منهم معن بن زائدة، الذي قال للمنصور: نحن نكفيكَهم فأبى، وقام أهل الأسواق إليهم فقاتَلوهم، وجاءت الجيوشُ فالتفُّوا عليهم من كل ناحية فحصدوهم عن آخِرِهم، ولم يَبقَ منهم بقيَّة."},{"id":498,"title":"بناء المنصور المصيصة .","date":["العام الهجري :141","العام الميلادي :758"],"text":"لما رجع أبو جعفر المنصور من الحج مر بالمدينة، ثم توجه إلى بيت المقدس، فصلى في مسجدها، ثم سلك إلى الشام منصرفا حتى انتهى إلى الرقة فنزلها، وكتب إلى صالح بن علي يأمره ببناء المصيصة، ثم خرج منها إلى ناحية الكوفة، فنزل المدينة الهاشمية بالكوفة، وقد فرغ بناءُ المصيصة على يدَي جبريلَ بنِ يحيى الخراساني."},{"id":499,"title":"فتح طبرستان .","date":["العام الهجري :143","العام الميلادي :760"],"text":"كتب المنصورُ إلى ابنه المهدي أن يغزوَ طبرستان، وأن يوجِّهَ أبا الخصيب وخازم بن خزيمة والجنودَ إلى الأصبهبذ، وكان الأصبهبذ يومئذٍ محاربًا للمصمغان، ملك دنباوند، فتحالفا ضدَّ المُسلمين، فانصرف الأصبهبذ إلى بلادِه فحارب المسلمين، فطالت تلك الحروبُ، فوجه المنصورُ عمرَ بن العلاء إلى طبرستان وكان عالِمًا ببلاد طبرستان، فأخذ الجنودَ وقصد الرويان وفتَحَها، وأخذ قلعةَ الطاق وما فيها، وطالت الحربُ، فألحَّ خازم على القتالِ، ففتح طبرستان وقتل منهم فأكثَرَ، وسار الأصبهبذ إلى قلعته فطلب الأمانَ على أن يسَلِّمَ القلعةَ بما فيها من الذخائرِ، وكتب المهدي بذلك إلى المنصورِ، فوجَّه المنصورُ صالحًا صاحِبَ المُصلى، فأحصوا ما في الحصن وانصرفوا، ودخل الأصبهبذ بلاد جيلان من الديلم فمات بها، وأُخِذَت ابنته وهي أم إبراهيم بن العباس بن محمد، وقصَدَت الجنود بلد المصمغان فظَفِروا به وبالبحترية، أم منصور بن المهدي."},{"id":500,"title":"وفاة عمرو بن عبيد شيخ المعتزلة .","date":["العام الهجري :143","العام الميلادي :760"],"text":"هو عمرو بنُ عُبيد بن باب التميميُّ ولاءً، من أهل ِالبصرةِ، شيخ المعتزلة في زمانه، اشتُهِر بزهده، أخذ عن واصل بن عطاءٍ، واعتزل معه مجلسَ الحسَن البصريِّ، قال يحيى بن معين: \"كان من الدَّهرية الذين يقولونَ إنما الناسُ مِثلُ الزرع\"، وقال ابن المبارك: \"دعا إلى القدَرِ فتركوه\"، قال ابن عُلية: \"أوَّلُ من تكلَّم في الاعتزالِ واصِلُ الغزَّال، فدخل معه عمرو بنُ عُبيد، فأُعجِبَ به وزوَّجَه أختَه\"، وله كتابُ العدل، والتوحيد، وكتاب الردَّ على القدرية يُريدُ السُّنَّة، مات بمران قرب مكة."},{"id":501,"title":"غزو الديلم .","date":["العام الهجري :144","العام الميلادي :761"],"text":"بلغ أبا جعفر المنصور ما فعله الدَّيلمُ بالمسلمين وقتْلُهم منهم مقتلةً عظيمةً، فوجَّه إلى البصرة حبيبَ بن عبد الله بن رغبان، وعليها يومئذ إسماعيلُ بن عليٍّ، وأمره بإحصاءِ كلِّ مَن له فيها عشرةُ آلاف درهم فصاعدًا، وأن يأخُذَ كلَّ من كان ذلك له بالشُّخوصِ بنَفسِه لجهاد الدَّيلم، ووجَّه آخر لمثل ذلك إلى الكوفة. ثم سيَّرَ أبو جعفر النَّاسَ من الكوفة والبصرة والجزيرة والموصل إلى غزو الديلم، واستعمل عليهم محمد بن أبي العباس السفَّاح."},{"id":502,"title":"بداية تأسيس الدولة الرستمية (الإباضية) .","date":["العام الهجري :144","العام الميلادي :761"],"text":"كان عبد الرحمن بن رستم من مُسلِمة الفتح الإسلامي، وهو من ولَدِ رستم أمير الفرس بالقادسية، قَدِم إلى إفريقية مع طوالعِ الفتح فكان بها. وأخذَ بدِين الخارجيَّة والإباضية منهم، تحزَّبَ الإباضية بناحية طرابلس واجتمعوا إلى ابنِ الخطاب عبد الأعلى بن السمح المغافري إمامِ الإباضية، فملكوا طرابلس، ثم ملَكوا القيروان، وقتَلوا واليَها من ورفجومة عبد الملك بن أبي الجعد، وأثخَنوا في ورفجومة وسائر مغراوة, ثم رجعَ أبو الخطاب والإباضية الذين معه من زناتة وهوارة وغيرهم بعد أن استخلف على القيروان عبد الرحمن بن رستم. لَمَّا بلغ الخبرُ بفتنةِ ورفجومة واضطرابِ الخوارجِ من البربر بإفريقيةَ والمغرب المنصورَ أبا جعفر, سرَّح محمد بن الأشعث الخزاعي في العساكرِ إلى إفريقية، وقلَّدَه حرب الخوارج، فقَدِمَها سنة 144, ولقيهم أبو الخطَّاب في جموعه قريبًا من طرابلس، فأوقع به ابن الأشعث وبقومه. وقُتل أبو الخطَّاب وطار الخبرُ بذلك إلى عبد الرحمن بن رستم بمكانِ إمارته في القيروان، فاحتمَلَ أهلَه وولده ولحِقَ بإباضية البرابرة في المغرب الأوسط (الجزائر) عاصمتها (تهرت) تسمى تيارت حاليًّا، ونزل على لماية بطن من بطونِ البربر لقديمِ حِلفٍ بينه وبينهم، فاجتمعوا إليه وبايعوا له بالخلافة."},{"id":503,"title":"المنصور يعتقل عبدالله بن حسن والد محمد النفس الزكية .","date":["العام الهجري :144","الشهر القمري : ذي الحجة","العام الميلادي :762"],"text":"لَمَّا قَدِمَ المنصورُ لموسم الحجِّ واجتمع بعبدِ الله بن حسن، ولم يكن ولداه قد قَدِما معه إليه، فغَضِبَ المنصور من عبد الله لَمَّا لم يُعلِمْه بمكانِ ولديه فأخذه معه إلى الكوفة هو وبعض أقاربه مُقَيَّدينَ، وحبَسَهم هناك في حبسٍ سيئ، هلك فيه بعضُهم، وقُتِل البعضُ. وأمَّا عبد الله بن حسن فإنه توفِّي في السجن بعد مقتل ولده محمد بالمدينة, وقيل إنَّه قُتِلَ في السجنِ عمدًا؛ حيث كان محبوسًا في سرداب، فقيل إن المنصورَ أمرَ برَدمِه عليهم."},{"id":504,"title":"ثورة السودان العبيد بالمدينة .","date":["العام الهجري :145","العام الميلادي :762"],"text":"كان على المدينةِ عبد الله بن الربيع مِن قِبَل المنصور، وكان جندُه قد استفحل أمرُهم مع التجَّار بالظُّلم، فكانوا يأخذون ما شاءوا بدون ثمنٍ أحيانًا، وكل ذلك وابن الربيع لا يغيِّرُ شيئًا ولا يكلِّمُ جندَه، فاستفحل أمرُهم حتى كان يومُ جمعة قتَلَ أحدُ الجزَّارين جنديًّا، ثم تنادى الجندُ وتنادى السودان (العبيد) ونفخوا في بوقٍ لهم، فلم يبقَ في المدينة أسودُ إلَّا جاء، وتأمر عليهم وثيق الزنجي، فثاروا على الجند ونهبوا أموالَ الأميرِ وهرب ابنُ الربيع خارج المدينة، ثم إنَّ أبا بكر بن أبي سبرة خرج من السجنِ ونصح النَّاسَ أن يعودوا للطاعة، وإلا كانت مهلكتُهم وخاصةً بعد أن كانت حادثةُ النَّفس الزكية، فاستجابوا له ورَدُّوا ما كانوا نهبوه, ثم أمسك وثيق الزنجي وقيد, وعاد ابن الربيع للمدينة."},{"id":505,"title":"حركة محمد النفس الزكية .","date":["العام الهجري :145","الشهر القمري : جمادى الآخرة","العام الميلادي :762"],"text":"كان المنصورُ قد حَبَس عبدَ الله بن الحسن والدَ محمد النفس الزكية، وكان همُّ المنصورِ هو الظفَرَ بمحمَّدٍ - الذي كان متخفيًا في المدينة- وأخيه إبراهيمَ، وذلك أنَّهما تخلَّفا عن الحضور إليه في موسم الحج, وعِلْمه بسعيهما للوصول لأمر ِالخلافة منذ أيَّام بني أمية؛ بقصد إزالة المخالفاتِ الشَّرعية والظُّلم الذي وقع من الولاة والأمراء, فخاف مِن أمرِهما، ثمَّ إنَّ محمدًا دعا للبيعةِ لنفسه واستولى على مقاليد الأمور في المدينة في  آخر شهر جمادى الآخرة وحبس واليها رياح المري، وأخذ البيعة من أهلها في المسجد النبوي بعد خروجِ المنصور إلى الكوفة، فكتب المنصورُ له كتابًا بالأمان فرفضه، وكتب هو للمنصور كتابًا مضمونُه أنَّه هو أحقُّ بالولاية منه، فانتشر أمرُ محمد في المدينة وبايعه خلقٌ كثير، وقَوِيَ أمرُه حتى أرسل بعضَ الجندِ إلى مكَّة ليبايعوا له فيها، وبعث لأهل الشامِ فأبَوا عليه واعتذروا بأنَّه ليس له قوةٌ في بلدِه التي هو فيها، فكيف يطلب مثلَ هذا؟! وقد ملُّوا الحروبَ بين بعضِهم، ثم َّإن المقاتلينَ الذين أرسلهم إلى مكةَ دخلوها ولم يكونوا يزيدونَ على ثمانينَ، وأمَّا في البصرةِ فقام إبراهيم أخو محمد وبايع أيضًا له خلْقٌ، فجهَّزَ له المنصورُ جيشًا بقيادة عيسى بن موسى، فعلم محمد النفس الزكية بالأمر فحفَرَ خندقًا، ثمَّ جاء جيشُ عيسى وبقي أيامًا يدعوه للطاعة ويأبى، ودعا أهلَ المدينة للخروجِ؛ فليسوا هم المقصودين، وأحلَّ محمدٌ من أرادَ مِن بيعتِه إن خاف، فرجَع خلقٌ عنها، ثم بعد عدة أيام نشبت الحرب بينهما، وكانت حربًا شديدة جدًّا، ودخل عيسى المدينة وبقيَ القتالُ حتى لم يبقَ مع محمد النفس الزكيَّة إلا نفرٌ، ثمَّ قُتِلَ في رمضان وبُعِثَ برأسه إلى المنصور، ونوديَ بالأمان لأهل المدينةِ."},{"id":506,"title":"خروج إبراهيم بن عبدالله (أخو محمد النفس الزكية) بالبصرة  .","date":["العام الهجري :145","الشهر القمري : ذي الحجة","العام الميلادي :763"],"text":"لَمَّا قام محمد بالمدينة ودعا لنفسه خرج أخوه إبراهيم في البصرة ودعا للبيعة، وقوِيَ أمره ثم غلبَ عليها وبايعه أهلُ الأهواز كذلك واستحوذَ على البلاد، وبعث إبراهيم إلى بلاد فارس فأخَذَها، وكذلك واسِط والمدائن والسَّواد، واستفحل أمرُه جدًّا، ولكنْ لَمَّا جاءه نعيُ أخيه محمد انكسر جدًّا، ثم إنَّ المنصورَ استدعى عيسى بن موسى وجيشَه وسيَّرَه لقتال إبراهيم حتى هزمه في موقعة باخمرا، وقُتِلَ إبراهيمُ كذلك وأُخِذَ رأسُه إلى المنصور، وكان ذلك في ذي الحجَّةِ من هذا العام،"},{"id":507,"title":"هزيمة حملة العلاء بن مغيث ضد الأمويين بالأندلس .","date":["العام الهجري :146","العام الميلادي :763"],"text":"سار العلاء بن مغيث اليحصبي من إفريقيَّة إلى مدينة باجة من الأندلس، ولَبِسَ السَّواد, وخطبَ للمنصور، واجتمع إليه خلقٌ كثيرٌ، فخرج إليه الأميرُ عبد الرحمن الداخل، فالتقيا بنواحي إشبيلية، ثم تحارَبا أيامًا، فانهزم العلاء وأصحابُه، وقُتِل منهم في المعركة سبعةُ آلاف، وقُتِل العلاء، وأُمِرَ بعضُ التجار بحمل رأسه ورؤوسِ جماعةٍ مِن مشاهير أصحابه إلى القيروان، وإلقائِها بالسوق سرًّا، ففعل ذلك، ثم حُمِلَ منها شيءٌ إلى مكة، فوصلت وكان بها المنصور، وكان مع الرؤوسِ لواءٌ أسوَدُ وكتاب كتبه المنصورُ للعلاء."},{"id":508,"title":"بناء بغداد واتخاذها عاصمة للدولة العباسية .","date":["العام الهجري :146","العام الميلادي :763"],"text":"في هذا العام تكاملَ بناءُ بغداد، وكان السببُ الباعث للمنصور على بنائها أنَّ الراونديَّة لَمَّا وثبوا عليه بالكوفةِ ووقاه اللهُ شَرَّهم، بَقِيَت منهم بقيَّةٌ فخشيَ على جندِه منهم، فخرج من الكوفةِ يرتادُ لهم موضعًا لبناء مدينة، فسار في الأرض حتى بلغ الجزيرةَ، فلم يرَ موضعًا أحسنَ لوضعِ المدينة من موضعِ بغدادَ الذي هي فيه الآن؛ وذلك بأنه موضِعٌ يُغدى إليه ويُراحُ بخيراتِ ما حوله في البَرِّ والبحر، وهو مُحصَّنٌ بدجلة والفرات من هاهنا وهاهنا، لا يقدِرُ أحدٌ أن يتوصَّل إلى موضع الخليفة إلَّا على جسرٍ، وقد بات به المنصورُ قبل بنائِه لياليَ فرأى الرياحَ تهُبُّ به ليلًا ونهارًا من غير انجعارٍ ولا غبار، ورأى طِيبَ تلك البقعة وطِيبَ هوائها، وقد كان في موضِعها قُرًى ودُيور لعُبَّاد النصارى وغيرِهم، فحينئذ أمر المنصور باختطاطِها فرسموها له بالرَّمادِ، فمشى في طرقِها ومسالِكِها فأعجبه ذلك، ثم سلَّمَ كلَّ رَبعٍ منها لأميرٍ يقوم على بنائه، وأحضَرَ مِن كلِّ البلاد عمَّالًا وصنَّاعًا ومهندسين، فاجتمع عنده ألوفٌ منهم، ثم كان هو أوَّل من وضع لَبِنةً فيها بيده، وقال: بسمِ الله والحمد لله، والأرضُ لله يورثُها من يشاء من عبادِه، والعاقبة للمتَّقينَ. ثم قال: ابنُوا على بركةِ الله. وأمَرَ ببنائها مُدَوَّرةً سُمكُ سُورِها من أسفلِه خمسون ذراعًا، ومن أعلاه عشرونَ ذراعًا، وجعل لها ثمانيةَ أبواب في السُّور البرَّاني، ومثلها في الجُوَّاني، وليس كل واحد تجاهَ الآخر، ولكن جعَلَه أزْوَرَ عن الذي يليه، ولهذا سمِّيت بغداد الزَّوراء، لازوِرارِ أبوابِها بعضِها عن بعضٍ، وقيل: سمِّيت بذلك لانحرافِ دجلةَ عندها. وبنى قصرَ الإمارة في وسط البلد؛ ليكون الناسُ منه على حدٍّ سواءٍ، واختطَّ المسجِدَ الجامِعَ إلى جانب القصر، وكان الذي وضعَ قبلتَه الحجَّاجَ بن أرطأة."},{"id":509,"title":"غارات أسترخان الخوارزمي في جمع من الترك على المسلمين .","date":["العام الهجري :147","العام الميلادي :764"],"text":"فيها أغار أسترخان الخوارزمي في جمعٍ من التُّرك على المسلمين بناحية أرمينية، وسبى من المسلمين وأهلِ الذمَّة خلقًا، ودخلوا تفليس، وكان حربُ بن عبد الله مقيمًا بالموصِل في ألفينِ مِن الجند لمكان الخوارجِ الذين بالجزيرة، وسيَّرَ المنصور إلى محارَبة التُّرك جبرائيلَ بن يحيى وحَربَ بنَ عبد الله، فقاتلوهم، فهُزم جبرائيلُ وقُتِلَ حَربٌ، وقُتِل من أصحاب جبرائيلَ خلقٌ كثيرٌ."},{"id":510,"title":"خروج حسان بن مجالد الهمداني على المنصور في الموصل .","date":["العام الهجري :148","العام الميلادي :765"],"text":"خرج حسان بن مجالد بن يحيى بن مالك بن الأجدع الهمداني، وكان خروجُه بنواحي الموصِل بقريةٍ تُسمَّى بَافَخَّارى، قريب من الموصل على دجلة، فخرج إليه عسكرُ الموصِل، وعليها الصقر بن نجدة، فالتقَوا واقتَتلوا وانهزم عسكرُ الموصِل على الجِسر، وأحرق الخوارجُ أصحابُ حسَّان السوقَ هناك ونهبوه. ثم إنَّ حسانَ سار إلى الرقَّةِ ومنها إلى البحر ودخل إلى بلد السِّند، وكانت الخوارجُ مِن أهل عمان يُدخِلونَهم ويَدَعونهم، فاستأذَنَهم في المصير إليهم، فلم يجيبوه، فعاد إلى الموصِل، فخرج إليه الصقرُ أيضًا والحسَنُ بن صالح بن حسان الهمداني وبلال القيسي، فالتقَوا فانهزم الصقرُ وأُسِرَ الحسنُ بن صالح وبلال، فقتَل حسانُ بلالًا واستبقى الحسنَ؛ لأنَّه من همدان، ففارقه بعضُ أصحابه لهذا، وكان حسانُ قد أخذ رأيَ الخوارج عن خالِه حفصَ بنِ أشيم، وكان من علماء الخوارجِ وفُقَهائِهم، ولَمَّا بلغ المنصورَ خروجُ حَسَّان، قال: خارجيٌّ مِن همدان؟ قالوا: إنَّه ابن أخت حفص بن أشيم. فقال: فمن هناك؟ وإنَّما أنكر المنصورُ ذلك؛ لأن عامَّة همدان شيعةٌ لعليٍّ، وعزمَ المنصورُ على إنفاذ الجيوش إلى الموصِل والفَتكِ بأهلها، فأحضرَ أبا حنيفة، وابنَ أبي ليلى، وابنَ شبرمة، وقال لهم: إنَّ أهل الموصل شَرَطوا إليَّ أنَّهم لا يَخرُجون عليَّ، فإن فعلوا حلَّت دماؤهم وأموالهم، وقد خرجوا. فسكتَ أبو حنيفة وتكلَّم الرجُلانِ وقالا: رعِيَّتُك، فإنْ عَفَوتَ فأهلُ ذلك أنت، وإن عاقبتَ فبما يستحقُّون. فقال لأبي حنيفة: أراك سكتَّ يا شيخُ؟ فقال: يا أميرَ المؤمنين، أباحوك ما لا يملِكونَ، أرأيتَ لو أنَّ امرأةً أباحَت فرجَها بغير عقدِ نكاحٍ ومِلكِ يمينٍ، أكان يجوزُ أن تُوطأَ؟! قال: لا! وكفَّ عن أهل الموصل، وأمرَ أبا حنيفةَ وصاحِبَيه بالعودة إلى الكوفةِ."},{"id":511,"title":"استعادة العباسيين فتح طبرستان .","date":["العام الهجري :148","العام الميلادي :765"],"text":"نكث أصبهبذ طبرستان العهدَ الذي كان بينه وبين المسلمين، وقتلَ طائفةً ممَّن كان بطبرستان، فجهَّز إليه المنصورُ جيشًا بقيادة خازم بن خزيمة، وروحِ بن حاتم، ومعهم مرزوقٌ أبو الخصيب، مولى المنصور، فحاصَروه مدةً طويلة، فلما أعياهم فتحُ الحِصنِ احتالوا عليه، وذلك أنَّ أبا الخصيبِ قال: اضربوني واحلِقوا رأسي ولِحيتي، ففعلوا ذلك، فذهب إليه كأنَّه مُغاضِبٌ للمُسلِمينَ قد ضربوه وحلَقوا لحيتَه، فدخل الحِصنَ، وقال للأصبهبذ: إنَّما فعلوا ذلك بي تهمةً منهم لي أن يكونَ هوايَ معك, ففرح به الأصبهبذ وأكرَمَه وقَرَّبه، وجعل أبو الخصيب يُظهِرُ له النصحَ والخِدمةَ حتى خدَعَه، وحظِيَ عنده جدًّا وجعَلَه من جملةِ من يتولَّى فتحَ الحِصنِ وغَلْقَه، فلمَّا تمكَّنَ من ذلك كاتبَ المُسلمينَ وأعلَمَهم أنَّه سيفتحُ لهم البابَ في ليلةٍ محدَّدة، فلمَّا كانت تلك الليلةُ فتح لهم بابَ الحِصنِ فدخلوا فقتَلوا مَن فيه من المُقاتِلة وسَبَوا الذريَّة، وامتصَّ الأصبهبذ خاتمًا مسمومًا فمات. وكان فيمن أَسَروا يومئذ أمُّ منصور بن المهدي، وأم إبراهيم بن المهدي، وكانتا من بنات الملوك الحِسان."},{"id":512,"title":"ولاية الأغلب بن سالم على إفريقية .","date":["العام الهجري :148","الشهر القمري : جمادى الآخرة","العام الميلادي :765"],"text":"لَمَّا بلغ المنصورَ خروجُ محمد بن الأشعث من إفريقيَّة بعث إلى الأغلب بن سالم بن عقال بن خفاجة التميمي عهدًا بولايةِ إفريقية، وكان هذا الأغلبُ ممَّن قام مع أبي مسلم الخُراساني وقَدِم إفريقيَّةَ مع محمد بن الأشعث، فلما أتاه العهد قَدِم القيروانَ وأخرج جماعةً من قوَّاد المُضَريَّة، وسكن النَّاس. ثم خرج عليه أبو قرَّة في جمع كثير من البربر، فسار إليه الأغلبُ، فهرَبَ أبو قرَّة من غير قتال، ثم خرج عليه الحسَنُ بن حرب الكِندي، وكاتبَ جُندَ القيروان ودعاهم إلى نفسِه فأجابوه، فسار حتى دخل القيروان من غير مانع, فسار الأغلبُ إلى الحسَن بن حَرْب، واقتتلوا قتالًا شديدًا، فانهزم الحسنُ وقُتل من أصحابه جمعٌ كثير، ودخَل الأغلبُ القيروان."},{"id":513,"title":"وفاة الإمام جعفر الصادق .","date":["العام الهجري :148","الشهر القمري : شوال","العام الميلادي :765"],"text":"هو الإمام، الصَّادق، شيخ بني هاشم، أبو عبدالله جعفرُ بن محمد الباقر بن علي زين العابدين بن الحسين بن علي بن أبي طالب، القرشي، الهاشمي، العلوي، النبوي، المدني، أحد الأعلام من التابعين, وكان يلقَّبُ بالصابر، والفاضِلِ، والطاهر، وأشهرُ ألقابه الصادِقُ، ولد سنة 80, وأمه أم فروة بنت القاسم بن محمد بن أبي بكر الصديق, وأمها: هي أسماء بنت عبد الرحمن بن أبي بكر، ولهذا كان يقول: ولدني أبو بكر الصديق مرتين. قال الذهبي: \"كان يغضب من الرافضة، ويمقتهم إذا علم أنهم يتعرضون لجده أبي بكر ظاهرا وباطنا, ثم قال: هذا لا ريب فيه، ولكن الرافضة قوم جهلة، قد هوى بهم الهوى في الهاوية، فبعدا لهم\" وقال: \"أن الصادق رأى بعض الصحابة، أحسبه رأى: أنس بن مالك، وسهل بن سعد\".حاول المنصورُ أن يظفَرَ به، لكنَّه لم يقدِرْ عليه وانثنى عن ذلك، كان من أجلَّاء التابعين؛ فقيهًا عالِمًا جوادًا كريمًا زاهدا عابدا، قال ابن خلكان: \" أحد الأئمة الاثني عشر على مذهب الإمامية، وكان من سادات أهل البيت ولقب بالصادق لصدقه في مقالته وفضلُه أشهر من أن يذكر، وله كلام في صنعة الكيمياء والزجر والفأل\". أورد الذهبيُّ بإسنادٍ قال إنه صحيح، عن سالم بن أبي حفصة قال: \"سألتُ أبا جعفرٍ محمدَ بنَ عليٍّ وابنَه جعفرًا عن أبي بكرٍ وعمر، فقالا: يا سالمُ، تولَّهَما وابرأْ مِن عدُوِّهما؛ فإنهما كانا إمامَيْ هُدًى. وقال لي جعفرٌ: يا سالم، أيسُبُّ الرجُلُ جَدَّه؟! أبو بكرٍ جَدِّي، فلا نالَتني شفاعةُ محمَّدٍ يومَ القيامة إن لم أكنْ أتولَّاهما وأبرأُ من عدوِّهما!\" توفِّي في المدينة ودُفِنَ في البقيعِ."},{"id":514,"title":"خروج الأستاذ سيس (الفارسي) على المنصور في خرسان .","date":["العام الهجري :150","العام الميلادي :767"],"text":"فيها خرج أهل خراسان على المنصور مع الأستاذ سيس حتى اجتمع له فيما قيل ثلاثمئة ألف مقاتل من بين فارس وراجل، سائرُهم من أهل هراة وباذغيس وسجستان، واستولى على أكثر خراسان، وعَظُم الخطبُ فنهض لحربه الأخثم المروروذي. فقتل الأخثم واستُبيح عسكُره، فوجه المنصورُ- وهو بالراذان- خازمَ بن خزيمة إلى المهديِّ، فولَّاه المهدي محاربةَ أستاذ سيس وضمَّ إليه القُوَّاد. فسار حازم بن خزيمة في جيشٍ عظيم فالتقى الجمعان وصبَرَ الفريقان وقُتِلَ خلقٌ كثير، حتى قيل إنه قُتِلَ في هذه الوقعةِ سبعون ألفًا وأَسَروا أربعةَ عشر ألفًا، وانهزم الأستاذ سيس في طائفةٍ إلى جبل, ثم أمرَ حازم بالأسرى فضُرِبَت أعناقُهم كلِّهم، وكانوا أربعة عشر ألفًا، ثمَّ حاصر أستاذ سيس مدَّةً. ثم نزل على حُكمِهم، فقُيِّدَ هو وأولادُه، ثم أُعدم, وأُطلِقَ أصحابُه، وكانوا ثلاثينَ ألفًا. وكتب إلى المهديِّ بذلك، فكتب المهديُّ إلى المنصور، وقيل إن أستاذ سيس ادَّعى النبوةَ وأظهَرَ أصحابُه الفِسقَ وقطْعَ السبيلِ. وقيل: إنه جد الخليفة المأمون أبو أمه وهي مراجل بنت سيس كانت إحدى إيماء الرشيد أنجبت منه المأمون فقط."},{"id":515,"title":"وفاة الإمام أبي حنيفة النعمان .","date":["العام الهجري :150","الشهر القمري : رجب","العام الميلادي :767"],"text":"هو الإمام، فقيه الملة، أبو حنيفة النُّعمانُ بنُ ثابت بن زوطى التيميُّ ولاءً، فقيهُ العراقِ إمامُ الحنفيَّة، أحد الأئمة الأربعة المشهورين أصحاب المذاهب المعروفة، يقال: إنه من أبناء الفرس ولد سنة 80, وكان حسن الوجه حسن المجلس، شديد الكرم حسن المواساة لإخوانه، وكان ربعة من الرجال، وقيل كان طوالا تعلوه سمرة،. أدرك أبو حنيفة أربعة من الصحابة، رضوان الله عليهم وهم: أنس بن مالك وعبد الله بن أبي أوفى بالكوفة، وسهل بن سعد الساعدي بالمدينة، وأبو الطفيل عامر بن واثلة بمكة، ولم يلق أحداً منهم ولا أخذ عنه، وأصحابه يقولون: لقي جماعة من الصحابة وروى عنهم، ولم يثبت ذلك عند أهل النقل. أخذ الفقه عن حماد بن أبي سليمان وسمع عطاء بن أبي رباح وهو أكبر شيخ له, وأبا إسحاق السبيعي ومحارب بن دثار والهيثم بن حبيب الصواف ومحمد بن المنكدر ونافعاً مولى عبد الله بن عمر، وكان معروفًا بالزهد والورَع وكثرة العبادة، والوقار والإخلاص وقوة الشخصيَّة، كثير التعطر، لا يتكلم إلا جوابا، ولا يخوض فيما لا يعنيه. قال ابن المبارك: ما رأيت رجلا أوقر في مجلسه، ولا أحسن سمتا وحلما من أبي حنيفة. كان خزازا يبيع الخز. قيل لمالك: هل رأيت أبا حنيفة فقال: نعم، رأيت رجلاً لو كلمك في هذه السارية أن يجعلها ذهباً لقام بحجته. لم يرضَ أن يليَ القَضاءَ لأحدٍ، وطلبه المنصورُ للقضاء فأبى، وكان منها حبسُه، وقيل: مات في الحبسِ ببغداد، قال إسماعيل بن حماد بن أبي حنيفة: \"مررت مع أبي بالكناسة – موضع بالكوفة- فبكى، فقلت له: يا أبت ما يبكيك فقال: يا بني، في هذا الموضع ضرب ابن هبيرة أبي عشرة أيام، في كل يوم عشرة أسواط، على أن يلي القضاء، فلم يفعل\". وقيل: إنَّه توفِّيَ وهو يصلِّي."},{"id":516,"title":"أبو جعفر المنصور يبدأ ببناء مدينة الرصافة .","date":["العام الهجري :151","العام الميلادي :768"],"text":"شرع المنصورُ في بناء الرصافة لابنه المهدي بعد مَقدَمِه من خراسان، وكان سبب بنائِها أنَّ بعضَ الجند شغَّبوا على المنصور وحاربوه على باب الذَّهبِ، فدخل عليه قُثَمُ بنُ العبَّاس، وهو شيخُهم، وله الحرمةُ والتقدُّم عندهم، فاستشاره المنصور، فقال له أن يتركَ الأمرَ له، فقام قُثَم بحيلةٍ فافترق الجند، فصارت مُضَرُ فِرقةً، وربيعةُ فرقة، والخراسانية فرقة. فقال قُثَم للمنصور: قد فرَّقتُ بين جُندِك وجعلتُهم أحزابًا، كلُّ حزبٍ منهم يخافُ أن يُحدِثَ عليك حدثًا فتضرِبَه بالحزبِ الآخر، وقد بقيَ عليك في التدبير بقيَّة، وهي أن تعبُرَ بابنِك المهدي فتُنزِلَه في ذلك الجانب، وتحَوِّل معه قطعةً من جيشِك فيصير ذلك بلدًا وهذا بلدًا، فإن فسدَ عليك أولئك ضربتَهم بهؤلاء، وإن فسدَ عليك هؤلاء ضربتَهم بأولئك، وإن فسد عليك بعضُ القبائل ضربتَهم بالقبيلة الأخرى (على مبدأ: فَرِّقْ تَسُد)، فقَبِلَ رأيه واستقام مُلكُه، وبنى الرصافة وهي في الجانب الشرقي من بغداد، وجعل لها سورًا وخندقًا، وعَمِلَ عندها ميدانًا وبستانًا، وأجرى إليها الماءَ مِن نهرِ المهدي"},{"id":517,"title":"تجديد البيعة للمنصور ثم ولده المهدي .","date":["العام الهجري :151","العام الميلادي :768"],"text":"جدَّد المنصورُ البيعةَ لنفسه ثمَّ لولده المهدي من بعده، ولعيسى بن موسى مِن بعدهما، وجاء الأمراءُ والخَواصُّ، فبايعوا وجعلوا يقبِّلونَ يد المنصور ويدَ ابنه ويلمسونَ يد عيسى بن موسى ولا يقبِّلونَها."},{"id":518,"title":"خروج شقنا بن عبد الواحد في الأندلس .","date":["العام الهجري :151","العام الميلادي :768"],"text":"ثار في الشرق من الأندلس رجلٌ من بربر مكناسة، كان يعلِّمُ الصبيان، وكان اسمُه شقنا بن عبد الواحد، وكانت أمُّه تُسمى فاطمة، وادَّعى أنَّه من ولد فاطمةَ رَضِيَ الله عنها، ثم مِن ولَد الحُسين بن علي رضي الله عنهما، وتَسمَّى بعبد الله بن محمَّد، وسكن شنت برية، واجتمع عليه خلقٌ كثير من البربر، وعظُمَ أمرُه، وسار إلى عبد الرحمن الداخِل الأموي فلم يقِف له وراغ في الجبالِ، فكان إذا أمِنَ انبسط، وإذا خاف صَعِدَ الجبال بحيث يصعُبُ طَلبُه، فاستعمل عبد الرحمن على طليطِلة حبيبَ بن عبد الملك، فاستعمل حبيبٌ على شنت برية سليمانَ بنَ عثمان بن مروان بن أبان بن عثمان بن عفان، وأمَرَه بطلب شقنا. فنزل شقنا إلى شنت برية، وأخذ سليمانَ فقتله، واشتدَّ أمرُه، وطار ذِكرُه وغلب على ناحية قورية، وأفسدَ في الأرض فعاد عبد الرحمن الداخل فغزاه في سنة 152 بنفسِه، فلم يثبُتْ له فأعياه أمرُه، فعاد عنه وسيَّرَ إليه سنة ثلاث وخمسين بدرًا مولاه، فهَرَب شقنا وأخلى حصنَه شطران، ثم غزاه عبد الرحمن بنفسِه سنة 154، فلم يثبُتْ له شقنا، ثم سيَّرَ إليه سنة خمس وخمسين أبا عثمان عبيد الله بن عثمان، فخَدَعه شقنا وأفسد عليه جُندَه، فهرب عبيد الله، وغَنِم شقنا عسكرهَ وقتلَ جماعةً من بني أميَّة كانوا في العسكر. وفي سنة خمس وخمسين أيضًا سار شقنا بعد أن غَنِم عسكرَ عُبَيد الله إلى حصن الهواريين المعروف بمدائن، وبه عاملٌ لعبد الرحمن، فمكرَ به شقنا حتى خرج إليه، فقتله شقنا وأخذ خيلَه وسلاحَه وجميعَ ما كان معه، ثم بقي أمرُه مستمرًّا إلى أن اغتالَه بعضُ أصحابه سنة 160"},{"id":519,"title":"وفاة محمد بن إسحاق صاحب السيرة النبوية .","date":["العام الهجري :151","العام الميلادي :768"],"text":"هو العلامة، الحافظ، الأخباري أبو بكر، وقيل: أبو عبد الله محمد بن إسحاق بن يسار بن خيار, القرشي, المدني, المطَّلِبي ولاءً، العلَّامة, الحافظ, الأخباري, صاحب \"السيرة النبوية\" وُلِدَ ابنُ إسحاق: سنةَ ثمانين. وقيل إنه رأى أنس بن مالك بالمدينة, انتقل من المدينة إلى بغداد وسكنَها، كان من أقدم المؤرخينَ، ومن أشهر مؤلَّفاته السيرةُ النبويَّة، وبها اشتُهِر، قيل: إنه ألَّفها بأمرٍ من المنصورِ، وقال الشافعي: إن النَّاسَ كلَّهم عيالٌ عليه في السيرة، قال أبو زرعة الدمشقي: \"ابن إسحاق رجل قد اجتمع الكبراء من أهل العلم على الأخذ عنه، منهم: سفيان، وشعبة، وابن عيينة، والحمادان، وابن المبارك، وإبراهيم بن سعد, وروى عنه من القدماء: يزيد بن أبي حبيب، وقد اختبره أهل الحديث، فرأوا صدقا وخيرا، مع مدح ابن شهاب له\".  توفِّيَ في بغدادَ."},{"id":520,"title":"خروج الخوارج الصفرية ببلاد أفريقية .","date":["العام الهجري :153","العام الميلادي :769"],"text":"خرجَت الخوارجُ من الصفريَّة وغيرهم ببلاد إفريقية. فاجتمعَ منهم ثلاثمائة ألف وخمسون ألفًا، ما بين فارس وراجل، وعليهم أبو حاتم الأنماطي، وأبو عبَّاد وانضم إليهم أبو قرة الصفري في أربعين ألفًا، فقاتلوا نائبَ إفريقية فهَزَموا جيشَه وقتلوه، وهو عمَرُ بن حفص بن عثمان بن أبي صفرة الذي كان نائبَ السِّند، قتله هؤلاء الخوارجُ, وأكثرت الخوارجُ الفسادَ في البلاد، وقتلوا الحريمَ والأولاد، ثمَّ إن أبا جعفر المنصور سيَّرَ يزيد بن حاتم بن قبيصة بن المهلب بن أبي صفرة إلى إفريقيةَ في خمسين ألفًا لحربِ الخوارجِ الذين قتلوا عُمَرَ بن حفص. فدخل يزيد بن حاتم إفريقيَّة، وقتَلَ أبا حاتم، وملَكَ القيروانَ وسائِرَ الغرب."},{"id":521,"title":"أبو جعفر المنصورُ يبدأ بزيارة إلى الشامِ وبيتِ المقدس .","date":["العام الهجري :154","العام الميلادي :770"],"text":"سار أبو جعفر المنصورُ الخليفةُ العباسي إلى الشامِ وبيتِ المقدس، وأراد المنصور بناء الرافقة، فمنعه أهلُ الرقَّة، فهَمَّ لمحاربتِهم."},{"id":522,"title":"وفاة أبي عمرو بن العلاء البصري أحد القراء السبعة .","date":["العام الهجري :154","العام الميلادي :770"],"text":"هو شيخ القراء والعربية أبو عمرو العريان وقيل: زَبَّان بن العلاء بن عمار بن العُريان التميمي ثم المازني البصري، أحد القرَّاء السبعة، وُلد بمكة عام 68، وقيل 70, وأمه: من بني حنيفة. ونشأ بالبصرة، أحدُ التابعين، سمع من أنسِ بن مالك. قرأ القرآن على: سعيد بن جبير، ومجاهد، ويحيى بن يعمر، وعكرمة، وابن كثير، وطائفة, وكان من أئمَّة اللغة والأدب، ومن أعلَمِ الناسِ بالقرآن والعربية وأيَّامِ الناس، برز في الحروفِ وفي النحو، وتصدَّر للإفادةِ مُدَّة، واشتهر بالفصاحةِ والصدق وسَعةِ العلم، انتصب للإقراءِ أيامَ الحسَن البصري، كانت دفاترُه ملءَ بيتٍ إلى السقف، ثم تنسَّك فأحرقها، توفِّيَ في الكوفة."},{"id":523,"title":"أمر المنصور ببناء الرافقة وببناء سور وخندق حول الكوفة .","date":["العام الهجري :155","العام الميلادي :771"],"text":"الرافقة مدينة كانت متَّصلة البناء بالرقة، وهما على ضفَّة الفرات، وبينهما مقدار ثلاثمائة ذراع، ثم إن الرقَّة خربت وغلب اسمُها على الرافقة وصار اسمُ المدينة الرقة (وهي الموجودة حاليًّا في سوريا) ففي هذه السَّنة أمرَ الخليفةُ العباسي المنصور ببناء الرافقة، على منوالِ بناء بغداد، فلما أراد أهلُ الرقَّة منْعَه من بنائها همَّ في محاربتِهم. كما أمرَ ببناء سورٍ وعَمَلِ خندقٍ حول الكوفة، وأخذَ ما غَرِمَ على ذلك من أموالِ أهلِها، من كلِّ إنسانٍ مِن أهل اليسار أربعينَ درهمًا، وقد فرضَها أولًا خمسة دراهم، خمسة دراهم، ثم جباها أربعين أربعين."},{"id":524,"title":"خروج الخوارج الصفرية على أميرِهم بمدينة سجلماسة .","date":["العام الهجري :155","العام الميلادي :771"],"text":"أنكرت الخوارجُ الصفرية المجتَمِعةُ بمدينة سجلماسة على أميرِهم عيسى بن جرير أشياءَ، فشَدُّوه وِثاقًا، وجعلوه على رأس الجبلِ، فلم يزَلْ كذلك حتى مات، وقَدَّموا على أنفُسِهم أبا القاسم سمكو بن واسول المكناسي جدَّ مدرار."},{"id":525,"title":"ثورة الأرمن الصنارية .","date":["العام الهجري :155","العام الميلادي :771"],"text":"ثار الأرمن الصنارية بزَعامة موشيغ ماميكونيان، وسمباط بن آشوط، وامتنعوا عن دفع الخَراج، فأمدَّ المنصورُ الحسَن بن قحطبة أمير أرمينية بجيشٍ يضُمُّ كبارَ القادة، فالتقى الطرفانِ وجرت معركةٌ قرب جبل أرارات، وعُرِفَت المعركة في التاريخ الأرمني باسم بيغرافند، وفيها تمَّ قمعُ هذه الثورة وقتْلُ موشيغ، ودخلَ جيشُ المسلمين مدينة تفليس."},{"id":526,"title":"فتنة الخوارج في أفريقيا .","date":["العام الهجري :156","العام الميلادي :772"],"text":"هرب عبد الرحمن بن حبيب- الذي كان أبوه أميرَ إفريقية- مع الخوارج، واتَّصل بكتامة، فسيَّرَ يزيد بن حاتم أمير إفريقية العسكرَ في أثَره، وقاتلوا كتامة. فلمَّا كانت هذه السَّنةُ سيَّرَ يزيدُ عسكرًا آخرَ مددًا للذين يقاتلون عبد الرحمن، فاشتد الحصارُ على عبد الرحمن، فمضى هاربًا، وفارقَ مكانَه، فعادت العساكرُ عنه، ثم ثار في هذه السنة على يزيد بن حاتم أبو يحيى بن فانوس الهواري بناحية طرابلس، فاجتمع عليه كثيرٌ من البربر، وكان عسكرٌ ليزيد بن حاتم مع عامل البلد، فخرج العاملُ والجيش معه، فالتَقَوا على شاطئ البحرِ من أرض هوارة، فاقتتلوا قتالًا شديدًا، فانهزم أبو يحيى بن فانوس وقُتِلَ عامَّة أصحابه، وسكنَ النَّاسُ بإفريقيَّة وصَفَت ليزيد بن حاتم."},{"id":527,"title":"عصيان أهل إشبيلية على عبد الرحمن الداخل .","date":["العام الهجري :156","العام الميلادي :772"],"text":"سار عبد الرحمن الداخل إلى حرب شقنا، وقصدَ حصنَ شيطران، فحصَرَه وضيَّقَ عليه، فهرب إلى المفازة كعادته، وكان قد استخلف على قرطبة ابنَه سُليمان، فأتاه كتابُه يخبِرُه بخروج أهل إشبيلية مع عبد الغفار وحيوة بن ملابس عن طاعتِه، وعصيانِهم عليه، واتَّفَق مَن بها من اليمانية معهما، فرجع عبد الرحمن ولم يدخُل قرطبة، وهاله ما سَمِعَ من اجتماعِهم وكثرتِهم، فقدَّمَ ابنَ عمه عبد الملك بن عمر (كان شهاب آل مروان)، وبقي عبد الرحمن خَلفَه كالمَدَدِ له، فلما قارب عبد الملك أهل إشبيلية قدَّمَ ابنَه أمية ليعرف حالهم، فرآهم مستيقظينَ، فرجع إلى أبيه، فلامَه أبوه على إظهارِ الوهَنِ، وضرَبَ عُنُقَه، وجمعَ أهل بيته وخاصَّته، وقال لهم: طُرِدْنا من المشرق إلى أقصى هذا الصِّقع، ونُحسَدُ على لقمةٍ تُبقي الرَّمَق؛ اكسروا جفون السيوف، فالموتُ أولى أو الظَّفَر، ففعلوا، وحمل بين أيديهم، فهزَمَ اليمانية وأهلَ إشبيلية، فلم تقُمْ بعدها لليمانية قائمةٌ، وجُرِحَ عبد الملك. فأتاه عبد الرحمن وجُرحُه يجري دمًا، وسيفه يقطُرُ دمًا، وقد لصِقَت يدُه بقائمِ سَيفِه، فقَبَّله بين عينيه، وقال: يا ابنَ عَمِّ، قد أنكحتُ ابني وولي عهدي هشامًا ابنتَك فلانة، وأعطيتُها كذا وكذا، وأعطيتُك كذا وأولادَك كذا، وأقطعتُك وإياهم، وولَّيتكم الوزارة. وعبد الملك هو الذي ألزم عبد الرحمن بقَطعِ خُطبة المنصور، وقال له: تقطعُها وإلَّا قتلتُ نفسي, وكان قد خطبَ له عشرةَ أشهُر، فقطعها. وكان عبد الغفار وحيوة بن ملابس قد سَلِمَا من القتل. فلما كانت سنة 157 سار عبد الرحمن إلى إشبيلية، فقتل خلقًا كثيرًا ممَّن كان مع عبد الغفار وحيوة ورجع. وبسبَبِ هذه الوقعة وغِشِّ العرب، مال عبد الرحمن إلى اقتناءِ العبيد."},{"id":528,"title":"وفاة حمزة الزيات أحد القراء السبعة .","date":["العام الهجري :156","العام الميلادي :772"],"text":"هو الإمام العلم أبو عمارة حمزةُ بن حبيبِ بنِ عمارة التيميُّ المعروف بالزيَّات، ولد سنة 80. قيل له \" الزيات \" لأنه كان يجلب الزيت من الكوفة إلى حلوان, ويجلب إلى الكوفة الجبن والجوز. أصله من سبي فارس، وقيل: ولاؤه لبني عجل، وقيل: ولاؤه لتيم الله بن ثعلبة. أدرك عددًا من الصحابة, أحدُ القراء السبعة، من أهل الكوفةِ، تلا عليه طائفةٌ، منهم الأعمش، وحدَّثَ عنه كثيرٌ، منهم الثوريُّ، كان إمامًا قَيِّمًا لكتاب الله، قانتًا لله، ثخينَ الورع، رفيعَ الذِّكر، عالِمًا بالحديث والفرائض، عديم النظير في وقته علما وعملا، قال الثوري: ما قرأ حمزةُ حرفًا إلَّا بأثَرٍ. قال أسود بن سالم: سألت الكسائي عن الهمز والإدغام: ألكم فيه إمام؟ قال: نعم، حمزة، كان يهمز ويكسر، وهو إمام من أئمة المسلمين، وسيد القراء والزهاد، لو رأيته لقرت عينك به من نسكه. وقال حسين الجعفي: ربما عطش حمزة فلا يستسقي كراهية أن يصادف من قرأ عليه. وذكر جرير بن عبد الحميد أن حمزة مر به فطلب ماء قال: فأتيته فلم يشرب مني لكوني أحضر القراءة عنده. وقال يحيى بن معين: سمعت ابن فضيل يقول: ما أحسب أن الله يدفع البلاء عن أهل الكوفة إلا بحمزة."},{"id":529,"title":"بناء قصر الخلد في بغداد .","date":["العام الهجري :157","العام الميلادي :773"],"text":"بنى المنصور قصرَه المسمَّى بالخُلد في بغداد على شاطئ دجلة، تفاؤلًا بالتَّخليد في الدنيا، فعند كمالِه مات وخرِبَ القَصرُ من بعده، وكان المستحِثُّ في عمارته أبان بن صدقة، والربيع مولى المنصور وهو حاجبُه."},{"id":530,"title":"وفاة الإمام الأوزاعي .","date":["العام الهجري :157","العام الميلادي :773"],"text":"هو إمام أهل الشام أبو عمرو عبد الرحمن بن عمرو بن محمد الأوزاعي، من كبار تابعي التابعين. ولقب بالأوزاعي نسبة إلى الأوزاع وهي فرع من همدان, وقيل الأوزاع قرية بدمشق على طريق باب الفراديس، ولم يكن أبو عمرو منهم، وإنما نزل فيهم فنسب إليهم وهو من سبي اليمن. وُلِدَ في بعلبك سنة 88 ونشأ في البقاع يتيم الأب, ثم انتقلت به أمه إلى بيروت، كان فوق الربعة خفيف اللحية به سمرة، وكان يخضب بالحناء. طلب الحديثَ فصار إمامَ أهل الشام، وكان ثقة مأمونا، فاضلا خيرا، كثير العلم والحديث والفقه، حجة, ذا أدبٍ وورع، وزهدٍ عُرِضَ عليه القضاء وأبى, صاحِبُ مذهبٍ فقهيٍّ مُندثِرٍ، إلَّا أنَّ عِلمَه لم يجمَعْه تلاميذُه في الكتب، على خلافِ ما فعل أتباعُ أبي حنيفة النعمان وغيره، فحافظوا على مذاهِبِ مُعَلِّميهم. وأنشأ مذهبًا مستقلًّا مشهورًا عُمِلَ به مدَّةً عند فقهاءِ أهل الشام والأندلس ثمَّ اندرس، ولكنْ ما زالت له بعض المسائل الفقهيَّة في أمهَّات الكتب، وكان الأوزاعي قد التزم في فتاويه بالتوقف عند النصوص الصحيحة من الكتاب والسنة. سكن بيروت وبها توفِّيَ."},{"id":531,"title":"وفاة الفقيه الحنفي زفر بن الهذيل .","date":["العام الهجري :158","الشهر القمري : شعبان","العام الميلادي :775"],"text":"هو العلَّامة الفقيهُ المجتهدُ الربَّاني الحنفي، أبو الهذيل زُفَر بن الهذيل بن قيس بن سلم وُلد سنة 110 في العراق. وكانت أسرة زُفر على جانبٍ مِن سَعة الرزق وبُحبوحة العيش، وهو ما ساعَده على الانصراف إلى طلب العلمِ دون أن يشغَلَ نفسَه بأعباءِ الحياة، فحَفِظَ القرآنَ صغيرًا واستقام به لسانُه، وتفتَّحَت مواهِبُه واستعَدَّت لطلب العلم، ومالت نفسُه ورَغِبَت في تلقِّي الحديثِ النبوي، فتردَّدَ على حلقاتِه واتصل بشيوخِه الأبرار، وفي مقدِّمتِهم محدِّث الكوفة سليمان بن مهران المعروف بالأعمش، ويحيى بن سعيد الأنصاري، وسعيد بن أبي عَروبة، وإسماعيل بن أبي خالد، ومحمد بن إسحاق، وأيوب السختياني في أصبهان. ثم ذهب إلى أصبهان مع والده، في خلافة الوليد بن يزيد بن عبد الملك، وكان أبوه قد تولَّى أمرَ أصبهان، وفي الفترة التي أقامها زُفَرُ في أصبهان أخذ عن عُلَمائها ومحدِّثيها المشهورين، حتى أصبحَ حافظًا مُتقنًا، وثِقةً مأمونًا. ولَمَّا رسخت قدمه في السُّنَّة أقبل عليه طلابُ العِلمِ يتعلَّمون على يديه، ويروونَ عنه أحاديثَ رَسولِ الله صلى الله عليه وسلم، ومن أشهَرِ هؤلاء: أبو نُعَيم الأصبهاني، وحسان بن إبراهيم، وأكثم بن محمد، وعبد الله بن المبارك، ووكيع بن الجرَّاح، وخالد بن الحارث. وكان زُفَرُ محدِّثًا بصيرًا وخبيرًا بفنون الحديثِ، وناقدًا دقيقًا، ويصف أبو نُعَيم ذلك بقوله: \"كنتُ أعرِضُ الحديثَ على زُفَر، فيقول هذا ناسِخٌ وهذا منسوخ، وهذا يؤخَذُ به وهذا يُرفَض\". وبلغ من سَعةِ عِلمِه وتمكُّنه من فنون الحديث وقدرتِه على التمييز بين درجاتِ الحديث من حيثُ الصِّحةُ والضَّعفُ أنه كان يقول للحافظ أبي نعيم: \"هاتِ أحاديثَك، أُغَرْبِلْها لك غَربلةً\"، ولَمَّا عاد إلى الكوفة وكانت تموجُ بحلقاتِ العلماء، استأنف اتصالَه بكبار الأئمة، وانتظم في حلقاتِهم، ونهَل من عِلمِهم، حتى اتَّصل بأبي حنيفة النعمان، وكان قد انتهت إليه رئاسةُ الفِقه في العراقِ، واتَّسَعت شهرتُه، فلازمه ملازمةً لصيقةً، حتى غلب عليه الفقهُ وعُرِفَ به، فقيل: \"كان صاحِبَ حديثٍ، ثم غلَبَ عليه الفِقهُ\". ويذكرُ أبو جعفر الطحاوي أنَّ سبب انتقال زُفَر إلى حلقةِ أبي حنيفةَ مسألةٌ فقهيَّةٌ أعيَتْه وأعيَتْ أصحابَه من المحدِّثين، وعجزوا عن حَلِّها، فلما أتى بها إلى أبي حنيفة أجابه إجابةً شافيةً، فكان ذلك أحدَ الأسبابِ التي دفعت بزُفَرَ إلى الاشتغالِ بالفقه والإقبال عليه، فالتزم أبا حنيفةَ أكثر من عشرين سنة، ووجد فيه الفَهمَ العميقَ والفِكرَ السَّديد، ومالت نفسُه إليه. ولَمَّا توفِّي أبو حنيفة النعمان خلَفَه في حلقتِه زُفَرُ بن الهذيل بإجماعِ تلامذةِ الإمام دونَ مُعارضةٍ، وقد رفض منصِبَ القضاء حين عُرِضَ عليه، وظل منقطعًا إلى العِلمِ، وقد توفِّيَ وهو في الثامنة والأربعين. قال الذهبي: ذكَره يحيى بن مَعين، فقال: ثقةٌ مأمون"},{"id":532,"title":"وفاة الخليفة العباسي أبي جعفر المنصور .","date":["العام الهجري :158","الشهر القمري : ذي الحجة","العام الميلادي :775"],"text":"هو الخليفة العباسي أبو جعفر المنصور عبد الله بن محمد بن علي الهاشمي العباسي, وأمه: سلامة البربريَّة. وُلِدَ سنة 95, وكان أسمرَ, طويلًا, نحيفًا, مَهيبًا, خفيفَ العارِضَينِ, مُعرق الوجه, رحْبَ الجبهة, كأنَّ عينيه لسانان ناطقان, تخالِطُه أبَّهة المُلك بِزِيِّ النسَّاك, تَقبَلُه القلوبُ، وتَتبَعُه العيون, وكان فحْلَ بني العباس؛ هيبةً وشجاعةً، ورأيًا وحزمًا، ودهاءً وجبروتًا، وكان جمَّاعًا للمال, حريصًا تاركا للَّهوِ واللَّعب, كامِلَ العقلِ بعيدَ الغَورِ، حسَن المشاركةِ في الفقهِ والأدب والعِلم. أباد جماعةً كبارًا حتى توطَّدَ له المُلك، ودانت له الأمَمُ على ظُلمٍ فيه، وقُوَّةِ نَفسٍ، ولكنَّه يرجِعُ إلى صِحَّة إسلامٍ وتديُّنٍ في الجُملة، وتَصَوُّنٍ وصلاةٍ وخيرٍ، مع فصاحةٍ وبلاغةٍ وجَلالةٍ، وعظَ المنصور عمرو بن عبيد شيخ المعتزلة فأبكاه، وكان المنصورُ يهابُ عَمرًا ويُكرِمُه، وقد كان المنصورُ يُصغي إلى أقوال المنجِّمين، وهذا من هناتِه مع فضيلتِه. كان حاكمًا على ممالك الإسلام بأسرِها, سوى جزيرة الأندلس، وكان ينظُرُ في حقيرِ المال، ويثَمِّرُه، ويجتهد بحيث إنَّه خلَّفَ في بيوت الأموالِ مِن النقدين أربعة عشر ألف ألف دينار، وستمئة ألف ألف درهم، وكان كثيرًا ما يتشبَّه بالثلاثة في سياسته وحَزمِه، وهم: معاوية، وعبد المَلِك، وهشام. لَمَّا رأى المنصورُ ما يدلُّ على قُربِ مَوتِه سار للحَجِّ، فلمَّا وصل إلى بئر ميمون مات بها مع السحَرِ قبل أن يصِلَ مكة، ولم يحضُرْه عند وفاتِه إلَّا خَدَمُه، والربيعُ مولاه، فكتم الربيعُ مَوتَه، واشتغلوا بتجهيزِ المنصور، ففرغوا منه العصرَ، وكُفِّنَ، وغطِّيَ وجهُه وبدَنُه، وجُعِلَ رأسُه مكشوفًا لأجل إحرامِه، وصلَّى عليه عيسى بن موسى، وقيل: إبراهيم بن يحيى بن محمد بن علي بن عبد الله بن عباس، ودُفِنَ في مقبرة المُعَلَّاة، وحَفَروا له مائة قبرٍ ليغُمُّوا على النَّاسِ، ودُفِنَ في غيرها، عاش أربعًا وستِّينَ سنة، وكانت مدة خلافته اثنتين وعشرين سنة إلَّا أربعة وعشرين يومًا."},{"id":533,"title":"محمد بن عبد الله المهدي يتولى الخلافة العباسية .","date":["العام الهجري :158","الشهر القمري : ذي الحجة","العام الميلادي :775"],"text":"كان المنصورُ عَهِدَ بالخلافة لولَدِه المهدي محمد بن عبد الله من بعدِه بعد أن اضطرَّ عيسى بن موسى إلى خلعِ نَفسِه من ولاية العهدِ، فلما توفِّي المنصورُ في الحج كُتِمَ أمرُ وفاتِه، حتى أُخِذَت البيعةُ لابنه المهدي، وبُويِعَ له بين الرُّكنِ والمقام، عُرِفَ المهديُّ بسماحتِه وكرَمِه ورَدِّه للمظالمِ."},{"id":534,"title":"غزو العباسيين بلاد الروم الغربية والشرقية .","date":["العام الهجري :159","العام الميلادي :775"],"text":"بعد أن تولَّى المهدي الخلافةَ بعث العباسَ بن محمد على رأسِ جيشٍ إلى بلاد الروم كما أرسل جيشًا آخر إلى بلاد الهند، وكان متَّجهًا بصورة عامة إلى بلاد الروم، حيث ما تنفكُّ الصوائفُ من الثغور فتُغيرُ على أرض الروم، وإن كانت لم تُحدِثْ فتوحات واسعة أو تضمَّ بلادًا جديدة بشكل دائمٍ إلَّا أنَّ الانتصاراتِ كانت كبيرةً، والغنائمُ كثيرةً، والأسرى كذلك."},{"id":535,"title":"خروج يوسف البرم الحروري بخراسان .","date":["العام الهجري :160","العام الميلادي :776"],"text":"خرجَ يوسف بن إبراهيم، المعروفُ بالبرم، بخراسان، منكِرًا هو ومن معه على المهديِّ سيرتَه التي يسيرُ بها، واجتمع معه بشَرٌ كثير، فتوجَّه إليه يزيد بن مزيد الشيباني، وهو ابنُ أخي معن بن زائدة، فلَقِيَه فاقتتلا، حتى صارا إلى المعانقة، فأسره يزيدُ بن مزيد وبعثَ به إلى المهدي، وبعثَ معه وجوهَ أصحابه، فلمَّا بلغوا النهروان حُمِلَ يوسفُ على بعيرٍ، قد حُوِّلَ وجهُه إلى ذَنَبه، وأصحابُه مثلُه، فأدخلوهم الرصافة على تلك الحال، وقُطِعَت يدا يوسُفَ ورِجلاه، وقُتِلَ هو وأصحابُه، وصُلِبوا على الجسر. وقد قيل: إنَّه كان حروريًّا، وتغلَّبَ على بوشنج وعليها مصعب بن زريق، جدُّ طاهر بن الحسين، فهرب منه، وتغلَّبَ أيضًا على مرو الروذ والطالقان والجوزجان، وقد كان من جملةِ أصحابه أبو معاذ الفريابي، فقُبِضَ معه."},{"id":536,"title":"فتح مدينة باربد .","date":["العام الهجري :160","العام الميلادي :776"],"text":"كان المهدي قد سيَّرَ جيشًا في البحر، وعليهم عبد الملك بن شهاب المسمعي إلى بلاد الهندِ في جمعٍ كثيرٍ مِن الجند والمتطوِّعة، وفيهم الربيع بن صبيح، فساروا حتى نزلوا على باربد، فلمَّا نزلوها حصَروها من نواحيها، وحرَّضَ الناسُ بعضُهم بعضًا على الجهادِ، وضايقوا أهلَها، ففتَحَها اللهُ عليهم عَنوةً واحتمى أهلُها بالبلد الذي لهم، فأحرقه المسلمونَ عليهم، فاحتَرَق بعضُهم، وقُتِل الباقون، واستُشهِدَ من المسلمين بضعةٌ وعشرونَ رجلًا، وأفاءها اللهُ عليهم، فهاج عليهم البحرُ، فأقاموا إلى أن يطيبَ، فأصابَهم مرَضٌ في أفواهِهم، فمات منهم نحو من ألفِ رجلٍ فيهم الربيع بن صبيح، ثم رجعوا، فلما بلَغوا ساحلًا من فارس يقال له بحر حمران عصَفَت بهم الريح ليلًا، فانكسَرَ عامَّةُ مراكِبِهم، فغرق البعضُ، ونجا البعض."},{"id":537,"title":"المهدي يلغي نسب آل زياد بمعاوية بن أبي سفيان .","date":["العام الهجري :160","العام الميلادي :776"],"text":"كان سببُ إلغاء نسَبِ آل زياد الذي كان معاويةُ قد استلحَقَه، وكان يقالُ له: زيادُ بن أبيه، هو أنَّ رجلًا من آل زياد قَدِمَ عليه يقال له الصغدي بن سلم بن حرب بن زياد، فقال له المهدي: من أنت؟ فقال: ابنُ عَمِّك. فقال: أيُّ بني عمي أنت؟ فذكر نسَبَه، فقال المهدي: يا ابنَ سُميَّة الزانية! متى كنتَ ابنَ عمِّي؟ وغَضِبَ وأمَرَ به، فوُجِئَ في عنقِه وأُخرِجَ، وسأل عن استلحاقِ زياد، ثمَّ كتب إلى العامل بالبصرة بإخراجِ آلِ زياد من ديوانِ قُرَيشٍ والعرب، ورَدَّهم إلى ثقيف، وكتَبَ في ذلك كتابًا بالغًا، يذكُرُ فيه استلحاقَ زياد، ومخالفةَ حُكمِ رسول الله صلَّى الله عليه وسلم فيه، فأُسقِطوا من ديوانِ قُريشٍ."},{"id":538,"title":"قيام الدولة الإباضية الرستمية في الجزائر .","date":["العام الهجري :160","العام الميلادي :776"],"text":"قام جماعةٌ مِن الخوارج الإباضيَّة بقيادة عبد الرحمن بن رستم، ببناء مدينة تاهرت، وكانت مقرَّهم، وهادنَ إمامُهم عبد الرحمن ولاةَ القيروانِ مثل حكَّام الدولة الصفرية في سجلماسة."},{"id":539,"title":"الخليفة العباسي المهدي يوسع لمسجد الحرام .","date":["العام الهجري :160","الشهر القمري : ذي الحجة","العام الميلادي :777"],"text":"حجَّ المهديُّ بعد توليه الخلافةَ بعامٍ, ولَمَّا رأى ضِيقَ مساحة مسجدِ الحرم, ومعاناة الحُجَّاج من الزِّحام؛ أمَرَ بتوسعته، فاشترى الأراضيَ والدُّورَ المحيطة بالمسجد وأزالها، وقد شَمِلَت التوسعة الجهتين الشماليَّة والجنوبية, وأمر بنقل أساطينِ الرُّخامِ من الشام ومصر إلى ميناء جُدَّة، ثم نُقِلَت على عربات إلى مكَّة, أما الأروقة فقد عَمِلَها على أساطينِ الرُّخام، وسُقِفَت بخشب الساج, وقد انتهت أعمال التوسعةِ الأولى سنة 164 وبلغت حوالي:7950م2، فصارت مساحة المسجد: 23390م2."},{"id":540,"title":"الخليفة العباسي المهدي يوسع المسجد النبوي .","date":["العام الهجري :160","الشهر القمري : ذي الحجة","العام الميلادي :777"],"text":"أمر أبو عبد الله محمد المهدي، أثناء زيارتِه للمدينة المنورة، بالزيادةِ فيه، فزاد فيه 30 مترًا من الناحية الشماليَّة فقط, واستمَرَّ العمل في البناء 4 سنوات من سنة 161 وانتهى منه سنة 165."},{"id":541,"title":"الخليفة العباسي المهدي يأمر ببناء المصانع والقصور في طريق مكة .","date":["العام الهجري :161","العام الميلادي :777"],"text":"أمر المهديُّ ببناء القصورِ في طريق مكَّة، وأمر بتوسيعِ القُصور التي كان بناها السفَّاح، كما قام بتجديد الأميال والبِرَك ومصانع المياه، وحفر الرَّكايا؛ كلُّ ذلك تسهيلًا للمسافرينَ في طُرُقِهم، كما أمرَ أن تُقصَّرَ كُلُّ المنابرِ إلى قَدْرِ ارتفاعِ مِنبرِ الرَّسولِ صلَّى الله عليه وسلَّم، ولا يُزادَ على ذلك."},{"id":542,"title":"بناء مدينة تيهرت (تاهرت) كعاصمة لدولة الرستميين .","date":["العام الهجري :161","العام الميلادي :777"],"text":"مدينة تيهرت، أسسَّها عبد الرحمن بن رستم بن بهرام، وكان مولًى لعثمانَ بن عفان، وكان خليفةً لأبي الخطاب أيامَ تغلُّبِه على إفريقية، ولما دخل ابن الأشعث القيروان فرَّ عبد الرحمن إلى الغرب بما خلفَ مِن أهله وماله، فاجتمعت إليه الإباضية، وعزموا على بنيان مدينةٍ تجمَعُهم، فنزلوا بموضعِ تيهرت، وهي غَيضة يكثر فيها الشجر بين ثلاثة أنهارٍ، فبنوا مسجدًا من أربع بلاطات، واختَطَّ الناسُ مساكِنَهم، وكانت في الزمان الخالي مدينةً قديمة، فأحدثها عبد الرحمن بن رستم وبقي بها إلى أن مات في سنة 168"},{"id":543,"title":"عبد الرحمن الفهري يقاتل أهل الأندلس ليدخُلوا في طاعة العباسيَّين .","date":["العام الهجري :161","العام الميلادي :777"],"text":"عبَرَ عبد الرحمن بن حبيب الفهري، المعروف بالصقلبي- وإنَّما سمي به لطولِه وزُرقتِه وشُقرتِه- من إفريقية إلى الأندلس مُحاربًا لهم، ليدخُلوا في طاعة العباسيَّين، وكان عبورُه في ساحل تدمير، وكاتبَ سليمانَ بن يقظان بالدخول في أمرِه، ومحاربةِ عبد الرحمن الداخل، والدُّعاءِ إلى طاعة المهدي. وكان سليمان ببرشلونة، فلم يجِبْه، فاغتاظَ عليه، وقصَدَ بلدَه فيمن معه من البربرِ، فهزمه سليمان، فعاد الصقلبيُّ إلى تدمير، وسار عبد الرحمن الداخل نحوَه في العدَد والعُدَّة، وأحرق السفُنَ تضييقًا على الصقلبي في الهرب، فقصدَ الصقلبي جبلًا منيعًا بناحية بلنسية، فبذلَ الداخل ألف دينارٍ لِمَن أتاه برأسِه، فاغتاله رجلٌ من البربر، فقتله، وحمل رأسَه إلى عبد الرحمن، فأعطاه ألفَ دينار، وكان قتْلُه سنة اثنتينِ وستين ومائة"},{"id":544,"title":"بدء حملات شارلمان على الأندلس .","date":["العام الهجري :161","العام الميلادي :777"],"text":"قام شارلِمان ملكُ الفرنجة بالإغارةِ على الأندلس شمالًا، وذلك بالاتِّفاق مع حليفِه سليمان بن يقظان ابن الأعرابي أمير سرقسطة، واستولى على بنبلونه، ثمَّ اتَّجه نحو سرقسطة، فخرج سليمان لاستقبالِه وتسليمه المدينةَ، لكنَّ المدينة أُغلِقَت بوجهِ الجيوشِ، وتسلَّمَ السلطة الحسين بن يحيى الأنصاري، وهو الذي أعان سليمان في الخروجِ على عبد الرحمنِ الداخِلِ، لكنه أحَبَّ الانفرادَ بإمارة سرقسطة، فاضطرَّ شارلمان بالانسحاب، وأخذ معه سليمانَ كرهينةٍ؛ لأنَّه ظَنَّ أنَّ هذه خُدعةٌ منه في إفشال حملتِه على الأندلس، فتَبِعَ ولداه الجيشَ واستنقذا والدَهما، وعادا ولكنْ بعد فترة قتله يحيى الأنصاري، وأصبح هو أميرَ سرقسطة."},{"id":545,"title":"وفاة سفيان الثوري .","date":["العام الهجري :161","الشهر القمري : شعبان","العام الميلادي :778"],"text":"هو شيخ الإسلام، إمام الحفاظ، أميرُ المؤمنين في الحديث، أبو عبد الله سفيانُ بنُ سعيد بن مسروق الثوريُّ التميميُّ، وُلِدَ سنة 97 بالكوفة, وهو سيِّدُ أهل زمانه في العِلم والدين، من كبارِ تابعي التابعينَ, وأحدُ الأئمة المجتهدينَ الذين كان لهم أتباعٌ، مصنف كتاب (الجامع) ولد: سنة 98 اتفاقا، وطلب العلم وهو حدث باعتناء والده المحدث الصادق سعيد بن مسروق الثوري، وكان والده من أصحاب الشعبي، وخيثمة بن عبد الرحمن، ومن ثقات الكوفيين، وعداده في صغار التابعين, ولا يُختلف في إمامة سفيان وأمانته وحفظه وعلمه وزهده. قال يونس بن عبيد: \"ما رأيت أفضل من سفيان الثوري، فقيل له: يا أبا عبد الله رأيت سعيد بن جبير، وإبراهيم، وعطاء، ومجاهدا وتقول هذا؟ قال: هو ما أقول، ما رأيت أفضل من سفيان\" قال عبد الرحمن بن مهدي: \"ما رأيت رجلاً أحسن عقلاً من مالك بن أنس، ولا رأيت رجلاً أنصح لأمة محمد صلى الله عليه وسلم من عبد الله بن مبارك، ولا أعلم بالحديث من سفيان، ولا أقشف من شعبة\". وقد ساق الذهبي جملة من اقوال الأئمة والعلماء في الثوري منها: قال ابن المبارك: \"كتبت عن ألف ومائة شيخ، ما كتبت عن أفضل من سفيان, وما نعت لي أحد فرأيته، إلا وجدته دون نعته، إلا سفيان الثوري. قال أبو حنيفة: لو كان سفيان الثوري في التابعين، لكان فيهم له شأن. وقال أيضا: لو حضر علقمة والأسود، لاحتاجا إلى سفيان. وقال المثنى بن الصباح: سفيان عالم الأمة، وعابدها. وقال ابن أبي ذئب،: ما رأيت أشبه بالتابعين من سفيان الثوري. وقال شعبة: ساد سفيان الناس بالورع والعلم, وهو أمير المؤمنين في الحديث. وقال ابن عيينة،: ما رأيت رجلا أعلم بالحلال والحرام من سفيان الثوري. وقال أحمد بن حنبل: قال لي ابن عيينة: لن ترى بعينيك مثل سفيان الثوري حتى تموت. وعن حفص بن غياث، قال: ما أدركنا مثل سفيان، ولا أنفع من مجالسته. وقال أبو معاوية: ما رأيت قط أحفظ لحديث الأعمش من الثوري، كان يأتي، فيذاكرني بحديث الأعمش، فما رأيت أحدا أعلم منه بها. وقال يحيى بن سعيد: سفيان أعلم بحديث الأعمش من الأعمش. وقال ابن عرعرة: سمعت يحيى بن سعيد يقول: سفيان أثبت من شعبة، وأعلم بالرجال. وقال محمد بن زنبور: سمعت الفضيل يقول: كان سفيان والله أعلم من أبي حنيفة. وقال بشر الحافي: سفيان في زمانه، كأبي بكر وعمر في زمانهما.\". يقال: إن عدد شيوخه ستمائة شيخ، وكبارهم الذين حدثوه عن: أبي هريرة، وجرير بن عبد الله، وابن عباس، وأمثالهم. وقد قرأ الختمة عرضا على: حمزة الزيات أربع مرات. وأما الرواة عنه فقد حدث عنه من القدماء من مشيخته وغيرهم خلق، منهم: الأعمش، وأبان بن تغلب، وابن عجلان، وخصيف، وابن جريج، وجعفر الصادق، وجعفر بن برقان، وأبو حنيفة، والأوزاعي، ومعاوية بن صالح، وابن أبي ذئب، ومسعر، وشعبة، ومعمر وكلهم ماتوا قبله, وغيرهم كثير. قال يحيى بن أيوب العابد: حدثنا أبو المثنى، قال: \"سمعتهم بمرو يقولون: قد جاء الثوري، قد جاء الثوري. فخرجت أنظر إليه، فإذا هو غلام قد بقل وجهه - خرج شعر وجهه-. قلت (الذهبي): \"كان ينوه بذكره في صغره، من أجل فرط ذكائه، وحفظه، وحدث وهو شاب قال أبو بكر بن عياش: إني لأرى الرجل يصحب سفيان، فيعظم في عيني. وقال ورقاء، وجماعة: لم ير سفيان الثوري مثل نفسه.\" كان سفيان رأسا في الزهد، والتأله، والخوف، رأسا في الحفظ، رأسا في معرفة الآثار، رأسا في الفقه، لا يخاف في الله لومة لائم, وهو من أئمة الدين، وكان يكثر من ذكر الآخرة, واغتفر له غير مسألة اجتهد فيها، وفيه تشيع يسير، كان يثلث بعلي، وهو على مذهب بلده أيضا في النبيذ. ويقال: رجع عن كل ذلك، وكان ينكر على الملوك، ولا يرى الخروج أصلا ومن أقوله رحمه الله: ما أودعت قلبي شيئا فخانني. قال وكيع، سمعت سفيان يقول: ليس الزهد بأكل الغليظ، ولبس الخشن، ولكنه قصر الأمل، وارتقاب الموت. وقال يحيى بن يمان: سمعت سفيان يقول: المال داء هذه الأمة، والعالم طبيب هذه الأمة، فإذا جر العالم الداء إلى نفسه، فمتى يبرئ الناس وقال عبد الرزاق: دعا الثوري بطعام ولحم، فأكله، ثم دعا بتمر وزبد، فأكله، ثم قام، وقال: أحسن إلى الزنجي، وكده. أبو هشام الرفاعي: سمعت يحيى بن يمان، عن سفيان، قال: إني لأرى الشيء يجب علي أن أتكلم فيه، فلا أفعل، فأبول دما. وقال سفيان: ما وضع رجل يده في قصعة رجل، إلا ذل له. قيل: إن عبد الصمد عم المنصور دخل على سفيان يعوده، فحول وجهه إلى الحائط، ولم يرد السلام. فقال عبد الصمد: يا سيف! أظن أبا عبد الله نائما. قال: أحسب ذاك أصلحك الله. فقال سفيان: لا تكذب، لست بنائم. فقال عبد الصمد: يا أبا عبد الله! لك حاجة؟ قال: نعم، ثلاث حوائج: لا تعود إلي ثانية، ولا تشهد جنازتي، ولا تترحم علي. فخجل عبد الصمد، وقام، فلما خرج، قال: والله لقد هممت أن لا أخرج، إلا ورأسه معي. دعاه المنصور لتولِّي القضاءِ فأبى، ثم طلَبَه المهدي لذلك, فأبى ثم أتي به للمهدي، فلما دخل عليه سلم تسليم العامة ولم يسلم بالخلافة، والربيع قائم على رأس المهدي متكئاً على سيفه يرقب أمر الثوري، فأقبل عليه المهدي بوجه طلق، وقال له: يا سفيان، تفر منا ها هنا وها هنا وتظن أنا لو أردناك بسوء لم نقدر عليك، فقد قدرنا عليك الآن، أفما تخشى أن نحكم فيك بهوانا قال سفيان: إن تحكم فيّ يحكم فيك ملك قادر يفرق بين الحق والباطل، فقال له الربيع: يا أمير المؤمنين، ألهذا الجاهل أن يستقبلك بمثل هذا إيذن لي أن أضرب عنقه، فقال له المهدي: اسكت ويلك، وهل يريد هذا وأمثاله إلا أن نقتلهم فنشقى بسعادتهم اكتبوا عهده على قضاء الكوفة على أن لا يُعترض عليه في حكم، فكتب عهده ودفع إليه، فأخذه وخرج فرمى به في دجلة وهرب، فطلب في كل بلد فلم يوجد. هرب إلى مكَّة أولًا، ثم خرج إلى البصرة وبقي فيها متواريًا حتى مات فيها\", وأُخرِجَت جنازتُه على أهلِ البصرة فجأةً، فشَهِدَه الخلقُ، وصلَّى عليه عبد الرحمن بن عبد الملك بن أبجر، ونزل في حُفرتِه هو وخالد بن الحارث. مات وله ثلاث وستون سنة."},{"id":546,"title":"وفاة إبراهيم بن أدهم .","date":["العام الهجري :162","العام الميلادي :778"],"text":"هو الإمام العارف، سيد الزهاد، أبو إسحاقَ إبراهيمُ بن أدهم بن منصور التميمي البلْخي ويقال له العجلي. أحد مشاهير العباد وأكابر الزهاد. كانت له همة عالية في ذلك. أصله من بلْخ، ولد سنة 99،كان من الأشراف وكان أبوه كثيرَ المال والخَدَم, ثم ترَكَ ابنُ أدهم الدُّنيا وأقبل على آخِرتِه، سكن الشام وروى الحديثَ، قال النسائي: \"إبراهيم بن أدهم ثقة مأمون أحد الزهاد\". اشتهر بالزُّهد والورع، فلا يُذكَرُ الزُّهدُ إلَّا ويُذكَرُ إبراهيمُ، كان لا يأكُلُ إلَّا مِن عمَلِ يديه، وقِصَصُه في الزهدِ مَشهورةٌ جدًّا. عن سفيان الثوري قال: لو كان إبراهيم بن أدهم في الصحابة لكان رجلا فاضلا له سرائر وما رأيته يظهر تسبيحا ولا شيئا ولا أكل مع أحد طعاما إلا كان آخر من يرفع يديه, وقال عبد الله بن المبارك: كان إبراهيم رجلا فاضلا له سرائر ومعاملات بينه وبين الله عز وجل. قال ابن أدهم: الزهد ثلاثة، واجب، ومستحب، وزهد سلامة، فأما الواجب فالزهد في الحرام، والزهد عن الشهوات الحلال مستحب، والزهد عن الشبهات سلامة. وقال: قلة الحرص والطمع تورث الصدق والورع، وكثرة الحرص والطمع تورث الغم والجزع."},{"id":547,"title":"خروج عبد السلام اليشكري في الجزيرة .","date":["العام الهجري :162","العام الميلادي :778"],"text":"خرج عبد السلامِ بن هاشم اليشكري، وهو من الخوارج الصفرية في الجزيرة، وقَوِيَ أمرُه، وأحرز النصرَ على عددٍ مِن قُوَّاد المهدي وجيوشِه، ثم سار إليه شبيب بن واج المروذي، فانهزم أولًا، ثم طلب الدعمَ مِن المهدي فأمَدَّه وأعطى كلَّ جندي ألفَ درهمٍ معونةً له، فنفر إليه وقاتَلَه مرة أخرى، فهزمه وفر عبد السلام إلى قِنَّسرين فتبعه إليها وتمكَّنَ منه وقتلَه."},{"id":548,"title":"القضاء على فتنة المقَنَّع رأس الزنادقة ببلاد فارس .","date":["العام الهجري :162","العام الميلادي :778"],"text":"ظهر المقَنَّع بخراسان سنة 161 وقيل سنة 159 وكان رجلًا أعورَ قصيرًا، من أهل مرو، ويسمَّى حكيمًا، وكان اتخذَ وجهًا من ذهَبٍ فجعله على وجهِه لئلا يُرى، فسُمِّيَ المقَنَّع، وادعَّى الألوهيَّة، ولم يُظهِرْ ذلك إلى جميع أصحابه، وكان يقولُ: إن الله خلق آدم، فتحول في صورته، ثمَّ في صورة نوح، وهكذا هلُمَّ جرًّا إلى أن تحوَّلَ في صورة أبي مسلم الخراساني، ثم تحوَّل إلى هاشم، وهاشم- في دعواه- هو المقَنَّع، ويقول بالتناسخ، وتابعَه خلق من ضُلَّالِ الناسِ، وكانوا يسجدونَ له من أي النواحي كانوا، وكانوا يقولونَ في الحرب: يا هاشم أعنَّا، واجتمع إليه خلقٌ كثير، وتحصَّنوا في قلعة بسنام، وسنجردة، وهي من رساتيق كش، وظهرت المبيضة ببخارى والصغد معاونينَ له، وأعانه كفَّارُ الأتراك، وأغاروا على أموالِ المسلمين. وكان يعتقِدُ أن أبا مسلم أفضلُ من النبي صلَّى الله عليه وسلَّم،  وكان يُنكِرُ قتلَ يحيى بن زيد، وادَّعى أنه يقتُلُ قاتليه. واجتمعوا بكش، وغلَبوا على بعض قصورها، وعلى قلعةِ نواكث، وحاربَهم أبو النعمان، والجنيد، مرةً بعد مرة، وقتلوا حسانَ بن تميم بن نصر بن سيار، ومحمد بن نصر وغيرهما، وأنفذ إليهم جبرائيل بن يحيى وأخاه يزيد، فاشتغلوا بالمبيضة الذين كانوا ببخارى، فقاتلوهم أربعة أشهُر في مدينة بومجكث، ونقَبَها عليهم، فقتل منهم سبعَمائة، ولحق منهزموهم بالمقَنَّع، وتبعهم جبرائيل، وحاربهم؛ ثم سيَّرَ المهدي أبا عون لمحاربةِ المقَنَّع، فلم يبالِغْ في قتاله، واستعمَلَ معاذَ بن مسلم، ثم إنَّ المقَنَّع بعد أن طال حصاره بالقلعة وشعر بالغَلَبة احتسى السُّمَّ وانتحر هو وأهله، وذلك في سنة 163 وكان قد حاصره سعيد الحريثي وبالغ في حصارِه."},{"id":549,"title":"وفاة أبي بكر بن عبد الله بن محمد بن أبي سبرة .","date":["العام الهجري :162","العام الميلادي :778"],"text":"هو الفقيه الكبير، قاضي العراق، أبو بكر بن عبد الله بن محمد بن أبي سبرة بن أبي رهم - وهو بدري من السابقين المهاجرين- بن عبد العزى القرشي، ثم العامري. كان أبو بكر من علماء قريش، ولاه المنصور القضاء، وكان خرج مع محمد بن عبد الله بن حسن صاحب النفس الزكية، وكان على صدقات أسد وطيء، فقدم على محمد بأربعة وعشرين ألف دينار، فلما قتل محمد، أُسر ابن أبي سبرة وسجن، ثم استعمل المنصور جعفر بن سليمان على المدينة، وقال له: إن بيننا وبين ابن أبي سبرة رحما، وقد أساء وأحسن، فأطلقه وأحسن جواره. وكان الإحسان أن عبد الله بن الربيع الحارثي قدم المدينة ومعه العسكر، فعاثوا بالمدينة، وأفسدوا. فوثب على الحارثي سودان المدينة والرعاع، فقتلوا جنده، وطردوهم، ونهبوا متاع الحارثي، ثم كسر السودان السجن، وأخرجوا ابن أبي سبرة حتى أجلسوه على المنبر، وأرادوا كسر قيده، فقال: ليس على هذا فوت، دعوني حتى أتكلم. فتكلم في أسفل المنبر، وحذرهم الفتنة، وذكرهم ما كانوا فيه، ووصف عفو المنصور عنهم، وأمرهم بالطاعة. فأقبل الناس على كلامه، وتجمع القرشيون، فخرجوا إلى عبد الله بن الربيع، فضمنوا له ما ذهب له ولجنده، ثم رجع ابن أبي سبرة إلى الحبس، حتى قدم جعفر بن سليمان، فأطلقه وأكرمه، ثم صار إلى المنصور، فولاه القضاء. قال ابن عدي: عامة ما يرويه أبو بكر غير محفوظ، وهو في جملة من يضع الحديث. قال ابن سعد: ولي القضاء لموسى الهادي، وهو ولي عهد، ثم ولي قضاء مكة لزياد بن عبيد الله. توفي ابن ابي سبرة ببغداد, وقد عاش ستين سنة، فلما مات، استقضي بعده القاضي أبو يوسف."},{"id":550,"title":"المهدي يغزو الروم بقيادة ابنه هارون الرشيد .","date":["العام الهجري :163","الشهر القمري : جمادى الآخرة","العام الميلادي :780"],"text":"تجهَّزَ المهدي لغزو الروم، فخرج وعسكرَ بالبردان، وجمع الأجناد من خراسان وغيرها، وسار عنها، وكان قد توفِّي عيسى بن علي بن عبد الله بن عباس في جمادى الآخرة، وسار المهدي من الغد، واستخلفَ على بغداد ابنَه موسى الهادي، واستصحَبَ معه ابنه هارون الرشيد، وسار على الموصِل والجزيرة، وعزل عنها عبد الصمد بن علي في مسيرِه ذلك، ولما حاذى قصرَ مسلمة بن عبد الملك، قال العباس بن محمد بن علي للمهدي: إنَّ لِمَسلمةَ بن عبد الملك في أعناقنا مِنَّة، كان محمد بن علي مَرَّ به، فأعطاه أربعةَ آلاف دينار، وقال له: إذا نَفِدَت فلا تحتَشِمْنا, فأحضر المهديُّ ولدَ مَسْلمة ومواليَه، وأمرَ لهم بعشرين ألفَ دينار، وأجرى عليهم الأرزاقَ، وعبَرَ الفُرات إلى حلب، وأرسل وهو بحلب فجَمَع مَن بتلك الناحية من الزَّنادقة، فجُمِعوا فقَتَلهم، وقطَّعَ كُتُبَهم بالسَّكاكين، وسار عنها مشيِّعًا لابنه هارون الرشيد، حتى جاز الدربَ وبلغ جيحان، فسار هارون، ومعه عيسى بن موسى، وعبد الملك بن صالح، والربيع، والحسن بن قحطبة، والحسن وسليمان ابنا برمك، ويحيى بن خالد بن برمك، وكان إليه أمرُ العَسكر، والنَّفَقات، والكتابة وغير ذلك، فساروا فنزلوا على حصنِ سمالوا، فحصره هارونُ ثمانية وثلاثين يومًا، ونصَبَ عليه المجانيقَ، ففتحه الله عليهم بالأمانِ، ووفى لهم، وفتحوا فتوحًا كثيرةً."},{"id":551,"title":"قتال المسلمين للأرمن  .","date":["العام الهجري :164","العام الميلادي :780"],"text":"غزا عبدُ الكبيرِ بنُ عبد الحميدِ بنِ عبدِ الرحمنِ بنِ زيدِ بنِ الخطَّابِ الصائفةَ مِن درب الحدث، بلاد الروم، فأتاه ميخائيلُ البِطريق، وطاردا طازاذ الأرمني البطريق في تسعينً ألفًا، فخافه عبد الكبير، ومنع الناسَ من القتال، ورجع بهم، فأراد المهديُّ قتْلَه، فشُفعَ فيه فحبَسَه."},{"id":552,"title":"عبدالرحمن الداخل يستعيد سرقسطة  .","date":["العام الهجري :164","العام الميلادي :780"],"text":"سار عبدُ الرحمن الداخل إلى سرقسطة، بعد أن كان قد سيَّرَ إليها ثعلبةَ بنَ عُبيد في عسكرٍ كثيف، وكان سليمانُ بن يقظان، والحسينُ بن يحيى قد اجتمعا على خلعِ طاعةِ عبد الرحمن، وهما بها، فقاتَلَهما ثعلبةُ قِتالًا شديدًا، وفي بعض الأيامِ عاد إلى مخَيَّمِه، فاغتنم سليمانُ غِرَّتَه، فخرج إليه، وقبَضَ عليه وأخَذَه، وتفَرَّق عسكَرُه، واستدعى سليمان بن يقظان قارله ملك الإفرنج، ووعَدَه بتسليمِ البلد وثعلبةَ إليه، فلما وصل إليه لم يُصبِحْ بيده غيرُ ثعلبة، فأخذه وعاد إلى بلادِه، وهو يظنُّ أنَّه يأخذُ به عظيمَ الفداء، فأهمله عبدُ الرحمن مدَّةً، فلما كان هذه السنة سار عبدُ الرحمن إلى سرقسطة، وفرَّقَ أولادَه في الجهات ليدفَعوا كلَّ مخالفٍ، ثم يجتَمِعوا بسرقسطة، فسبقهم عبدُ الرحمن إليها، وكان الحسينُ بن يحيى قد قتلَ سليمان بن يقظان، وانفرد بسرقسطة، فوافاه عبدُ الرحمن على أثَرِ ذلك، فضَيَّقَ على أهلها تضييقًا شديدًا. وأتاه أولادُه من النواحي، ومعهم كلُّ من كان خالفهم، وأخبَروه عن طاعةِ غَيرِهم، فرَغِبَ الحسين بن يحيى في الصُّلح، وأذعن للطاعةِ، فأجابه عبدُ الرحمن، وصالَحَه، وأخذ ابنَه سعيدًا رهينةً، ورجع عنه"},{"id":553,"title":"غزو عبدالرحمن الداخل الفرنجة في الأندلس .","date":["العام الهجري :164","العام الميلادي :780"],"text":"غزا عبدالرحمن الداخل بلادَ الفرنج، فدَوَّخَها، وبلغ قلهرة، وفتح مدينةَ فكيرة، وهدمَ قلاعَ تلك الناحية، وسار إلى بلاد البشكنس، ونزل على حِصنِ مثمين الأقرع، فافتتحه، ثمَّ تقدم إلى ملدوثون بن أطلال، وحصر قلعتَه، وقصد الناسُ جَبَلَها، وقاتلهم فيها، فمَلَكَها عَنوةً وخرَّبَها ثم رجع إلى قُرطبة."},{"id":554,"title":"فتنة الثورات بين البربر في الأندلس .","date":["العام الهجري :164","العام الميلادي :780"],"text":"ثارت فتنةٌ بين بربر بلنسية وبربر شنت برية من الأندلس، وجرت بينهم حروبٌ كثيرةٌ قُتِلَ فيها خَلقٌ كثيرٌ مِن الطائفتَينِ، وكانت وقائِعُهم مشهورةً."},{"id":555,"title":"ثورة دحية بن مصعب الأموية في مصر ضد العباسيين .","date":["العام الهجري :165","العام الميلادي :781"],"text":"خرج دحيةُ بن المصعب بن الأصبغ بن عبد العزيز بن مروان الأموي بالصعيدِ ودعا لنَفسِه بالخلافة، فتراخى عنه إبراهيمُ بنُ صالح أميرُ مصرَ، ولم يحفِلْ بأمره حتى استفحلَ أمرُ دحية، وملكَ غالِبَ بلاد الصعيد وكاد أمرُه أن يتِمَّ ويُفسِدَ بلادَ مِصرَ وأمرَها؛ فسَخِطَ المهديُّ عليه؛ بسبب ذلك، وعزله عزلًا قبيحًا، ثمَّ عيَّن موسى بن مصعب بن الربيع الذي اشتغلَ بأمر دحية الأموي، وجهَّزَ إليه جيوشًا لقتاله، ثمَّ خرج موسى بنفسِه في جميع جيوشِ مِصرَ لقتالِ قيسٍ واليمانية، فلمَّا التَقَوا انهزم عنه أهلُ مصر بأجمَعِهم وأسلَموه، فقُتِلَ موسى ثمَّ وَلِيَها عسامة بن عمرو، فبعث عسامة إلى دِحية جيشًا مع أخيه بكَّار بن عمرو، فحارب بكارٌ يوسُفَ بن نصير مُقَدَّم جيش دحية المذكور، وتطاعَنَا فوضَعَ يوسُفُ الرمحَ في خاصرةِ بكَّار ووضع بكَّارٌ الرُّمحَ في خاصرةِ يوسُفُ فقُتِلا معًا، ورجع الجيشانِ مُنهَزِمَينِ."},{"id":556,"title":"غدر الحسين بن يحيى بعبدالرحمن الداخل بالأندلس .","date":["العام الهجري :165","العام الميلادي :781"],"text":"غدر الحُسَين بن يحيى بسرقسطة، فنكَثَ مع عبد الرحمن، فسيَّرَ إليه عبد الرحمن غالبَ بنَ ثُمامة بن علقمة في جندٍ كثيف، فاقتتلوا، فأسرَ جماعةً من أصحاب الحسين فيهم ابنُه يحيى، فسيَّرَهم إلى الأمير عبد الرحمن، فقتَلَهم، وأقام غالبُ بن ثمامة على الحسين يحصُرُه، ثمَّ إنَّ الأمير عبد الرحمن سار سنةَ سِتٍّ وستين ومائة إلى سرقسطة بنفسِه، فحاصرها، وضايقَها، ونصب عليها المجانيقَ ستة وثلاثين منجنيقًا، فمَلَكَها عَنوةً، وقتل الحسينَ أقبحَ قِتلةٍ، ونفى أهلَ سرقسطة منها ليمينٍ تقَدَّمَت منه، ثم ردَّهم إليها."},{"id":557,"title":"هارون الرشيد ينتصر على البيزنطيين .","date":["العام الهجري :165","الشهر القمري : جمادى الآخرة","العام الميلادي :782"],"text":"أرسل المهديُّ ابنَه الرشيدَ لغَزوِ الرومِ صائفة، في خمسةٍ وتسعين ألفًا وتسعمائة وثلاثة وتسعين رجلًا، ومعه الربيع، فوغل هارونُ في بلاد الروم، ولقيه عسكرُ لقيظا قومس القوامسة، فبارزه يزيدُ بن مزيد الشيباني فأثخنه يزيدُ وانهزمت الرومُ، وغلب يزيدُ على عسكَرِهم. وساروا إلى الدمستق، وهو صاحِبُ المسالح، فحمل لهم مائة ألفِ دينار وثلاثة وتسعين ألفًا وأربعمائة وخمسين دينارًا، ومن الوَرِق أحدًا وعشرين ألف ألف درهم وأربعة عشر ألفًا وثمانمائة درهم. وسار الرشيدُ حتى بلغ خليجَ القسطنطينية، وصاحبُ الروم يومئذٍ عطسة امرأة أليون، فجرى الصلحُ بينها وبين الرشيد على الفِدية، وأن تُقيمَ له الأدلَّاء والأسواقَ في الطريق، وذلك أنَّه دخل مَدخلًا ضيِّقًا مَخوفًا، فأجابته إلى ذلك، ومقدارُ الفدية سبعون ألف دينار كلَّ سنة، ورجع عنها."},{"id":558,"title":"أخذ المهدي البيعة لولده هارون من بعد موسى الهادي .","date":["العام الهجري :166","العام الميلادي :782"],"text":"في هذه السنة أخذ المهديُّ البيعةَ لابنه هارون ولُقِّبَ بالرشيدِ مِن بعد موسى الهادي"},{"id":559,"title":"تتبعُ المهدي الزنادقة وإنشاء ديوان لمطاردتهم .","date":["العام الهجري :167","العام الميلادي :783"],"text":"جدَّ المهديُّ في تتبُّعِ الزنادقةِ، فأنشأ ديوانًا لمطاردتِهم, وكان المتولي أمرَ هذا الديوانِ عمر الكلواذي الذي صار يتتبَّعُ الزنادقةَ في سائرِ الآفاق فيستحضِرُهم ويقتلُ صبرًا بين يدي المهدي، فقتل عددًا كبيرًا، منهم الشَّاعرُ بشَّار بن بُرد، وأخذ يزيد بن الفيض كاتبَ المنصور، فأقَرَّ ولم يرجِعْ عمَّا يعتَقِدُه فحبسه، ثم هرب من الحَبسِ، فلم يَقدِر عليه."},{"id":560,"title":"نقض الروم الصلح الذي عقده هارون الرشيد عن أمر أبيه  .","date":["العام الهجري :168","العام الميلادي :784"],"text":"نقضَ الرومُ الهُدنةَ التي عقَدَها الرشيدُ سنة 165هـ فوجه إليهم عليُّ بن سليمان أميرُ الجزيرةِ جيشًا بقيادةِ يزيدَ بنِ بدر البطَّال، فظَفِرَ بهم وغَنِم."},{"id":561,"title":"اتخاذ الخليفة المهدي دواوين الأزِمة وتسمى (المالية) .","date":["العام الهجري :168","العام الميلادي :784"],"text":"كان ديوانُ الأزِمَّة- واحِدُها الزِّمام- من أهمِّ دواوينِ الدَّولة- ويُشبِهُ ديوانَ المحاسبةِ اليومَ- وكانت مهمَّةُ صاحب هذا الديوانِ جمعَ ضرائبِ بلاد العراقِ؛ أغنى أقاليمِ الدولة العباسية، وتقديمَ حسابِ الضرائب في الأقاليم الأخرى. ومن اختصاصاتِه أيضًا جمعُ الضرائب النوعيَّة المسمَّاة بالمعادن، وكانت تُجمَعُ لرجُلٍ يَضبِطُها بزمامٍ يكون له على كلِّ ديوانٍ- وقد جمَعَها عمر بن بزيع- فيتَّخِذُ دواوينَ الأزِمَّة ويولِّي على كلٍّ منها رجلًا."},{"id":562,"title":"ثورة أبي الأسود الفهري في الأندلس .","date":["العام الهجري :168","العام الميلادي :784"],"text":"ثار أبو الأسود محمد بن يوسف بن عبد الرحمن الفِهري بالأندلس، وكان من حديثه: أنَّه كان في سِجنِ عبد الرحمن بقُرطبةَ مِن حينِ هرب أبوه، وقُتِل أخوه عبد الرحمن، وحُبِس أبو الأسود، وتعامى في الحبسِ ثمَّ هرب منه واجتمعَ حَولَه خَلقٌ كثيرٌ، فرجع بهم إلى قتال عبد الرحمن الداخل، فالتقيا على الوادي الأحمر بقسطلونة، واشتدَّ القتال، ثم انهزم أبو الأسودِ، وقُتِلَ من أصحابِه أربعةُ آلاف سوى من تردَّى في النهر، واتَّبَعه الداخل يقتُلُ من لحِقَ، حتى جاوز قلعةَ الرباح، ثم جمَعَ وعاد إلى قتالِ الداخل، في سنة تسع وستين، فلما أحسَّ بمَقْدَمةِ الأمويِّ انهزم أصحابُه وهو معهم، فأُخِذَ عيالُه، وقُتِلَ أكثَرُ رجاله، وبَقِيَ إلى سنة سبعين، فهلك بقريةٍ مِن أعمال طليطِلة. وقام بعده أخوه قاسِمٌ وجمع جمعًا، فغزاه الأميرُ، فجاء إليه بغيرِ أمانٍ فقَتَله."},{"id":563,"title":"توالي ثورات الخوارج في الجزيرة والموصل  .","date":["العام الهجري :168","العام الميلادي :784"],"text":"خرج بأرضِ المَوصِل خارجيٌّ اسمُه ياسين من بني تميم، فخرج إليه عسكرُ الموصِل، فهزمهم، وغلَب على أكثَرِ ديار ربيعةَ والجزيرة، وكان يميلُ إلى مقالةِ صالحِ بن مسرح الخارجيِّ، فوجَّه إليه المهديُّ أبا هريرة محمد بن فرُّوخ القائد، وهرثمة بن أعيَن مولى بني ضبة، فحارباه فصَبَرَ لهما، حتى قُتِلَ وعِدَّةٌ من أصحابِه، وانهزم الباقون."},{"id":564,"title":"وفاة نافع بن عبدالرحمن أحدُ القُرَّاء السبعة .","date":["العام الهجري :169","العام الميلادي :785"],"text":"هو الإمامُ حَبرُ القرآنِ: نافع بن عبدالرحمن بن أبي نعيم، أحدُ القُرَّاء السبعة، أصلُه من أصبهان، ولد بالمدينة سنة 70 وقيل 71هـ في خلافة عبدالملك بن مروان, وكان أسودَ اللونِ حالكًا صبيحَ الوجهِ حسَنَ الخُلُق، فيه دُعابة، أخذ القراءةَ عَرضًا عن جماعةٍ مِن تابعي أهلِ المدينة، أقرأَ النَّاسَ دهرًا طويلًا؛ نيفًا عن سبعين سنة، وانتهت إليه رياسةُ القراءة بالمدينة، قيل: إنه كان يُشَمُّ منه رائحةُ المِسكِ حين يقرأُ القرآن، وكان زاهدًا جوادًا، صلى في مسجد النبيِّ صلَّى الله عليه وسلم ستينَ سنةً، وكان الإمامُ أحمَدُ يُقَدِّمُ قراءتَه على قراءةِ عاصم، توفِّيَ في المدينةِ."},{"id":565,"title":"وفاة الخليفة العباسي المهدي .","date":["العام الهجري :169","الشهر القمري : محرم","العام الميلادي :785"],"text":"هو محمَّدُ بن عبد الله بن محمد بن علي بن عبد الله بن عباس، أبو عبدِ الله المهدي، أميرُ المؤمنين، لُقِّبَ بالمهدي رجاءَ أن يكون الموعودَ به في الأحاديثِ، فلم يكُنْ به. وُلِدَ بالحميمة من أرض البلقاء سنة 126هـ، وقيل 127هـ، ووليَ الخلافةَ بعد أبيه سنة 158هـ في ذي الحجة سنة ثمان وخمسين ومائة، وعمُره إذ ذاك 33 سنة، وكان أسمرَ طويلًا جَعْدَ الشَّعرِ. وكان من مآثِره تتبُّعُه للزنادقة في عهدِه، حتى قُتِلَ عددٌ منهم صبرًا بين يديه, وقيل: إنَّ سبب وفاته أنَّه خرج إلى ماسبذان، بعد أن عزم على خلعِ ابنِه موسى الهادي والبيعة للرَّشيد بولايةِ العهد وتقديمه على الهادي، فبعث إليه فلم يأتِ فخرج المهديُّ إليه فمات في الطريق, بسبب إصابةٍ في ظَهرِه وهو يَلحَقُ الصيدَ، وقيل: بل مات مسمومًا، وكانت خلافتُه عشر سنين وشهرًا؛ ودُفِنَ تحت جوزة كان يجلِسُ تحتها، وصلى عليه ابنُه الرشيد."},{"id":566,"title":"موسى الهادي يتولى الخلافة العباسية .","date":["العام الهجري :169","الشهر القمري : محرم","العام الميلادي :785"],"text":"وبويِعَ لموسى الهادي في اليومِ الذي مات فيه المهديُّ، وهو مقيمٌ بجرجان، يحارِبُ أهل طبرستان."},{"id":567,"title":"ثورة الحسين بن علي بن الحسن في المدينة ومكة .","date":["العام الهجري :169","الشهر القمري : شوال","العام الميلادي :786"],"text":"ظهر الحُسَين بن عليِّ بن الحسن بن الحسن بن علي بن أبي طالب بالمدينةِ، وذلك أنَّه أصبح يومًا وقد لَبِسَ البياضَ وجلس في المسجدِ النبويِّ، وجاء الناسُ إلى الصلاةِ، فلما رأوه ولَّوا راجعين، والتفَّ عليه جماعةٌ فبايعوه على الكتابِ والسنَّة والرضا من أهل البيت, وكان سببُ خروجِه أنَّ متولي المدينة خرج منها إلى بغداد ليهنِّئ الخليفةَ الهادي بالولايةِ ويعَزِّيه في أبيه. ثم جرت أمورٌ اقتَضَت خروجَه، والتفَّ عليه جماعةٌ وجعلوا مأواهم المسجِد النبوي، ومنعوا النَّاسَ من الصلاة فيه، ولم يُجِبْه أهلُ المدينة إلى ما أراده، بل جعلوا يدعونَ عليه لانتهاكِه المسجِدَ، حتى ذُكِرَ أنَّهم كانوا يَقذرونَ في جَنَبات المسجد، وقد اقتتلوا مع المسودةِ مَرَّات، فقتل من هؤلاء وهؤلاء. ثم ارتحل إلى مكَّةَ فأقام بها إلى زمنِ الحَجِّ، فبعث إليه الهادي جيشًا فقاتلوه بعد فراغِ النَّاسِ مِن الموسِم، فقتلوه وقتلوا طائفةً من أصحابه، وهرب بقيَّتُهم وتفَرَّقوا شَذَر مَذَر, منهم إدريس بن عبدالله الذي أسَّس دولة الأدارسة العلوية بالمغرب, وكان موقِع المعركة يسمَّى فخ بمكَّة عبارة عن فجٍّ من فجاجِها."},{"id":568,"title":"وفاة الخليل بن أحمد الفراهيدي .","date":["العام الهجري :170","العام الميلادي :786"],"text":"هو الخليلُ بن أحمد بن عمرو بن تميم الفراهيديُّ الأزدي اليحمدي، أبو عبد الرحمن: من أئمَّة اللغة والأدب، وواضِعُ علم العروضِ، إمامُ اللغة المعروف، ولد سنة 100هـ ونشأ بالبصرة، وأخذ النحوَ والقراءةَ والحديث عن أئمَّة العربية وكِبار الرواة، رحل إلى الباديةِ فسَمِعَ الفصيحَ وجمَع الغريبَ، حتى نبغَ في اللغة فأصبح عَلَمَها المشهورَ، وعنه أخذ سيبويهِ، انكَبَّ على العلم يستنبِطُ ويُعَلِّم ويؤلِّف، مع تقشُّفٍ في المعيشة وزُهدٍ، قيل: كان أوَّلًا على مذهب الخوارج الإباضيَّة، ثم رجع إلى مذهب أهل السنَّة، وهو أوَّل من ابتكر عِلمَ العَروضِ، وابتكر المُعجَمات ووضَعَ الخَطَّ على الشَّكلِ المُستعمَل، ألَّفَ في العَروض والخَطِّ والشَّكل والنَّقط والإيقاع، وأما أهمُّ مؤلَّفاته فهو كتاب \"العَين\" وهو معجَمٌ مُرَتَّبٌ على حسَبِ مخارجِ الحروفِ، مُبتدئا بحرفِ العين، فسُمِّي بذلك، لكنه لم يُتِمَّه، وكان سببُ موتِه أنَّه اصطدم رأسُه بساريةٍ في المسجدِ ارتَجَّ منها دماغُه، فكانت سببَ موته."},{"id":569,"title":"ثورة الإباضية في أفريقية .","date":["العام الهجري :170","العام الميلادي :786"],"text":"لَمَّا توفِّيَ يزيد بن حاتم المهلبي، والي إفريقيَّة، وكان قد استخلفَ عليها ابنَه داود، فانتقَضَت جبال باجة، وخرج فيها الإباضيَّة، فسيَّرَ إليهم داود جيشًا فظَفِرَ بهم الإباضيَّة، وهزموهم، فجهز إليهم جيشًا آخرَ، فهُزِمت الإباضيَّة، فتَبِعَهم الجيش، فقَتلوا منهم فأكثروا، وبَقيَ داود أميرًا إلى أن استعمل الرَّشيدُ عمَّه روح بن حاتم المهلبي أميرًا على إفريقيَّة."},{"id":570,"title":"بدء بناء جامع قرطبة .","date":["العام الهجري :170","العام الميلادي :786"],"text":"كان أوَّل الأمرِ في قرطبة عندما فتَحَها المسلمونَ أن بنَوَا المسجِدَ فيها بجانب الكنيسةِ العظيمة فيها، ثمَّ لَمَّا ازداد عددُ المسلمين وضاق عليهم المسجدُ، نظر عبدالرحمن الداخل في أن يوسِّعَه فاشترى من النصارى كنيسَتَهم بعد أن دفَعَ لهم ما أرادوه من المالِ، وأوسع في ذلك، فأمر بتحويلِه إلى مسجدٍ وضَمَّه للقديم، وكان ذلك في عامٍ كاملٍ."},{"id":571,"title":"وفاة الخليفة العباسي الهادي  .","date":["العام الهجري :170","الشهر القمري : ربيع الأول","العام الميلادي :786"],"text":"هو موسى الهادي بن محمد المهدي بن عبد الله المنصور بن محمد بن علي بن عبد الله بن عباس أبو محمد وَلِيَ الخلافةَ في محرم سنة تسع وستين ومائة. مات وله من العمُرِ ثلاث وعشرون سنة، ويقال: إنَّه لم يلِ الخلافةَ أحدٌ قبلَه في سِنِّه، وكان حسنًا جميلًا طويلًا، أبيض، وكان قويًّا شَهمًا خبيرًا بالمُلك كريمًا، ومن كلامه: \"ما أُصلِحَ الملكُ بمثل تعجيلِ العقوبةِ للجاني، والعفوِ عن الزلَّات، ليقِلَّ الطَّمعُ عن الملك\". سار على طريقةِ أبيه المهدي في تتبُّعِ الزنادقة واستئصالهم. واختُلِفَ في سبب وفاته، فقيل: كان سببها قرحةً كانت في جوفه، وقيل: مَرِضَ وهو بحديثة الموصل، وعاد منها مريضًا فتوفِّيَ، وقيل: إنَّ وفاته كانت من قبَل جَوارٍ لأمِّه الخيزُران كانت أمَرَتهنَّ بقتله، وكان سببُ أمرِها بذلك أنَّه لَمَّا وَلِيَ الخلافةَ منعها من أن تتصَرَّف بأي شيءٍ في أمور الخلافةِ أو الشَّفاعات وغيرها, وصلَّى عليه الرشيدُ، ودُفِنَ بعيساباذ الكبرى في بستانِه، فكانت خلافتُه سنة وثلاثة أشهر."},{"id":572,"title":"تولي هارون الرشيد الخلافة .","date":["العام الهجري :170","الشهر القمري : ربيع الأول","العام الميلادي :786"],"text":"أراد الهادي أن يعهَدَ لابنه جعفرٍ بدلًا من أخيه هارون الرشيد الذي عيَّنه والده المهديُّ واليًا ثانيًا للعهد. وألحَّ الهادي على ذلك وشجَّعَه جماعةٌ من ولاته, لكِنَّ خالد بن يحيى البرمكي نبَّهَه أنَّ جعفر ما زال صغيرًا لم يبلُغ الحنثَ، ثمَّ إنَّ هذا سيجعل الناسَ تستخِفُّ بأيمانِها، فرجع الهادي عن رأيه في عَزْلِ الرشيد, والعجيبُ أنَّ الرشيدَ كان مُسالِمًا لأخيه الهادي في هذا الأمرِ دون أن يبديَ أيَّ اعتراضٍ, حتى جاءه الرشيدُ يومًا فجلس عن يمينه بعيدًا عنه، فجعل الهادي ينظُرُ إليه مليًّا، ثم قال: يا هارونُ، تطمَعُ أن تكونَ وليًّا للعهدِ حَقًّا؟ فقال: إي والله، ولئنْ كان ذلك لأصِلَنَّ مَن قطعتُ، ولأُنصِفَنَّ من ظَلَمتُ، ولأزوِّجَنَّ بنيك من بناتي. فقال: ذاك الظَّنُّ بك. فقام إليه هارونُ ليقَبِّلَ يدَه، فحلف الهادي ليجلس معه على السرير فجلس معه، ثم أمرَ له بألف ألف دينار، وأن يدخُلَ الخزائنَ فيأخُذَ منها ما أراد، وإذا جاء الخَراجُ دفع إليه نِصفَه. ففعل ذلك كلَّه ورَضِيَ الهادي عن الرشيد, فاستلم هارونُ الرشيد زمامَ الخلافة في اليوم التالي لوفاة أخيه الهادي."},{"id":573,"title":"الأدارسة يقيمون دولتهم ويبنون فاس عاصمة لها بالمغرب الأقصى .","date":["العام الهجري :172","العام الميلادي :788"],"text":"هرب إدريسُ بن عبدالله بن حسن بن الحسن بن علي بن أبي طالب- أخو محمد النَّفس الزكيَّة- من الحجاز بعد أن نجا من معركةِ فخ بمكَّة عام 169هـ فاتَّجه لمصرَ ثمَّ للمغرب، واستطاع أن يؤسِّسَ بمساعدة السكَّان البربر دولةَ الأدارسة العلويَّة المنفصلة عن المشرقِ في خلافة هارون الرشيد, وبنى مدينة فاس في مكانٍ يسمَّى جراوة، وصارت عاصمةً له وبَقِيَ حاكمًا عليهم إلى أن توفِّيَ عام 175هـ وقيل في 177هـ"},{"id":574,"title":"وفاة عبدالرحمن الداخل صاحب الأندلس .","date":["العام الهجري :172","الشهر القمري : جمادى الأولى","العام الميلادي :788"],"text":"هو عبد الرحمن بن معاوية بن هشام بن عبد الملك بن مروان، صاحِبُ الأندلس، سمِّيَ بالداخل؛ لأنَّه استطاع أن يهربَ مِن العباسيين رغمَ كُلِّ المحاولاتِ للإمساك به، واستطاع أن يدخُلَ الأندلسَ، وأن يكَوِّنَ فيها دولةً قَوِيَت يومًا بعد يوم، وقيل: كان عمره حينئذ عشرين سَنةً، وأما موتُه فكان بقرطبة، وصلَّى عليه ابنُه عبد الله، وكان عَهِدَ إلى ابنه هشام، وكان هشامٌ بمدينة ماردة واليًا عليها، وكان ابنُه سليمان بن عبد الرحمن، وهو الأكبَرُ، بطليطِلة واليًا عليها، فلم يحضُرا موت أبيهم، وحضَره عبد الله المعروفُ بالبلنسي، وأخذ البيعةَ لأخيه هشام، وكتب إليه بنعي أبيه ويهَنِّئُه بالإمارة، فسار هشامٌ إلى قرطبة. وكانت دولة عبد الرحمن ثلاثًا وثلاثين سنةً وأشهُر."},{"id":575,"title":"هارون الرشيد يكتب كتابا يوصي فيه لابنه الأمين بالبيعة .","date":["العام الهجري :175","العام الميلادي :791"],"text":"أخذ الرَّشيدُ بولاية العهدِ مِن بعده لولَدِه محمَّد بن زبيدة وسمَّاه الأمين، وعمُرُه إذ ذاك خمسُ سنين، وقد كان الرشيد يتوسَّمُ النجابةَ والرَّجاحة في عبد الله المأمون، ويقول: والله، إنَّ فيه حزمَ المنصور، ونُسُك المهديِّ، وعِزَّة نفسِ الهادي، ولو شئتُ أن أقولَ الرابعةَ مني لقُلتُ، وإني لأقَدِّمُ محمَّد بن زبيدة، وإنِّي لأعلَمُ أنَّه مُتَّبِعٌ هواه، ولكن لا أستطيعُ غيرَ ذلك، ثمَّ لَمَّا حج علَّقَ هذا الكتاب في جوفِ الكعبة، كنوعٍ مِن التثبيتِ لهذا العهدِ، فلا يستجرئُ أحدٌ على نقضِه."},{"id":576,"title":"تغلب هشام بن عبدالرحمن على أخويه .","date":["العام الهجري :175","العام الميلادي :791"],"text":"لَمَّا استلم هشامٌ الخلافةَ بعَهدِ أبيه إليه، طَمِعَ أخواه فيها بعد مدَّةٍ، فحاول سليمانُ-وهو الأخ الأكبَرُ لهشام- ذلك، ودعا لنفسِه وبويع في بعضِ المناطق، ثم فعل أخوه الآخَرُ عبدالله كذلك، فانتدب لهما هشامٌ وغَلَبَهما وأجْلاهما عن الأندلُس."},{"id":577,"title":"القضاء على تمرد مطروح بن سليمان في سرقسطة .","date":["العام الهجري :175","العام الميلادي :791"],"text":"لَمَّا فرغ هشامُ بن عبدالرحمن من أخوَيه سليمانَ وعبد الله, انتدب لمطروحِ بن سليمان بن يقظان، فسيَّرَ إليه جيشًا كثيفًا، وجعل عليه أبا عثمان عبيد الله بن عثمان، فسار إلى مطروح، وهو بسرقسطة، فحصَرَه بها فلم يظفَرْ به، فرجع أبو عثمانَ عنه، ونزل بحِصنِ طرسونة، بالقربِ من سرقسطة، وبثَّ سراياه على أهل سرقسطة يُغِيرونَ ويَمنَعون عنهم المِيرةَ، ثمَّ غدر بمطروحٍ بعضُ أصحابِه وقَتَلوه ودانُوا لهِشامٍ، فقَبِلَ منهم."},{"id":578,"title":"غزو عبيد الله بن مطروحِ بلاد الفرنجة .","date":["العام الهجري :175","العام الميلادي :791"],"text":"لَمَّا فرغ أبو عثمان عبيد الله بن عثمان من مطروحِ بنِ سليمان، سار إلى بلاد الفرنج، فلَقِيَه العدوُّ، فظَفِرَ بهم، وقتلَ منهم خلقًا كثيرًا، وفتح الله عليه."},{"id":579,"title":"غزو هشام بن عبدالرحمن مدينة جليقية (غرب إسبانيا) .","date":["العام الهجري :175","العام الميلادي :791"],"text":"سيَّرَ هشام بن عبدالرحمن يوسُفَ بن بخت في جيشٍ إلى جليقية، فلقِيَ مَلِكَهم وهو برمند الكبير، فاقتتلوا قتالًا شديدًا وانهزمت الجلالِقةُ، وقُتِل منهم عالَمٌ كثير."},{"id":580,"title":"وفاة الليث بن سعد .","date":["العام الهجري :175","الشهر القمري : شعبان","العام الميلادي :791"],"text":"هو الإمامُ الحافِظُ شيخ الإسلامِ، وعالمُ الدِّيار المصرية، أبو الحارثِ الليثُ بنُ سعدِ بن عبد الرحمن الفهمي، ولِدَ سنة أربع وتسعين بقرقشندة- قرية من أسفل أعمال مصر- إمامُ أهل مصر في عصرِه؛ حديثًا وفِقهًا ولغةً، حتى قال الشافعي: الليث أفقَهُ من مالك، أصلُه من أصبهان، ولد في مصر ونشأ فيها، أراده المنصورُ على القضاء فأبى، كان متولِّي مصرَ وقاضيها وناظِرُها من تحتِ أوامِره، ويَرجِعونَ إلى رأيِه ومَشُورتِه، ووَلِيَ بعضَ الولاياتِ، توفِّي في القاهرة."},{"id":581,"title":"ثورة يحيى بن عبدالله في بلاد الديلم (من ذرية الحسن بن علي) .","date":["العام الهجري :176","العام الميلادي :792"],"text":"هو يحيى بن عبدالله بن الحسن بن الحسن بن علي بن أبي طالب، وكان يحيى ممَّن نجا يوم فخٍّ بمكَّة عام 169هـ فهرب إلى اليمن، ثم لمصر، ثم بغداد، ثم نزل ببلاد الديلم، واتَّبَعه خلقٌ كثيرٌ وجَمٌّ غفير، وقَوِيَت شوكتُه، وارتحل إليه الناسُ من الكور والأمصار، فانزعج لذلك الرشيدُ وقَلِقَ من أمره، فنَدَب إليه الفضلَ بن يحيى بن خالد بن برمك، فسار الفضلُ إليه وكاتَبَه بأنَّه سيسعى له بالأمانِ إن هو خرجَ مُطيعًا وأغرى صاحِبَ الديلم أن يعطيَه ألف ألف درهم إن هو سعى إلى إخراجِ يحيى للصُّلحِ، فطلب يحيى أن يكتُبَ له الرشيدُ بخَطِّ يده الأمانَ، فلما وصل الخبَرُ للرشيد سُرَّ بذلك وكتب له الأمانَ، وأشهد عليه القُضاةَ والفقهاءَ ومَشيخةَ بني هاشم، وبعثه ومعه الهدايا والأموال، ثم جاء يحيى ودخل بغدادَ بهذا الأمانِ، وأكرَمَه الرشيدُ، ثم لم يلبث الرشيدُ فتنكَّرَ ليحيى مرَّةً أخرى فحَبَسَه في سرداب حتى مات عام 180هـ، وقد كَثُرت الروايات في سبَبِ مَوتِه؛ قيل: جَوَّعَه حتى مات، وقيل: عُذِّبَ، وقيل: بل مات دون دافِعٍ، وقيل غيرُ ذلك."},{"id":582,"title":"فتنة عظيمة بالشام بين النزارية (القيسية) واليمانية .","date":["العام الهجري :176","العام الميلادي :792"],"text":"هاجت الفتنةُ بدِمشقَ بين المُضَريَّة واليمانية، وكان رأس المضرِيَّة أبو الهيذام، واسمُه عامر بن عمارة بن خريم أحَد الفُرسان المشهورين، وكان سببُ الفتنة أنَّ عامِلًا للرشيد بسجستان قَتَل أخًا لأبي الهيذام، فخرج أبو الهيذامِ بالشام، وجمعَ جمعًا عظيمًا فرثى أخاه بأبياتٍ، ثمَّ إنَّ الرشيد احتال عليه بأخٍ له كتَبَ إليه فأرغَبَه، ثم شَدَّ عليه فكَتَّفه، وأتى به الرشيدَ، فمَنَّ عليه وأطلقه. وقيل: كان أوَّل ما هاجت الفتنةُ في الشام أنَّ رجُلًا من بني القين اقتتل مع رجلٍ مِن لخم أو جذام، فقُتِلَ رجلٌ من اليمانية، وطلبوا بدَمِه، فاجتمعوا لذلك، وكان على دمشق حينئذ عبدُ الصمد بن علي، فلمَّا خاف الناسُ أن يتفاقمَ ذلك اجتمع أهلُ الفَضلِ والرؤساءُ ليُصلِحوا بينهم، فأتوا بني القين فكَلَّموهم، فأجابوهم إلى ما طلَبوا فأتوا اليمانية فكلَّموهم، فقالوا: انصَرِفوا عنا حتى ننظُرَ، ثم ساروا فبيَّتوا بني القين، فقَتَلوا منهم ستَّمائة، وقيل ثلاثمائة، فاستنجَدَت القين قضاعة وسليحا فلم ينجدوهم، فاستنجدت قيسًا فأجابوهم، وساروا معهم إلى الصواليك من أرض البلقاء، فقتلوا من اليمانية ثمانمائة، وكثُرَ القتال بينهم فالتَقَوا مرَّات. وعُزِل عبد الصمد عن دمشق، واستُعمِلَ عليها إبراهيم بن صالح بن علي، فدام ذلك الشَّرُّ بينهم نحو سنتين، والتقَوا بالبثنية، فقُتِلَ من اليمانية نحوُ ثمانمائة، فأعادوا أيامَ الجاهلية، وقد هُدِّمَ سور دمشق حين ثارت الفتنةُ؛ خوفًا من أن يتغلب عليها أبو الهيذام المزِّي رأسُ القيسية، فلمَّا تفاقم الأمرُ بعث الرشيدُ مِن جهته موسى بن يحيى بن خالد ومعه جماعةٌ مِن القُوَّاد ورؤوس الكُتَّاب، فأصلحوا بين الناسِ، وهدأت الفتنةُ واستقام أمرُ الرعيَّة، وحملوا جماعاتٍ من رؤوس الفتنة إلى الرشيد، فرَدَّ أمرَهم إلى يحيى بن خالد، فعفا عنهم وأطلَقَهم."},{"id":583,"title":"ظهور الإباضية في عُمان .","date":["العام الهجري :176","العام الميلادي :792"],"text":"استطاع أحدُ زُعَماء الإباضية وهو عبد الله بن يحيى، المشهورُ بطالب الحقِّ، الاستيلاءَ على حضرموت سنة 129هـ، في السنواتِ الأخيرة لحُكم بني أمية، بمساعدة الإباضيَّة في البصرة، ثم استولى على صَنعاء، وامتَدَّ نُفوذُهم إلى بعضِ مَناطِقِ الحجاز بعد انتصاراتٍ على الجيوش الأمويَّة، تَبِعَها هزائم وانكسارات. وقد ظَلَّ للإباضيَّة نفوذ وانتشار في حضرموت حتى استيلاء الصليحي عليها سنة 455هـ. وأدَّت بعضُ العوامل إلى أن يؤسِّسَ الإباضيُّونَ إمارةً لهم في عُمان؛ منها: انتماءُ عدَدٍ من أبناء قبيلة الأزد- أكبر قبائل عُمان- إلى الإباضيَّة، ورغبةُ العُمانيِّين المستَمِرَّة في الاستقلال عن السُّلطة المركزية المتمَثِّلة بالدولة الأموية ثمَّ العباسيَّة، إضافةً إلى طبيعة عُمان الجغرافية وموقعِها الاستراتيجيِّ؛ ممَّا ساعدها على تنميةِ مَوارِدها الاقتصاديَّة، وبالتالي الوقوف ضِدَّ أي خطرٍ دونَ خَوفٍ من حصار اقتصاديٍّ مُحتَمَل، كما كان يحدثُ في الحجاز مثلًا. ومنذ سنة 177هـ استطاع الإباضيُّون تأسيسَ الإمامة في عُمان، وما زال مذهبُهم سائدًا فيها إلى اليوم."},{"id":584,"title":"غزو هشام بن عبدالرحمن الداخل جنوب فرنسا .","date":["العام الهجري :177","العام الميلادي :793"],"text":"أرسل هشامُ بن عبدالرحمن الداخل بالصائفة جيشًا كثيفًا واستعمَلَ عليهم وزيرَه عبدالملك بن عبدالواحد بن مُغيث، فبلغ ألبةَ والقلاعَ، وأثخن في نواحيها، ثم بعَثَه في العساكِرِ، فوصلوا إلى أربونة وجرندة، وكان البدءُ بجرندة، وكان بها حامية الفرنج، فقَتَل رجالَها وهَدَّم أسوارَها بالمجانيقِ، وأبراجَها، وأشرَفَ على فَتحِها، فرحل عنها إلى أربونة، ففعل بها مثلَ ذلك، وأوغلَ في بلادهم ووطئَ أرض برطانية فاستباح حريمَها وقتل مُقاتِلَتَها، وجاس البلادَ شهرًا يحرِقُ الحُصون ويَسبي ويَغنَم، وقد أجفل العدُوُّ من بين يديه هاربًا، وأوغلَ في بلادهم ورجع سالِمًا ومعه من الغنائمِ ما لا يعلَمُه إلا الله تعالى. وهي من أشهَرِ مغازي المسلمين بالأندلس. حيث بلغ فيه خُمسُ السبيِ إلى خمسةٍ وأربعين ألفًا من الذَّهَب العين، وكان قد استمَدَّ الطاغية بالبشكنس وجيرانه من الملوك، فهزمهم عبدالملك ثم بعث بالعساكرِ مع عبد الكريم بن عبد الواحد إلى بلاد جليقة، فأثخنوا في بلاد العدوِّ وغَنِموا ورجَعوا."},{"id":585,"title":"فتنة العطاف في الموصل .","date":["العام الهجري :177","العام الميلادي :793"],"text":"خالف العطافُ بنُ سفيانَ الأزديُّ الرشيدَ وتغلَّب على الموصِل، وكان من فرسانِ أهلِ الموصل، واجتمع عليه أربعةُ آلافِ رَجُلٍ، وجبى الخراجَ، وكان عامِلُ الرشيدِ على الموصل محمَّدَ بن العباس الهاشمي، وقيل: عبد الملك بن صالح، والعطاف غالِبٌ على الأمر كلِّه، وهو يَجبي الخراج، وأقام على هذا سنتين، حتى خرجَ الرشيدُ إلى الموصل فهدَمَ سُورَها بسَبَبِه, فأقسَمَ ليقتُلَنَّ من لَقِيَ مِن أهلِها، وكان العطاف قد سار عنها نحوَ أرمينيَّة، فلم يظفَرْ به الرشيدُ."},{"id":586,"title":"اغتيال إدريس بن عبدالله مؤسس دولة الأدارسة بالمغرب .","date":["العام الهجري :177","الشهر القمري : ربيع الآخر","العام الميلادي :793"],"text":"لَمَّا قَدِمَ إدريسُ بن عبدالله المغربَ سنة 172هـ نزل على إسحاقَ بن عبد الحميد، فقَدَّمه قبائلُ البربر وأطاعوه، وبلغ خبرُه هارونَ الرشيد، فدَسَّ إليه مَن سَمَّه. وكان المدسوسُ إليه رجلًا يقالُ له الشماخ، فسَمَّه وهرب إلى المشرق، فقام بأمرِ البربرِ مولاه راشِد. وترك إدريسُ جاريةً بربريَّةً اسمها كنزة؛ فوَلَدت له غلامًا سُمِّيَ باسم أبيه، فوَلِيَ إدريسُ بنُ إدريس سنة 187هـ وهو ابنُ أحد عشرة سنة، وقيل: أكثر من ذلك."},{"id":587,"title":"ثورة أهل تونس ونهاية دولة المهالبة .","date":["العام الهجري :178","العام الميلادي :794"],"text":"استعمل الرشيدُ على إفريقيَّة الفضلَ بنَ روح بن حاتم المهلبي بعد موت والِدِه, فاستعمل الفضلُ على مدينة تونس ابنَ أخيه المغيرةَ بن بشر بن روح، فاستخَفَّ بالجُندِ. وكان الفضلُ أيضًا قد أوحَشَهم، وأساء السيرةَ معهم؛ بسبَبِ ميلهم إلى نصرِ بن حبيب الوالي قبلَه، فاجتمع مَن بتُونس، وكتبوا إلى الفضلِ يَستعفُونه من ابن أخيه، فلم يُجِبْهم عن كتابِهم، فاجتمعوا على تَركِ طاعتِه، فبايعوا عبدالله بن الجارود، وأخرجوا المغيرةَ، ثم استشرى الأمرُ في أفريقيا ففسَدَ الجُندُ على الفضلِ، فسَيَّرَ إليهم الفضل عسكرًا كثيرًا فخَرجوا إليه فقاتلوه، فانهزم عسكرُه وعاد إلى القيروان منهزِمًا وتبعهم أصحابُ ابن الجارود، فحاصروا القيروانَ ودخل ابن الجارود وعسكَرُه في جمادي الآخرة، وأخرج الفضل من القيروان، ووكلَ به وبمن معه من أهلِه أن يوصِلَهم إلى قابس، ثم ردَّهم ابن الجارود، وقُتِلَ الفضل بن روح بن حاتم، ثمَّ إنَّ الرشيدَ بلَغَه ما صنع ابنُ الجارود، وإفسادُه إفريقية، فوجَّه هرثمة بن أعين ومعه يحيى بن موسى، فكاتب يحيى عبدالله بن الجارود، ثم دخل في الطاعةِ بعد أن طلَبَ الأمانَ فأمَّنَه."},{"id":588,"title":"فتنة تاكرنا بالأندلس .","date":["العام الهجري :178","العام الميلادي :794"],"text":"هاجت فتنةُ تاكرنا بالأندلس، وخلع بربَرُها الطاعة، وأظهروا الفسادَ، وأغاروا على البلادِ، وقطعوا الطريقَ، فسَيَّرَ هشام بن عبدالرحمن إليهم جُندًا كثيفًا عليهم عبدُ القادر بن أبان بن عبد الله، مولى معاويةَ بن أبي سفيان، فقَصَدوها وتابَعوا قتالَ من فيها إلى أن أبادوهم قتلًا وسَبيًا، وفَرَّ من بقِيَ منهم، فدخل في سائرِ القبائل، وبَقِيَت كورة تاكرنا وجبالُها خاليةً مِن الناس سبعَ سنين."},{"id":589,"title":"ثورة مسلمي مصر على الضرائب العباسية .","date":["العام الهجري :178","الشهر القمري : رجب","العام الميلادي :794"],"text":"لَمَّا وَلِيَ إسحاق بن سليمان بن علي بن عبد الله بن العباس إمارةَ مِصرَ لم يرضَ بما كان يأخُذُه قبله الأمراءُ، وزاد على المُزارعين زيادةً أفحَشَت بهم فسَئِمَته الناسُ وكَرِهَته وخرج عليه جماعةٌ مِن أهل الحوفِ مِن قيس وقضاعة، فحاربَهم إسحاقُ، وقُتل من حواشيه وأصحابِه جماعةٌ كبيرة، فكتب إسحاقُ يُعلِمُ الرَّشيدَ بذلك، فعَظُمَ على الرشيدِ ما ناله من أمرِ مِصرَ، وصَرَفه عن إمرَتِها وعقَدَ الرَّشيدُ لهرثمة بن أعيَن على إمرة مصرَ، وأرسله في جيشٍ كبير إلى مصرَ، فتلقَّاه أهلُ مِصرَ بالطاعةِ وأذعنوا له، فقَبِلَ هرثمة منهم ذلك، وأمَّنَهم وأقَرَّ كُلَّ واحدٍ على حاله."},{"id":590,"title":"القضاء على ثورة الوليد بن طريف الخارجي في الجزيرة .","date":["العام الهجري :178","الشهر القمري : رمضان","العام الميلادي :794"],"text":"خرج الوليدُ بن طريف التغلبي بالجزيرة، ففَتَك بإبراهيم بن خازم بن خزيمة بنصيبين، ثم قَوِيَت شوكةُ الوليد، فدخل إلى أرمينيَّة، وحصر خلاط عشرينَ يومًا، فافتدوا منه أنفُسَهم بثلاثين ألفًا. ثم سار إلى أذربيجان، ثمَّ إلى حلوان وأرض السواد، ثم عبَرَ إلى غرب دجلة، وقصد مدينة بلد، فافتدوا منه بمائةِ ألف، وعاث في أرضِ الجزيرة، فسَيَّرَ إليه الرشيد يزيدَ بن مزيد بن زائدة الشيباني, فجعل يزيدُ يختالُه ويُماكِرُه، وكانت البرامِكةُ مُنحَرِفةً عن يزيد، فقالوا للرشيد: إنَّما يتجافى يزيدُ عن الوليد للرَّحِم؛ لأنَّهما كلاهما من وائل، فكتب إليه الرشيدُ كتابَ مُغضَب، وقال له: لو وَجَّهتُ أحدَ الخدم لقام بأكثَرَ ممَّا تقوم به، ولكِنَّك مُداهِنٌ متعَصِّبٌ، وأُقسِمُ بالله إن أخَّرْتَ مناجَزتَه لأُوجِّهنَّ إليك من يحمِلُ رأسَك. فقال يزيدُ لأصحابه: فِداكم أبي وأمِّي، إنَّما هي الخوارِجُ ولهم حَملةٌ، فاثبُتوا، فإذا انقضت حملتُهم فاحملوا عليهم؛ فإنهم إذا انهزموا لم يرجِعوا، فكان كما قال، حَمَلوا عليهم حَملةً، فثَبَت يزيدُ ومن معه مِن عشيرته، ثم حَمَل عليهم فانكشفوا واتَّبَع يزيدُ الوليدَ بن طريف، فلَحِقَه واحتَزَّ رأسَه."},{"id":591,"title":"غزو هشام بن عبدالرحمن الفرنج بالأندلس .","date":["العام الهجري :179","العام الميلادي :795"],"text":"سيَّرَ هشام بن عبدالرحمن صاحِبُ الأندلس جيشًا كثيفًا عليهم عبدُ الملك بن عبد الواحد بن مغيث، إلى جليقية، فساروا حتى انتهوا إلى استرقة، وكان أذفونش، ملك الجلالقة قد جمع وحشَد، وأمَدَّه ملك البشكنس، وهم جيرانُه، ومن يليهم من المجوس، وأهل تلك النواحي، فصار في جمعٍ عظيم، فأقدمَ عليه عبدُ الملك، فرجع أذفونش هيبةً له، وتَبِعَهم عبد الملك يقفو أثَرَهم، ويُهلِكُ كلَّ من تخلَّفَ منهم، فدَوَّخ بلادَهم، وأوغل فيها وأقام فيها يَغنَمُ، ورجع سالِمًا. وكان قد سيَّرَ هشام جيشًا آخرَ من ناحية أخرى، فدخلوا أيضًا على ميعادٍ من عبد الملك، فلما أرادوا الخروجَ مِن بلاد العدوِّ اعترضهم عسكرٌ للفرنجِ، فنال منهم، وقتل نفرًا من المسلمينَ، ثم تخلَّصوا وسَلِموا وعادوا سالِمينَ سِوى من قُتِلَ منهم."},{"id":592,"title":"وفاة الإمام مالك بن أنس .","date":["العام الهجري :179","الشهر القمري : صفر","العام الميلادي :795"],"text":"هو إمامُ دار الهجرة، أبو عبدِ الله مالكُ بنُ أنس بن مالك بن أبي عامر بن عمرو بن الحارث بن غيمان بن خثيل بن عمرو بن الحارث الأصبحي، ثم المدني، جَدُّه الصحابيُّ أبو عامرٍ الأصبحيُّ، كان طويلًا عظيمَ الهامةِ أصلعَ أبيضَ الرأسِ واللِّحية. أبيضَ شديدَ البياضِ إلى الشُّقرة. وُلِدَ بالمدينة سنة ثلاث وتسعين، عام موتِ أنسِ بنِ مالكٍ خادمِ رَسولِ الله صلى الله عليه وسلم، ونشأ في أسرةٍ ذاتِ صَونٍ ورفاهيةٍ وتجَمُّل. أحدُ الأئمَّة الأربعة المشهورين، إليه تُنسَبُ المالكيَّة، كان إمامًا في الحديثِ بلا منازعٍ، له كتابُ الموطأ المشهور. تعرَّضَ للفتنة أيَّامَ المنصورِ؛ بسبب فتوى له في قتالِ البُغاة، أقام في المدينةِ، وكان يُعظِّمُ ما جرى عليه عمَلُ أهلِ المدينةِ في الفِقهِ، وروى عن نافعٍ مولى ابنِ عُمَرَ، وأكثَرُ مَن رحل إليه للعلمِ المصريُّونَ والمغربيونَ، فكان هذا سببَ انتشارِ مَذهَبِه في تلك البقاعِ، توفي في المدينة ودُفِنَ في البقيعِ- رَحِمَه اللهُ تعالى وجزاه عن الإسلامِ والمُسلمِينَ خَيرًا."},{"id":593,"title":"خروج حمزة بن أترك في خراسان .","date":["العام الهجري :180","العام الميلادي :796"],"text":"خرج حمزةُ بن أترك السجستاني الخارجيُّ في خراسان، فجاء إلى بوشنج، فخرج إليه عَمرَوَيه بن يزيد الأزدي، وكان على هراة، في ستةِ آلاف، فقاتَلَه فهزمه حمزة، وقتَلَ مِن أصحابه جماعةً، ومات عَمرَويه في الزحام، فوجَّه عليُّ بن عيسى- وهو أميرُ خراسان- ابنَه الحُسَينَ في عشرة آلاف، فلم يحارِبْ حمزة، فعَزَله وسَيَّرَ عِوَضَه ابنَه عيسى بن علي، فقاتل حمزة، فهَزَمه حمزةُ، فرَدَّه أبوه إليه أيضًا فقاتله بباخرز، وكان حمزةُ بنيسابور، فانهزم حمزةُ، وبَقِيَ أصحابه، وبقي في أربعينَ رَجُلًا فقَصَد قهستان. وأرسل عيسى أصحابَه إلى أوق وجوين، فقَتَلوا مَن بها من الخوارج، وقصَدَ القرى التي كان أهلُها يُعِينون حمزة، فأحرَقَها وقتَلَ مَن فيها حتى وصل إلى زرنج، فقتَلَ ثلاثين ألفًا ورجَعَ عيسى بن علي، وخلف بزرنج عبد الله بن العباس النسفي، فجبى الأموالَ وسار بها، فلَقِيَه حمزةُ بنُ أترك بأسفزار، فقاتله، فصبَرَ له عبد الله ومن معه من الصغد، فانهزم حمزةُ، وقُتِل كثيرٌ من أصحابه، وجُرِحَ في وجهه، واختفى هو ومن سَلِمَ من أصحابه في الكروم، ثم خرج وسار في القُرى يَقتُل ولا يُبقي على أحدٍ. وكان علي بن عيسى قد استعمَلَ طاهر بن الحسين على بوشنج، فسار إليه حمزةُ، وانتهى إلى مكتبٍ فيه ثلاثون غلامًا فقَتَلهم وقتَلَ مُعَلِّمَهم، وبلغ طاهرًا الخبَرُ، فأتى قريةً فيها قُعَّدُ الخوارجِ- وهم الذين لا يُقاتِلونَ، ولا ديوانَ لهم- فقَتَلهم طاهِرٌ وأخذ أموالَهم، وكان يشُدُّ الرجُلَ منهم في شجرتين، ثم يجمَعُهما ثمَّ يرسِلُهما، فتأخذ كلُّ شَجرةٍ نِصفَه، فكتب القُعَّدُ إلى حمزةَ بالكَفِّ، فكَفَّ وواعَدَهم، وأمِنَ النَّاسُ مدَّةً، وكانت بينه وبين أصحابِ عليِّ بنِ عيسى حروبٌ كثيرةٌ، حتى غُلِبَ وفَرَّ إلى كابل."},{"id":594,"title":"نزول هارون الرشيد الرقة .","date":["العام الهجري :180","العام الميلادي :796"],"text":"بعد أن هدمَ الرَّشيدُ سُورَ الموصِل بسبَبِ العطاف بن سفيان الأزدي، مضى إلى الرقَّةِ فاتَّخَذها وَطنًا، واستنابَ على بغدادَ ابنَه الأمينَ محمَّدًا، وولاه العِراقَينِ."},{"id":595,"title":"وفاة سيبويه أستاذ النحاة .","date":["العام الهجري :180","العام الميلادي :796"],"text":"هو أبو بِشرٍ عَمرُو بنُ عُثمانَ بنِ قُنَبْرَ مَولى بني الحارثِ بنِ كعبٍ، قيل: مولى الرَّبيع بن زياد الحارثي البصري، ولُقِّبَ سيبويهِ لجَمالِه وحُمرةِ وَجنَتَيه، حتى كانتا كالتفَّاحتَين، وسيبويهِ في لغة فارس (رائحةُ التفاحِ)، وهو الإمامُ العلَّامة العَلَم، شيخُ النُّحاة من لدنْ زمانِه إلى زمانِنا هذا، والناسُ عِيالٌ على كتابِه المشهورِ في هذا الفنِّ المعروفِ باسمِ \"كتابُ سِيبَويه\"، وقد شُرِحَ شروحًا كثيرةً، وقلَّ من يحيطُ عِلمًا به، أخذ سيبويهِ العلمَ عن الخليلِ بنِ أحمدَ الفراهيديِّ ولازَمَه، و كان الخليلُ إذا جاءه سيبويهِ يقول: مرحبًا بزائرٍ لا يُمَلُّ\"، وأخذ أيضًا عن عيسى بنِ عُمَر، ويونُسَ بنِ حَبيب، وأبي زيدٍ الأنصاريِّ، وأبي الخطَّابِ الأخفشِ الكبيرِ، وغيرهم، قَدِمَ مِن البصرةِ إلى بغدادَ أيَّامَ كان الكسائيُّ يؤدِّبُ الأمينَ بنَ الرَّشيدِ، وحصلت بينهم وَحشةٌ، فانصرف وعاد إلى بلادِ شيراز."},{"id":596,"title":"غزو الحكم بن هشام بلاد الفرنج (صاحِب الأندلس) .","date":["العام الهجري :180","العام الميلادي :796"],"text":"سيَّرَ الحكم بن هشام صاحِبُ الأندلس جيشًا مع عبد الكريم بنِ مغيث إلى بلاد الفرنج، فدخل البلادَ، وبثَّ السَّرايا فجازوا خليجًا من البحر كان الماءُ قد جَزَر عنه، وكان الفرنجُ قد جعلوا أموالَهم وأهليهم وراء الخليجِ؛ ظنًّا منهم أنَّ أحدًا لا يقدِرُ أن يعبُرَ إليهم، فجاءهم ما لم يكُنْ في حِسابهم، فغَنِمَ المسلمون جميعَ مالهم، وأسَروا الرجالَ وقَتَلوا منهم فأكثروا، وسَبَوا الحريمَ، وعادوا سالِمينَ إلى عبدِ الكريم. وسَيَّرَ طائفةً أخرى، فخَرَّبوا كثيرًا من بلاد فرنسيَّة، وغَنِمَ أموال أهلها، وأسَروا الرجال، فأخبَرَه بعض الأسرى أنَّ جماعةً مِن ملوك الفرنج قد سبقوا المُسلِمينَ إلى وادٍ وعْرِ المسلَكِ على طريقِهم، فجمع عبد الكريم عساكِرَه، وسار على تعبئةٍ، وجَدَّ السَّيرَ، فلم يشعُرِ الكُفَّارُ إلَّا وقد خالَطَهم المسلمون، فوَضَعوا السيفَ فيهم فانهزموا، وغَنِمَ ما معهم وعاد سالِمًا هو ومَن معه."},{"id":597,"title":"وفاة هشام بن عبدالرحمن حاكم الأندلس .","date":["العام الهجري :180","الشهر القمري : صفر","العام الميلادي :796"],"text":"هو هِشامُ بنُ عبد الرحمن بن معاوية بن هشامِ بن عبد الملك بن مروان، صاحِبُ الأندلس، توفي في صفر، وكانت إمارتُه سبع سنين وسبعة أشهر وثمانية أيام، وقيل: تسعة أشهر، وقيل: سبعة أشهر، وكان عمرُه تسعًا وثلاثين سنة وأربعة أشهر، كان ذا رأيٍ وشجاعةٍ وعدلٍ، محبًّا لأهل الخير والصَّلاح، شديدًا على الأعداءِ، راغبًا في الجهادِ، وهو الذي تمَّمَ بناء جامِعِ قرطبة، وكان أبوه قد مات قبل فراغِه منه، وبنى عدَّة مساجد معه، وبلغ مِن عِزِّ الإسلامِ في أيَّامِه وذُلِّ الكُفرِ أنَّ رجلًا مات في أيَّامِه، فأوصى أن يُفَكَّ أسيرٌ مِن المسلمينَ مِن تَرِكتِه، فطُلِب ذلك، فلم يُوجَدْ في دار الكُفَّارِ أسيرٌ يُشترى ويُفَكُّ؛ لضَعفِ العَدُوِّ وقُوَّةِ المُسلِمينَ!"},{"id":598,"title":"القضاء على طائفة المحمرة الزنادقة في جرجان ببلاد فارس .","date":["العام الهجري :181","العام الميلادي :797"],"text":"ظهرت طائفةٌ بجرجان، يقال لها المحَمِّرة، لَبِسُوا الحُمرةَ واتَّبَعوا رجلًا يقال له عمرُو بن محمد العمركي، وكان يُنسَبُ إلى الزندقة، فبعث الرشيدُ يأمُرُ بقَتلِه، فقُتِلَ، وأطفأ اللهُ نارَهم في ذلك الوقتِ."},{"id":599,"title":"وفاة عبدالله بن المبارك .","date":["العام الهجري :181","الشهر القمري : رمضان","العام الميلادي :797"],"text":"هو عبدالله بن المبارك بن واضح، أبو عبد الرحمن الحنظليُّ، مولاهم التركيُّ، ثمَّ المروزي، الحافِظُ الغازي، أحدُ الأعلامِ، كان أبوه تركيًّا وأمُّه تركيَّةً، مِن خوارزمَ، وُلِدَ سنة ثماني عشرة ومائة. وطلبَ العِلمَ وهو ابنُ عشرين سنة، أفنى عمُرَه بالأسفارِ، صَنَّفَ الكتُبَ، وجاهَدَ في سبيلِ اللهِ، وجمَعَ الحديثَ والفقهَ والعربيَّةَ وأيَّامَ النَّاسِ، أوَّلُ مَن صنَّفَ في الجهادِ، اشتهَرَ بالزُّهدِ والورعِ، مع تجارتِه، وكان يُنفِقُ على أهلِ العبادةِ والزُّهدِ مِن مالِه، توفِّيَ في مدينة هيت- بين الرحبة وبغداد- مُنصَرِفًا من غزو الرومِ، وعمره 63 سنة، قال أبو عمر بن عبد البَرِّ: \"أجمع العُلَماءُ على قَبولِه وجَلالتِه، وإمامتِه وعَدْلِه\"، فرَحِمه الله تعالى، وجزاه عن الإسلامِ والمسلمينَ خَيرًا."},{"id":600,"title":"هارون الرشيد يجعل البيعة لولاية العهد لابنه المأمون بعد أخيه الأمين .","date":["العام الهجري :182","العام الميلادي :798"],"text":"أخذ الرَّشيدُ لوَلَدِه عبدِ الله المأمونِ وِلايةَ العَهدِ، من بعد أخيه محمَّد الأمين بن زُبيدة، وذلك بالرقَّةِ بعد مَرجِعِه من الحَجِّ- للمَرَّة الثانية؛ حيث كانت الأولى عام 175هـ-  وضَمَّ ابنَه المأمونَ إلى جعفر بن يحيى البرمكي، وبعثه إلى بغدادَ ومعه جماعةٌ من أهل الرشيدِ خِدمةً له، وولَّاه خراسان وما يتَّصِلُ بها، وسمَّاه المأمون."},{"id":601,"title":"قتال سليمان بن عبدالرحمن لابن أخيه صاحب الأندلس .","date":["العام الهجري :182","العام الميلادي :798"],"text":"جاز سُليمان بن عبد الرحمن بن معاوية إلى بلاد الأندلُسِ من الشرق، وتعَرَّض لحرب ابنِ أخيه الحَكَمِ بن هشام بن عبد الرحمن، صاحِبِ الأندلُس، فسار إليه الحكَمُ في جيوشٍ كثيرة، وقد اجتمع إلى سليمانَ كثيرٌ من أهل الشِّقاقِ ومن يريد الفتنةَ، فالتقيا واقتَتلا واشتدَّت الحربُ، فانهزم سليمانُ واتبَعَه عسكَرُ الحَكَم، وعادت الحربُ بينهما ثانيةً في ذي الحجة، فانهزم فيها سُلَيمان، واعتصَمَ بالوَعْرِ والجبال، فعاد الحَكَمُ. ثم عاد سليمانُ فجمع برابِرَ، وأقبل إلى جانبِ إستجة، فسار إليهم الحَكَمُ، فالتَقَوا واقتتلوا سنة ثلاث وثمانين ومائة، واشتَدَّ القتال، فانهزم سليمانُ، واحتمى بقريةٍ، فحَصَره الحَكَمُ، وعاد سُلَيمانُ مُنهَزِمًا إلى ناحية فريش."},{"id":602,"title":"وفاة القاضي أبي يوسف صاحب أبي حنيفة .","date":["العام الهجري :182","الشهر القمري : ربيع الأول","العام الميلادي :798"],"text":"هو أبو يوسُفَ يعقوبُ بن إبراهيم بن حبيب بن حبيش بن سعد بن بجير بن معاوية الأنصاري، الكوفيُّ، وُلِدَ سنة ثلاث عشرة ومائة، لَزِمَ أبا حنيفةَ سبع عشرة سنةً وتتلمَذَ عليه، وكان يعَدُّ من أنبَلِ تلامذتِه وأنجَبِهم، وكان أبو حنيفةَ يتعاهَدُه ويُنفِقُ عليه، كان أميَلَ للمُحَدِّثينَ مِن أبي حنيفة ومِن مُحمَّد بن الحسَن، كان قاضيَ الآفاقِ، ووزيرَ الرَّشيدِ، وزميلَه في حَجِّه، وكان الرشيدُ يُجِلُّه كثيرًا، وقيل: إنَّه كان يحفَظُ التفسيرَ، ويحفَظُ المغازيَ، وأيَّامَ العربِ، واشتهر بالفِقهِ."},{"id":603,"title":"الخوارج في بلاد الخزر وقتالهم المسلمين .","date":["العام الهجري :183","العام الميلادي :799"],"text":"خرج الخزر بسبب ابنة خاقان من بابِ الأبواب، وقيل: إنَّ سببَ خُروجِهم أنَّ سعيد بن سلم قتَلَ المنجم السلميَّ فدخل ابنُه بلاد الخزر، واستجاشهم على سعيد، فخرجوا ودخَلوا أرمينيَّة من الثُّلمة، فانهزم سعيدٌ، وأقاموا نحو سبعينَ يومًا، وسَبَوا أكثَرَ من مائة ألف رأس، وأوقعوا بالمسلمينَ وأهل الذمَّة أمرًا عظيمًا لم يُسمَعْ بمِثلِه في الأرضِ، فولَّى الرشيدُ أرمينيَّةَ يزيدَ بن مزيد مضافًا إلى أذربيجان، ووجَّهَه إليهم، وأنزل خزيمةَ بن خازم نصيبين ردءًا لأهل أرمينيَّة، فأصلحا ما أفسد سعيدٌ، وأخرجا الخزر وسَدَّا الثُّلْمة."},{"id":604,"title":"وفاة موسى الكاظم بن جعفر الصادق .","date":["العام الهجري :183","الشهر القمري : رجب","العام الميلادي :799"],"text":"هو السَّيِّدُ أبو الحسن العلوي موسى الكاظم بن جعفر الصادق بن محمد الباقر بن علي زين العابدين بن الحسين بن علي بن أبي طالب، والِدُ الإمام علي بن موسى الرضا, المدنِيُّ، ولد سنة ثمان وعشرين ومائة بالمدينةِ ثم نزلَ بغداد,َ لقب بالكاظِمِ لكَظمِه عمَّن أساء إليه، كان مجتهدًا في العبادةِ كريمًا، قيل: إنَّ سبَبَ سَخَطِ الرشيدِ عليه هو أنَّ الرشيدَ لَمَّا زار قبرَ النبيِّ صلَّى اللهُ عليه وسلَّم، قال: السَّلامُ عليك يا عمَّاه يفتَخِرُ بذلك، فقال موسى: السَّلامُ عليك يا أبتِ. فقال الرشيدُ: هذا هو الفَخرُ يا أبا الحسَنِ, ثم لم يزَلْ ذلك في نفسِه، فحَنقَ عليه حتى استدعاه في سنة تسعٍ وسبعين وسجَنَه فأطال سَجنَه، وقيل: بل لأنَّه سَمِعَ أنَّ النَّاسَ يبايعونَ له فحَمَله معه إلى البصرةِ وحَبَسَه عند واليها عيسى بن جعفرٍ، ثمَّ نقَلَه إلى الفضلِ البرمكي، ثمَّ حَوَّله إلى السندي بن شاهك، إلى أن مات عنده ودُفِنَ في بغداد."},{"id":605,"title":"هارون الرشيد يعقد لابنه القاسم بولاية العهد بعد أخيه المأمون .","date":["العام الهجري :183","الشهر القمري : ذي الحجة","العام الميلادي :800"],"text":"حجَّ الرَّشيدُ ومعه ابناه: الأمينُ محمَّد، والمأمونُ عبد الله، وفَرَّقَ بالحرمينِ الأموالَ، وفيها بايعَ الرَّشيدُ بولايةِ العَهدِ لولده قاسِمٍ بعد الأخوينِ: الأمين والمأمون، ولقَّبَه المُؤتَمَن، وولَّاه الجزيرةَ والثُّغورَ، وهو صبيٌّ."},{"id":606,"title":"هارون الرشيد يولي  إبراهيم بن الأغلب على أفريقية .","date":["العام الهجري :184","العام الميلادي :800"],"text":"تمرَّدَ متولي المغربِ محمَّد بن مقاتل العكي، وظلَم وعسَفَ واقتطَعَ مِن أرزاق الأجنادِ وآذى العامَّةَ، فخرج عليه تمامُ بنُ تميم التميمي نائبُه على تونس، فزحَفَ إليه فبَرَز لملاقاته العكي، فهَزَمه ابنُ تميمٌ، فتحَصَّنَ العكيُّ بالقيروان في القصرِ، وغلَبَ تمَّام على البلد، ثم نزل العكيُّ بأمانٍ وانسحب إلى طرابلس، فنهض لنُصرتِه إبراهيمُ بنُ الأغلب، فتقهقر تمَّام إلى تونُسَ ودخل ابنُ الأغلب القيروانَ، فصلى بالنَّاسِ وخطب وحَضَّ على الطاعةِ، ثم التقى ابنُ الأغلب وتمَّام فانهزم تمَّام، واشتَدَّ بغضُ الناسِ للعكيِّ، وكاتبوا الرشيدَ فيه، فعَزَله وأقَرَّ عليهم إبراهيمَ بن الأغلبِ."},{"id":607,"title":"مؤسس دولة الأغالبة في أفريقيا يبني مدينة ويسميها (العباسية) .","date":["العام الهجري :184","الشهر القمري : محرم","العام الميلادي :800"],"text":"بعد أن قام إبراهيمُ بنُ الأغلب بقَمعِ تمَرُّدِ تمَّام بن تميم في أفريقيا، ولَّاه الرشيد، فانقمع الشَّرُّ، وضُبطَ الأمر، وسَيَّرَ تمامًا وكُلَّ مَن يتوثَّبُ الوُلاة إلى الرَّشيد، فسَكَنت البلاد، وابتنى مدينةً سمَّاها العباسيَّة بقُرب القيروان، وانتقَلَ إليها بأهلِه وعَبيدِه."},{"id":608,"title":"سقوط مدينة برشلونة الإسلامية في يد الأسبان .","date":["العام الهجري :185","العام الميلادي :801"],"text":"سقَطَت مدينةُ برشلونة بالأندلُسِ بِيَدِ ملك الفرنج بقيادةِ أذفونش بعد تحالُفِه مع البشكنس- لعَنَهم الله- وأخَذُوها من المسلمينَ، ونقلوا حُماةَ ثغورِهم إليها، وتأخَّرَ المسلمونَ إلى ورائهم. وكان سبَبُ مُلكِهم إيَّاها اشتغال الحَكَم بن هِشامٍ صاحِبِ الأندلس بمحاربةِ عَمَّيه عبد الله وسُليمان."},{"id":609,"title":"هارون الرشيد يجدد وثيقة ولاية العهد لأولاده في جوف الكعبة .","date":["العام الهجري :186","العام الميلادي :802"],"text":"لَمَّا وصل الرشيدُ إلى مكَّة، ومعه أولادُه والفُقَهاء والقُضاة والقُوَّاد، فكتب كتابًا أشهَدَ فيه على محمَّد الأمين، وأشهدَ فيه من حضرَ بالوفاء للمأمونِ، وكتَبَ كتابًا للمأمونِ أشهَدَهم عليه فيه بالوفاءِ للأمين، وعلَّقَ الكتابينِ في الكعبةِ، وجَدَّد العهودَ عليهما في الكعبة. ولَمَّا فعل الرشيد ذلك قال الناس: قد ألقى بينهم شَرًّا وحَربًا. وخافوا عاقبةَ ذلك، فكان ما خافوه."},{"id":610,"title":"هارون الرشيد يجبر إمبراطور البيزنطيين على دفع الجزية .","date":["العام الهجري :186","العام الميلادي :802"],"text":"اضطُرَّت دولةُ الرُّومِ أمام ضَرَباتِ الرشيدِ المتلاحقةِ إلى طلبِ الهُدنة والمصالحة، فعقدت \"إيريني\" مَلِكةُ الرُّومِ صلحًا مع الرشيد، مقابِلَ دفعِ الجزية السَّنوية له في سنة 181هـ، وظلَّت المعاهدة ساريةً حتى نقَضَها إمبراطورُ الروم، الذي خلَفَ إيريني، وكتب إلى هارون: \"مِن نقفور ملكِ الرُّومِ إلى ملِك العَرَب، أمَّا بعدُ؛ فإنَّ المَلِكة إيريني التي كانت قبلي أقامَتْك مقامَ الرُّخِّ، فحَمَلَت إليك مِن أموالها، لكِنَّ ذاك ضَعفُ النِّساءِ وحُمقُهنَّ، فإذا قرأتَ كتابي فاردُدْ ما حصَلَ قِبَلَك من أموالِها، وافتَدِ نَفسَك، وإلَّا فالحربُ بيننا وبينك\". فلمَّا قرأ الرشيدُ الرسالةَ ثارت ثائِرتُه، وغضِبَ غضَبًا شديدًا، وكتبَ على ظهرِ رسالة الامبراطور: \"مِن هارونَ أميرِ المؤمنينَ إلى نقفور كَلبِ الرُّومِ، قد قرأتُ كتابَك يا ابنَ الكافرةِ، والجوابُ ما تراه دونَ أن تسمَعَه، والسَّلامُ\". فشَخَص مِن يَومِه، وسار حتى أناخ ببابِ هرقلة، ففتح وغَنِمَ، واصطفى وأفاد، وخَرَّب وحَرَّق واصطَلَم، فطلبَ نقفورُ الموادعةَ على خراجٍ يؤدِّيه في كلِّ سَنةٍ، فأجابه إلى ذلك."},{"id":611,"title":"استيلاء الفرنجة على تطيلة في الأندلس واسترجاع المسلمين لها .","date":["العام الهجري :187","العام الميلادي :802"],"text":"استولى الفِرنجُ على مدينة تطيلة بالأندلس، وسبب ذلك أنَّ الحَكَمَ بن هِشامٍ صاحِبَ الأندلُسِ استعمَلَ على ثغورِ الأندلُسِ قائدًا كبيرًا من أجنادِه، اسمُه عمروس بن يوسف، فاستعمل ابنَه يوسُفَ على تطيلة. وكان قد انقلب على الحَكَم بنِ هشام بيتٌ من بيوت الأندلُسِ أولُو قوَّةٍ وبأس؛ لأنَّهم خرجوا عن طاعته، فالتحَقوا بالمُشرِكين، فقَوِيَ أمرُهم، واشتَدَّت شوكتُهم، وتقَدَّموا إلى مدينة تطيلة فحَصَروها ومَلَكوها من المسلمين، فأسَروا أميرَها يوسُفَ بن عمروس، وسجَنوه بصخرة قيس. واستقَرَّ عمروس بن يوسف بمدينةِ سرقسطة ليحفَظَها من الكُفَّار، وجمَعَ العساكِرَ، وسيَّرَها مع ابنِ عَمٍّ له، فلَقِيَ المشركين، وقاتَلَهم، ففَضَّ جَمعَهم، وهزَمَهم، وقتل أكثَرَهم، ونجا الباقون منكوبين، وسار الجيشُ إلى صخرة قيس، فحصروها وافتتحوها ولم يقدِر المشركون على مَنعِها منهم؛ لِما نالهم من الوَهَنِ بالهزيمة، ولَمَّا فَتَحَها المسلمون خلَّصوا يوسُفَ بن عمروس أميرَ الثغر، وسيَّروه إلى أبيه، وعظم أمر عمروس عند المشركين، وبَعُد صوتُه فيهم."},{"id":612,"title":"وفاة الفضيل بن عياض .","date":["العام الهجري :187","الشهر القمري : محرم","العام الميلادي :803"],"text":"هو الفُضيلُ بنُ عِياضِ بن مسعود بن بشر التميمي اليربوعي الخراساني، المجاوِرُ بحرم الله، وُلِدَ بسمرقند، ونشأ بأبيورد، وارتحلَ في طلَبِ العلم؛ قال الفضل بن موسى: كان الفضيلُ بنُ عياض شاطِرًا يقطَعُ الطَّريقَ بين أبيورد وسرخس، وكان سبَبُ توبته أنَّه عَشِقَ جارية، فبينا هو يرتقي الجُدران إليها، إذ سَمِعَ تاليًا يتلو {أَلَمْ يَأْنِ لِلَّذِينَ آمَنُوا أَنْ تَخْشَعَ قُلُوبُهُمْ لِذِكْرِ اللَّهِ وَمَا نَزَلَ مِنَ الْحَقِّ...} [الحديد: 16] فلمَّا سَمِعَها، قال: بلى يا رَبِّ، قد آن، فرجع، فآواه الليلُ إلى خربةٍ، فإذا فيها سابلةٌ، فقال بعضُهم: نرحَلُ، وقال بعضهم: حتى نُصبحَ؛ فإنَّ فُضَيلًا على الطريق يقطَعُ علينا، قال: ففَكَّرتُ، وقلتُ: أنا أسعى باللَّيلِ في المعاصي، وقومٌ مِن المسلمينَ هاهنا، يخافونني، وما أرى اللهُ ساقني إليهم إلَّا لأرتَدِعَ، اللهمَّ إني قد تبتُ إليك، وجعلتُ توبتي مجاورةَ البيتِ الحرامِ. وقال ابن المبارك: ما بقِيَ على ظهرِ الأرضِ عندي أفضَلُ من الفُضَيل بن عِياضٍ، وقيل: مات- رحمه الله- في ست وثمانين ومئة. قال الذهبيُّ: وله نيِّفٌ وثمانون سنة، وهو حُجَّةٌ كبيرُ القَدرِ."},{"id":613,"title":"تصفية نفوذ البرامكة في دولة هارون الرشيد .","date":["العام الهجري :187","الشهر القمري : صفر","العام الميلادي :803"],"text":"كان لآلِ بَرْمَك نفوذٌ كبيرٌ في دولة الرشيد؛ إذ كان يحيى بن خالدٍ مُربِّيًا للرشيدِ، وكان أولادُه جعفر والفضل وموسى ومحمَّد أترابَ الرَّشيد، ثمَّ تغيَّرَت أحوالُ البرامكة وتبدَّلَ لهم الرشيدُ فجأةً، فقتل جعفرَ بنَ يحيى وسجَنَ يحيى وابنَه الفضلَ، وصادرَ أملاكَهم، وقد قيل في سبب ذلك أشياءُ؛ منها: أنهم- يعني البرامِكةَ- زاد نفوذُهم كثيرًا، وزادت مصروفاتُهم كثيرًا، حتى فاقوا الخليفةَ بذلك؛ ممَّا جعل أمرَهم مُريبًا مُخيفًا؛ فقد بنى جعفرٌ بيتًا له كلَّفَه عشرينَ مليونَ درهم، وعندما عاد الفضلُ بن يحيى مِن حَربِه في الديلم أطلق لمادِحيه ثلاثةَ ملايين درهم. وهذا السَّرفُ جعل الرشيدَ يتابِعُهم في الدواوينِ والكتاباتِ، فاكتشفَ وُجودَ خَلَلٍ كبير في مصاريفِ الدولة. وقيل: لتشَيُّعِهم وتعاطُفِهم مع العَلَويِّينَ؛ فقد حمل يحيى بن خالد البرمكي إلى يحيى بن عبد الله الطالبي في أثناء ثورتِه بالديلم مئتي ألفِ دينارٍ، كما أنَّ جعفرًا أطلَقَه بعد سَجنِه مِن دونِ عِلمِ الخليفة. وقد أحضر الخليفةُ جعفرًا وسأله، فأقرَّ بالأمرِ، فأظهرَ الرَّشيدُ أنَّه راضٍ عن عَمَلِه، فلمَّا خرج مِن مجلِسِه قال: \"قتلني اللهُ بسَيفِ الهُدى على عمَلِ الضَّلالةِ إنْ لم أقتُلْك\", وقد يُعدُّ هذا من أقوى أسبابِ نِقمةِ الرشيدِ عليهم، وقيل: لتعصُّبِهم للفُرسِ ومحاولةِ إقصاءِ العَرَب عن المناصبِ المُهِمَّة؛ فقد أبدَوا كراهيَتَهم لمحمَّد بن الليث لِمَيله عن العجَم، وسَعَوا لدى الرشيدِ للإيقاع بيزيدَ بن مزيد الشيباني، واتَّهَموه بالتراخي في قتالِ الخوارج. وقيل: بل لأنَّ الرشيدَ لَمَّا كان يحِبُّ أن يجتَمِعَ مع جعفر وأختِه العبَّاسة (أخت الرشيد) وهي مُحَرَّمة على يحيى، فزَوَّجَها الرشيدُ مِن جَعفرٍ على ألا يقرَبَها، بل فقط ليجتَمِعوا ويَسمُروا سويًّا، ولكِنَّ جعفرًا أتاها فحَمَلت العبَّاسةُ منه، ولَمَّا ولَدَت وجَّهَته إلى مكَّةَ، ثمَّ عَلِمَ الرشيدُ بذلك من بعضِ حواضِنِ العبَّاسة، فعَدَّ ذلك خيانةً مِن جعفرٍ،  وقد تناقل المؤرِّخونَ قِصَّةَ عبَّاسة وجعفرٍ البرمكيِّ، وكأنَّها أحدَثَت فِعلًا، بينما عليَّةُ بنتُ المهدي تقولُ للرَّشيدِ بعد إيقاعِه بالبرامكة: ما رأيتُ لك يومَ سرورٍ تامًّا منذ قتَلْتَ جعفرًا، فَلأيِّما شيءٍ قَتَلْتَه؟ فقال: لو عَلِمتُ أنَّ قَميصي يعلمُ السَّببَ الذي قتلْتُ به جعفرًا لأحرقتُه. فهل كانت عليَّة بنت المهدي جاهلةً السَّبَبَ لو كان هناك مِثلُ هذه الفضيحة (قِصَّة عبَّاسة وجعفر البرمكيِّ) في قصرِ الخلافة؟!"},{"id":614,"title":"نَكْثُ نقفور للعهد وغزو الروم .","date":["العام الهجري :188","العام الميلادي :803"],"text":"بعد أن غزا الرشيدُ نقفور وطلبَ الصُّلحَ وقَبِلَ منه، قام نقفور بنكثِ العَهدِ في نفسِ السَّنة، لكن الأمرَ لم يصِلْ إلى الرشيدِ إلَّا بعد سنةٍ؛ للبَردِ الشَّديد الذي منع وصولَ البريدِ، فغزا إبراهيمُ بن جبرئيل الصائفة، فدخل أرضَ الروم من درب الصفصاف، فخرج إليه نقفور ملكُ الروم، فأتاه مِن ورائه أمرٌ صَرَفه عنه، ولَقِيَ جمعًا من المسلمين، فجرح ثلاث جِراحات، وقُتِلَ مِن الروم- فيما قيل- أربعون ألفًا وسبعمائة."},{"id":615,"title":"وفاة علي بن حمزة الكسائي .","date":["العام الهجري :189","العام الميلادي :804"],"text":"هو أبو الحسنُ عليُّ بن حمزة بن عبد الله بن بهمن بن فيروز الأسدي مولاهم الكوفيُّ الملقَّبُ بالكسائيِّ؛ لكساءٍ أحرَمَ فيه، وُلِدَ بالكوفةِ نحو 120هـ, اختار قراءةً اشتَهَرت عنه، وصارت إحدى القراءاتِ السَّبع، وجالس في النحو الخليلَ، وسافر في بادية الحجازِ مُدَّةً للعربيَّة، قال الشافعي: \"من أراد أن يتبحَّرَ في النحو فهو عيالٌ على الكسائيِّ\". وقال ابن الأنباري: \"اجتمع في الكسائيِّ أمور: كان أعلمَ النَّاسِ بالنحو، وواحِدَهم في الغريبِ، وكان أوحدَ الناسِ في القرآن، وكانوا يُكثِرونَ عليه حتى لا يضبطَ عليهم، فكان يجمَعُهم ويجلِسُ على كرسيٍّ ويتلو القرآنَ مِن أوَّلِه إلى آخره وهم يسمعون، ويَضبِطون عنه حتى المقاطِعَ والمبادئَ\" له عدةُ تصانيفَ منها: معاني القرآن، وكتاب في القراءات، وكتاب النوادر الكبير، ومختَصَر في النحو، وغير ذلك. مات بالريِّ بقرية أرنبوية عن سبعين سنة، وفي تاريخِ موتِه أقوال، وأصحُّها أنَّها سنة تسع وثمانين ومئة."},{"id":616,"title":"وفاة محمد بن الحسن الشيباني صاحب أبي حنيفة .","date":["العام الهجري :189","العام الميلادي :804"],"text":"هو العلَّامة، فقيهُ العراق أبو عبد الله محمد بن الحسن بن فرقد الشَّيباني ولاءً، أصلُه من الغوطة، صاحِبُ أبي حنيفة، ولد سنة 131هـ بواسط, نشأ في الكوفة فسَمِعَ من أبي حنيفة، وأخذ عنه طريقتَه، لم يجالِسْه طويلًا لوفاة أبي حنيفة، فأتمَّ الطريقةَ على أبي يوسف، رحل إلى المدينةِ وأخذ عن الإمامِ مالكٍ، واتَّصل بالشافعيِّ، وكان بينهما مناظراتٌ معروفةٌ، تولى القضاءَ للرَّشيدِ ثمَّ اعتزل القضاءَ وتفَرَّغ لتعليمِ الفِقه، كانت وفاتُه في الريِّ، وكان يومَها مع الرشيد."},{"id":617,"title":"فدية أسارى المسلمين من بلاد الروم .","date":["العام الهجري :189","العام الميلادي :804"],"text":"رابَطَ في هذه السنة القاسِمُ بن الرشيد في مرج دابق، وفادى الرشيدُ الأُسارى من المسلمين الذين كانوا في بلاد الرومِ، حتى لم يبقَ أسيرٌ واحِدٌ."},{"id":618,"title":"شَغبُ أهل المغرب على وُلاتِهم من دولة الأغالبة .","date":["العام الهجري :189","الشهر القمري : شعبان","العام الميلادي :805"],"text":"كثُرَ شَغبُ أهل طرابلس الغرب على وُلاتِهم، وكان إبراهيمُ بن الأغلب أميرُ إفريقيَّةَ قد استعمَلَ عليهم عِدَّةَ وُلاةٍ، فكانوا يَشكُون من وُلاتِهم، فيَعزِلُهم، ويولِّي غَيرَهم، فاستعمل عليهم هذه السَّنةَ سُفيانَ بنَ المضاء، وهي ولايتُه الرابعة، فاتَّفق أهلُ البلد على إخراجه عنهم، وإعادتِه إلى القيروان، فزَحَفوا إليه، فأخذ سلاحَه، وقاتَلَهم هو وجماعةٌ ممَّن معه، فأخرجوه من داره، فدخل المسجِدَ الجامع، فقاتَلَهم فيه، فقتلوا أصحابَه، ثم أمَّنوه، فخرج عنهم، فكانت ولايتُه سبعًا وعشرين يومًا."},{"id":619,"title":"المسلمون يعاودون غزو قبرص  .","date":["العام الهجري :190","العام الميلادي :805"],"text":"نقَضَ أهلُ قُبرص العهدَ، فقام معيوف بن يحيى أميرُ سواح الشامِ ومصر بالسَّيرِ إليهم بأسطولٍ كبيرٍ، فغزاهم وأسَرَ أسقُفَهم وسبى من أهلِها الكثيرَ، وقتل الكثيرَ، ثم سار إلى جزيرة كريت ورودوس."},{"id":620,"title":"فتنة رافع بن الليث بن سيَّار في سمرقند .","date":["العام الهجري :190","العام الميلادي :805"],"text":"كان رافِعُ بن نصرِ بنِ الليث بن سيَّار من عظماء الجندِ فيما وراء النهر، وكان يحيى بن الأشعَثِ الطائي قد تزوَّجَ ابنةَ عَمٍّ له، وكانت ذاتَ يَسارٍ ولِسانٍ وجَمالٍ, ثم ترَكَها بسمرقند فترةً وأقام ببغداد، واتَّخذَ السَّراريَّ، فلما طال ذلك عليها، أرادت أن تخلصَ مِن زواجها له, فعَلِمَ رافِعٌ بأمرِها فتزوَّجَها بعد أن قال لها أن تُظهِرَ الشِّركَ ثم تتوبَ فيَنفَسِخَ نِكاحُها, فشكاه زوجُها يحيى بن الأشعث إلى الرشيدِ، فأمر الرشيدُ عامِلَه على سمرقند عليَّ بن عيسى بن ماهان أن يَحُدَّه ويُطلقَ منها ويُطيفه على حمارٍ في سمرقند للعبرةِ، ففعل لكِنَّه لم يحدَّه وحَبَسَه فهرب من الحبسِ، فلَحِقَ ببلخ فأراد عامِلُها علي بن عيسى قَتْلَه فشَفعَ فيه عيسى بن علي بن عيسى، وأمَرَه بالانصرافِ إلى سمرقند."},{"id":621,"title":"خروج رافع بن الليث بن نصر في خراسان .","date":["العام الهجري :190","العام الميلادي :805"],"text":"خلع رافِعُ بنُ الليث بن نصر بن سيَّار نائبُ سمرقند الطاعةَ، ودعا إلى نفسِه، وتابعه أهلُ بلَدِه وطائفةٌ كثيرةٌ من تلك الناحية، واستفحل أمرُه، فسار إليه نائِبُ خراسان علي بن عيسى، فهزمه رافِعٌ وتفاقم الأمر به. فجمَعَ له عليُّ بن عيسى جيشًا لقِتالِه، فلما قَتَل رافِعُ بن الليثِ عيسى بن علي خرج عليُّ بن عيسى مِن بَلْخ حتى أتى مرْوًا مخافةَ أن يسيرَ إليها رافع بن الليث، فيستولي عليها، فلما علم الرشيد بذلك خلَعَه وعيَّنَ بدلًا عنه هرثمة بن أعين."},{"id":622,"title":"فتح هرقلة  .","date":["العام الهجري :190","الشهر القمري : شوال","العام الميلادي :806"],"text":"فتح الرَّشيدُ هرقلةَ، وكان سببُ مَسيرِه إليها ما حصل سنةَ سبعٍ وثمانين ومائة، من غَدرِ نقفور، فحاصرَ الرَّشيدُ هرقلة ثلاثين يومًا وسَبى أهلَها، وكان قد دخل البلادَ في مائة ألف وخمسة وثلاثين ألفًا من المرتَزِقة، سوى الأتباعِ والمتطَوِّعة، ومَن لا ديوان له، وأناخ عبدُ الله بن مالك على ذي الكلاع، ووجَّه داود بن عيسى بن موسى سائرًا في أرضِ الرُّوم في سبعين ألفًا، ففتَحَ الله عليه، وفتح شراحيل بن معن بن زائدة حِصنَ الصقالبة ودلسة، وافتتح يزيدُ بن مخلد الصفصاف وملقونية، كما أجبَرَ نقفور على دفْعِ جزيةٍ كبيرةٍ للمسلمين وإلزامه بها، فبعث نقفور بالخَراجِ والجِزية عن رأسِه أربعةَ دنانير، وعن رأسِ ولده دينارين، وعن بطارقتِه كذلك، وكتب نقفور إلى الرشيدِ في جاريةٍ مِن سَبيِ هرقلة كان خطَبَها لولَدِه، فأرسلَها إليه."},{"id":623,"title":"هارون الرشيد يأمر بتمييز لباس أهل الذمة في بغداد .","date":["العام الهجري :191","العام الميلادي :806"],"text":"أمرَ الرَّشيدُ بهَدمِ الكنائسِ والدُّورِ بالثُّغور، وألزم أهلَ الذمَّة بتمييزِ لباسِهم وهيئاتِهم ورَكوبِهم عن المُسلمين في بغداد وغَيرِها من البلاد."},{"id":624,"title":"وقعة الحفرة في أهل طليطلة .","date":["العام الهجري :191","العام الميلادي :806"],"text":"أوقع الأميرُ الحكَمُ بنُ هشام- صاحب الأندلس- بأهل طليطِلة، فقتلَ منهم ما يزيدُ على خمسةِ آلاف رجلٍ مِن أعيان أهلِها، وسببُ ذلك أنَّ أهلَ طُليطِلة كانوا قد طَمِعوا في الأمراءِ، وخَلَعوهم مرَّةً بعد أخرى، وقَوِيَت نفوسُهم بحصانةِ بلَدِهم وكثرةِ أموالِهم، فلم يكونوا يطيعونَ أمراءَهم طاعةً مُرضيةً، فلما أعيا الحكَمَ شأنُهم أعمل الحيلةَ في الظفَرِ بهم، فاستعان في ذلك بعَمروس بن يوسف المعروف بالمولد، حيث دخل طليطِلة وأنِسُوا به واطمأنُّوا له، وأشاع عمروس أنَّ عبد الرحمن بن الحكَم يريدُ أن يتَّخِذَ لهم وليمةً عظيمةً، وشرَعَ في الاستعدادِ لذلك، وواعدهم يومًا ذكَرَه، وقَرَّر معهم أن يدخُلوا من بابٍ، ويخرُجوا من آخَرَ ليقِلَّ الزِّحامُ، ففعلوا ذلك، فلما كان اليومُ المذكورُ أتاه الناس أفواجًا، فكان كلمَّا دخلَ فوجٌ، أُخِذوا وحُمِلوا إلى جماعةٍ مِن الجندِ على حُفرةٍ كبيرةٍ في ذلك القَصرِ، فضُرِبَت رقابُهم عليها، فذَلَّت رقابُهم بعدها وحَسُنَت طاعتُهم بقيَّةَ أيامِ الحَكَم وأيَّام ولده عبد الرحمن، ثم انجبَرَت مصيبتُهم، وكَثُروا، فلما هلك عبدُ الرحمن ووَلِيَ ابنُه محمَّد عاجلوه بالخلعِ."},{"id":625,"title":"هزيمة لزريق بالأندلس .","date":["العام الهجري :191","العام الميلادي :806"],"text":"تجهَّزَ لذريق ملك الفرنج بالأندلس، وجمعَ جموعَه ليسيرَ إلى مدينة طرطوشة ليحصرَها، فبلغ ذلك الحكَمَ بنَ هشامٍ صاحِبَ الأندلس، فجمع العساكِرَ وسيَّرَها مع ولده عبد الرحمن، فاجتمعوا في جيشٍ عظيمٍ، وتَبِعَهم كثيرٌ من المتطَوِّعة، فساروا فلَقُوا الفرنج في أطرافِ بلادهم قبل أن ينالوا من بلادِ المسلمينَ شيئًا، فاقتتلوا وبذلَ كُلٌّ من الطائفتين جُهدَه، واستنفَدَ وُسعَه، فأنزل الله تعالى نَصرَه على المسلمين، فانهزم الكُفَّارُ، وكثُرَ القتلُ فيهم، والأسْرُ، ونُهِبَت أموالُهم وأثقالُهم، وعاد المسلمونَ ظافرينَ غانِمينَ."},{"id":626,"title":"خروج ثروان الحروري بسواد العراق .","date":["العام الهجري :191","العام الميلادي :806"],"text":"خرج رجلٌ بسَوادِ العِراقِ يُقالُ له ثروانُ بن سيف الحروري، وجعل يتنقَّلُ فيها من بلدٍ إلى بلد، فوَجَّه إليه الرشيدُ طَوقَ بن مالك فهَزَمَه، وجُرِحَ ثروان وقُتِلَ عامَّةُ أصحابه، وكتبَ بالفتح إلى الرَّشيد، لكِنَّ ثروان هرب فنجا من القتل."},{"id":627,"title":"تأسيسُ مدينة فاس في المغرب .","date":["العام الهجري :193","العام الميلادي :808"],"text":"تم تأسيسُ مدينة فاس على يدِ إدريس الأوَّل مؤسِّس دولة الأدارِسة في المغرب، وليس إدريس الثاني كما هو شائِعٌ."},{"id":628,"title":"وفاة الخليفة العباسي هارون الرشيد .","date":["العام الهجري :193","الشهر القمري : جمادى الآخرة","العام الميلادي :809"],"text":"هو هارونُ الرَّشيدُ أميرُ المؤمنينَ ابنُ المهديِّ محمد بن أبي جعفر المنصور، أبو محمد، ويقال أبو جعفر. وأمُّه الخَيزُران أمُّ ولَدٍ. كان مولِدُه في شوَّال سنة 147هـ وقيل غيرُ ذلك, وبويِعَ له بالخلافةِ بعد موت أخيه الهادي في ربيع الأوَّل سنة 170هـ، بعهدٍ مِن أبيه المهدي. وكان الرشيدُ أبيضَ طويلًا سمينًا جَميلًا، وقد غزا الصائفةَ في حياة أبيه مرارًا، وعقد الهدنةَ بين المسلمين والرومِ بعد محاصرتِه القُسطنطينيَّة، ثمَّ لَمَّا أفضَت إليه الخلافةُ في سنة سبعين كان من أحسَنِ النَّاسِ سِيرةً وأكثَرِهم غَزوًا وحَجًّا، وكان يتصَدَّقُ مِن صُلبِ مالِه في كلِّ يومٍ بألفِ دِرهمٍ، وإذا حَجَّ أحَجَّ معه مائةً من الفُقَهاء وأبنائِهم، وإذا لم يحُجَّ أحَجَّ ثلاثَمائة بالنَّفقةِ السابغةِ والكُسوةِ التَّامَّة، وكان يحِبُّ التشَبُّهَ بجَدِّه أبي جعفرٍ المنصورِ إلَّا في العطاءِ؛ فإنَّه كان سريعَ العَطاءِ، جزيلَه، وكان يحِبُّ الفُقَهاءَ والشُّعَراءَ ويُعطيهم. كان هارونُ الرَّشيد قد سار إلى خراسانَ لقِتالِ رافِعِ بنِ الليثِ، وكان مريضًا ثم اشتَدَّ مَرَضُه عند دخولِهم طوس- قرية من قرى سناباذ- ومات ودفُنَ فيها عن عمر سبع وأربعين سنة, بعد أن دامَت خلافتُه عشرين عامًا، وقيل: ثلاثةً وعشرين, وقد كانت حافِلةً بالفتوحِ والعِمارة."},{"id":629,"title":"الأمين يتولى خلافة الدولة العباسية  .","date":["العام الهجري :193","الشهر القمري : جمادى الآخرة","العام الميلادي :809"],"text":"كان الرَّشيدُ قد عقد الخلافةَ لابنه الأمينِ ثمَّ للمأمونِ لِمَكانةِ زبيدة والدةِ الأمينِ، وإلَّا فالمأمونُ أكبَرُ منه، فبويع الأمينُ بالخلافة في عسكرِ الرشيد، صبيحةَ الليلة التي توفِّيَ فيها، وكان المأمونُ حينئذ بمرو، فكتب حمويه مولى المهديِّ، صاحبُ البريدِ، إلى نائبِه ببغداد- وهو سلام بن مسلم- يُعلِمُه بوفاةِ الرشيد، فدخل أبو مسلمٍ على الأمينِ فعَزَّاه وهنَّأه بالخلافة، فانتقل مِن قصرِه بالخُلد إلى قصرِ الخلافةِ، وبايعه الناسُ."},{"id":630,"title":"الأمين يعلن خلع أخويه المأمون والمؤتمن من ولاية العهد .","date":["العام الهجري :193","الشهر القمري : جمادى الآخرة","العام الميلادي :809"],"text":"كان الرَّشيدُ في أثناء مسيرِه إلى خراسانَ، وكان المأمونُ في مرو بخُراسان، وكان الأمينُ في بغداد، فأخذ الرشيدُ البيعةَ مِن جُندِه الذين معه أن يطيعوا للمأمونِ ويَبقَوا معه، ولكِنَّ الفَضلَ بنَ الربيعِ عاد بالجُندِ إلى بغداد، ثم أوحى للأمينِ أن يَعقِدَ البيعةَ لابنِه موسى ثمَّ للمأمونِ، فلمَّا علم بذلك المأمونُ قَطَعَ البريدَ عن الأمينِ وأسقطَ اسمَه من الطرز، وأمَّنَ رافِعَ بنَ اللَّيثِ وأكرَمَه، كما أكرَمَ هرثمة بن أعيَن، الذي كان مكَلَّفًا بقتالِ رافعٍ، فقَوِيَت فِكرةُ خَلعِ المأمونِ من ولاية العهدِ وتوليةِ ابنِه مكانه، وأمر الخليفةُ الأمينُ بالدعاءِ لابنه موسى على المنابرِ بعد ذكَرَ المأمون والقاسم، فتنكَّرَ كلُّ واحدٍ مِن الأمينِ والمأمون لصاحِبِه، وظهر الفسادُ بينهما، وهذا أوَّلُ الشَّرِّ والفتنةِ بين الأخوين. ثم أرسلَ الأمينُ في أثناء السنةِ إلى المأمون يسألُه أن يُقَدِّمَ ولدَ الأمين موسى المذكورَ على نفسِه، ويذكُرَ له أنَّه سمَّاه الناطِقَ بالحقِّ، فقَوِيَت الوحشةُ بينهما أكثَرَ."},{"id":631,"title":"عصيان أهل ماردة على الحكَم بن هشام أميرِ الأندلُس .","date":["العام الهجري :194","العام الميلادي :809"],"text":"في هذه السَّنةِ عاود أهلُ ماردة الخلافَ على الحكَم بن هشام أميرِ الأندلُس، وعصُوا عليه، فسار بنَفسِه إليهم وقاتَلَهم، ولم تَزَل سراياه وجيوشُه تتردَّدُ وتقاتِلُهم على مدى ثلاثِ سَنَوات."},{"id":632,"title":"خلاف أهل تونس على ابن الأغلب .","date":["العام الهجري :194","الشهر القمري : جمادى الآخرة","العام الميلادي :810"],"text":"تمرَّدَ عِمرانُ بن مجالد الربيعيُّ، وقُريشُ بن التونسي بتونُسَ على إبراهيمَ بنِ الأغلب أميرِ إفريقيَّةَ، واجتمع فيها خلقٌ كثير، وحُصِرَ إبراهيمُ بن الأغلب بالقصرِ وجمعٌ ممَّن أطاعه، وخالفَ عليه أيضًا أهلُ القيروان، فكانت بينهم وقعةٌ وحَربٌ قُتِلَ فيها جماعةٌ مِن رجالِ ابن الأغلب. وقَدِمَ عِمرانُ بنُ مجالد فيمن معه، فدخل القيروانَ عاشر رجب، وقَدِمَ قُريش من تونس عليه، فكانت بينهم وبين ابن الأغلبِ وَقعةٌ في رجب، فانهزم أصحابُ ابن الأغلب، ثم التَقَوا في العشرين منه فانهزموا ثانيةً أيضًا، ثم التقوا ثالثةً فيه أيضًا فكان الظَّفَرُ لابن الأغلب، وأرسل عِمرانُ بن مجالد إلى أسدِ بن الفرات الفقيهِ ليخرُجَ معهم، فامتنع، فعاد الرسولُ يقول له: تخرجُ معنا وإلَّا أرسلتُ إليك من يجُرُّ برِجلِك، فقال أسدٌ للرسول: قل له: واللهِ إن خَرجتُ لأقولنَّ للنَّاسِ إنَّ القاتلَ والمقتولَ في النَّارِ، فتَرَكه."},{"id":633,"title":"موقعة الري وهزيمة جيوش الأمين أمام جيش المأمون .","date":["العام الهجري :195","العام الميلادي :810"],"text":"عقَد الأمينُ لعليِّ بنِ عيسى بن ماهان بالإمرةِ على الجبل وهمذان وأصبهان وقُم، وأمره بحربِ المأمونِ، وجَهَّزَه بجيشٍ كبير، فلمَّا وصل الجيشُ إلى الريِّ تلقَّاه طاهِرُ بن الحسين قائِدُ المأمون، فاقتتَلَ الطرفانِ، فقُتِلَ عليُّ بنُ عيسى بن ماهان، وانهزم جيشُه، ولَمَّا وصل الخبرُ إلى الأمين جهَّز جيشًا آخر بإمرةِ عبدالرحمن بن جَبَلة الأنباريِّ، ولكنَّه هُزِمَ هو أيضًا، فهرب بجيشِه إلى همذان، وطلب الأمانَ من طاهرِ بنِ الحُسين، فأمَّنَهم ولكنَّهم غدروا به وبجيشِه، وقتلوا منهم الكثيرَ، فنهض إليهم طاهِرٌ وقاتَلَهم، فقُتِلَ عبدالرحمن بن جَبَلة، وفَرَّ من نجا من القتلِ، ثم عاد الأمينُ فوَجَّه أحمد بن يزيد وعبدَ اللهِ بن حُميد بن قحطبة في أربعين ألفًا إلى حلوان لقِتالِ طاهِرِ بن الحُسين، وكان هذا في العامِ التَّالي، فلما وصَلوا إلى قريبٍ مِن حلوان خندق طاهِرٌ على جيشِه خندقًا، وجعل يعمَلُ الحيلةَ في إيقاعِ الفِتنةِ بين الأميرينِ، فاختلفا فرجعا ولم يُقاتِلاه، ودخل طاهِرٌ إلى حلوان، وجاءه كتابُ المأمون بتسليمِ ما تحت يدِه إلى هرثمة بن أعْيَن، وأن يتوجَّه هو إلى الأهواز، ففعل ذلك."},{"id":634,"title":"ظهور السفياني في الشام .","date":["العام الهجري :195","الشهر القمري : ذي الحجة","العام الميلادي :811"],"text":"ظهَرَ السُّفيانيُّ بدمشقَ وبويع بالخلافةِ، واسمُه عليُّ بن عبد الله بن خالد بن يزيد بن معاوية بن أبي سفيان، وطرَدَ عامِلَ الأمينِ عن دمشق- وهو سليمانُ بن أبي جعفر- بعد أن حصَرَه السفيانيُّ بدمشق مدَّةً، ثمَّ أفلت منه، وخالد بن يزيد جدُّ السفياني هذا، هو الذي وضع حديثَ السُّفياني في الأصل؛ فإنَّه ليس بحديثٍ، غيرَ أن خالدًا لَمَّا سَمِعَ حديثَ (المهديُّ من أولادِ عليٍّ في آخِرِ الزَّمانِ) أحَبَّ أن يكونَ مِن بني سُفيانَ من يظهَرُ في آخر الزمان، فوضعَ حديثَ السُّفياني؛ فمشى ذلك على بعضِ العوامِّ، ثم بعث الأمينُ إليه جيشًا، لكنهم بَقُوا في الرقَّة ولم يسيروا إلى دمشق؛ فقد قاتله ابنُ بيهس محمد بن صالح وغلَبَه وضَعُف أمر السفياني وقُتِلَ ممَّن كان معه الكثيرُ، ثمَّ قُبِضَ عليه وسُجِنَ، ثمَّ هرب بعد ذلك."},{"id":635,"title":"الحكم بن هشام ينتصر لأهل الثغور .","date":["العام الهجري :196","العام الميلادي :811"],"text":"لَمَّا انشغل الحكَمُ بن هشام بإخماد عِصيانِ أهل مارد. طمِعَ الفرنج في ثغورِ المسلمين، وقَصَدوها بالغارة والقتل، والنَّهبِ والسَّبي، فأتاه الخبَرُ بشِدَّة الأمر على أهل الثغر، وما بلغ العدوُّ منهم، وسَمِعَ أنَّ امرأةً مُسلمةً أُخِذَت سبيةً، فنادت: واغَوْثاه، يا حَكَمُ! فعَظُمَ الأمر عليه، وكان قد فرَغ من أهل ماردِ، فجمَعَ عَسكَرَه واستعَدَّ وحَشَد وسار إلى بلد الفرنج, وأثخَنَ في بلادهم، وافتتح عِدَّةَ حُصونٍ، وقتَل الرِّجالَ، وسبى الحريمَ، وقصَدَ الناحيةَ التي كانت بها تلك المرأةُ، فأمَرَ لهم من الأسرى بما يُفادون به أَسراهم، وبالغ في الوصيَّة في تخليص تلك المرأة، فتخَلَّصَت من الأسر، وقُتِل باقي الأسرى، فلما فرغ من غَزاتِه قال لأهل الثغور: هل أغاثكم الحَكَمُ؟ فقالوا: نعم، ودَعَوا له وأثنَوا عليه خيرًا، وعاد إلى قُرطبة مُظفرًا."},{"id":636,"title":"وفاة أبي نواس الشاعر .","date":["العام الهجري :196","العام الميلادي :811"],"text":"هو الحسَنُ بن هانئ بن صباح بن عبد الله، اشتهر بالشِّعرِ، ولكنَّه أدخل فيه ما يُستقذَرُ، حتى اتُّهِم، ذكروا له أمورًا كثيرة، ومُجونًا وأشعارًا مُنكَرة، وله في الخَمريَّات والقاذورات والتشبُّب بالمُردان والنِّسوان أشياءُ بِشَعةٌ شَنيعةٌ؛ فمِن النَّاسِ من يفَسِّقُه ويرميه بالفاحشةِ، ومنهم من يرميه بالزَّندقة،  كان أبو نواس شاعِرَ الأمينِ بن الرشيد وأحدَ نُدَمائه، وقد قال في الأمين مدائِحَ حِسانًا، وقد وجده مسجونًا في حبسِ الرَّشيدِ مع الزَّنادقةِ، فأحضره وأطلقه وأطلق له مالًا، فجعله مِن نُدَمائه، ثمَّ حَبَسه مرَّةً أخرى في شُربِ الخَمرِ، وأطال حبسَه ثمَّ أطلَقَه وأخذ عليه العهدَ ألَّا يشرَبَ الخمرَ ولا يأتي الذُّكورَ من المردان، فامتثل ذلك، وكان لا يفعَلُ شيئًا من ذلك بعد ما استتابه الأمينُ، وتأدَّبَ على الكسائيِّ وقرأ عليه القرآنَ. كانت وفاته ببغداد، ودُفِنَ في مقابر الشونيزى في تل اليهود."},{"id":637,"title":"انقلاب داخلي في بغداد على الخليفة العباسي الأمين .","date":["العام الهجري :196","الشهر القمري : رجب","العام الميلادي :812"],"text":"كان الأمينُ قد أرسل عبدالملك بن صالح بن عليٍّ إلى الشام ليجمَعَ له الجُندَ، لكنَّه توفي في الرقَّة، فتولى أمرَ الجُندِ الحُسينُ بن علي بن ماهان، فعاد بهم إلى بغداد، ورفض القدومَ على الأمين الذي أرسلَ إليه من يُحضِرُه، فاقتتل الطرفانِ وانهزم الجمعُ الذين أرسَلَهم الأمين، فخلَعَ الحُسَينُ الأمينَ يومَ الأحدِ لإحدى عشرة ليلةً خلَت من رجب، وأخذ البيعةَ للمأمونِ مِن الغدِ يوم الاثنين، فلما أصبح الناسُ يوم الأربعاء طلبوا مِن الحُسين بن عليٍّ أُعطِياتِهم واختلفوا عليه، وصار أهل بغداد فرقتينِ؛ فِرقةً مع الأمينِ، وفرقةً عليه، فاقتتلوا قتالًا شديدًا، فغلب حزبُ الخليفة، وأسَروا الحُسَين بنَ علي بن عيسى بن ماهان وقَيَّدوه، ودخلوا به على الخليفة ففكُّوا عنه قيودَه، ثم إنَّ الأمينَ عفا عن الحسين وولَّاه الجُندَ وسَيَّرَه إلى حلوان، فلما وصل إلى الجِسرِ هرب في حاشيتِه وخَدَمِه، فبعث إليه الأمين من يرُدُّه، فرَكِبَت الخيولُ وراءه فأدركوه فقاتَلَهم وقاتلوه، فقتلوه لِمُنتَصف رجب."},{"id":638,"title":"توقيع اتفاق حسن الجوار بين الدولة الرستمية ودولة الأغالبة .","date":["العام الهجري :197","العام الميلادي :812"],"text":"ثار أبو عصامٍ ومَن وافقه على إبراهيمَ بن الأغلب، أميرِ إفريقيَّة، فحاربهم إبراهيمُ، فظَفِرَ بهم. واستعمل ابنُ الأغلب ابنَه عبدالله على طرابلس الغرب، فلما قدِمَ إليها ثار عليه الجُندُ، فحصروه في داره، ثم اصطَلَحوا على أن يخرُجَ عنهم، فخرج عنهم، فلم يُبعِد عن البلد حتى اجتمع إليه كثيرٌ من الناس، ووضَعَ العطاء، فأتاه البربرُ من كل ناحية، فاجتمع له عددٌ كثير، فزحف بهم إلى طرابلس، فخرج إليه الجُند، فاقتتلوا فانهزمَ جُند طرابلس، ودخل عبد الله المدينةَ، وأمَّنَ الناسَ وأقام بها؛ ثمَّ عزله أبوه، واستعمل بعده سُفيانَ بن المضاء، فثارت هوارة بطرابلُس، فخرج الجندُ إليهم، والتَقَوا واقتتلوا، فهُزِمَ الجند إلى المدينة، فتَبِعَهم هوارة، فخرج الجندُ هاربين إلى الأميرِ إبراهيم ابن الأغلب، ودخلوا المدينةَ فهَدَموا أسوارها. وبلغ ذلك إبراهيمَ ابن الأغلب، فسيَّرَ إليها ابنَه أبا العباس عبد الله في ثلاثة عشر ألف فارس، فاقتتل هو والبربر، فانهزم البربرُ، وقُتِل كثيرٌ منهم، ودخل طرابلس وبنى سورها. وبلغ خبَرُ هزيمة البربر إلى عبد الوهاب بن عبد الرحمن بن رستم، وجمع البربرَ وحَرَّضَهم، وأقبل بهم إلى طرابلس، وهم جمعٌ عظيم، غضبًا للبربر ونصرةً لهم، فنزلوا على طرابلس، وحصروها. فسدَّ أبو العباس عبد الله بن إبراهيم بابَ زناتة، ولم يزل كذلك إلى أن توفِّي أبوه إبراهيم بن الأغلب، وعَهِدَ بالإمارة لولده عبد الله، فأخذ أخوه زيادةُ الله بن إبراهيم له العهودَ على الجند، وسيَّرَ الكتاب إلى أخيه عبد الله، يخبِرُه بموت أبيه، وبالإمارة له، فأخذ البربرُ الرسولَ والكتابَ، ودفعوه إلى عبد الوهاب بن عبد الرحمن بن رستم، فأمر بأن يناديَ عبد الله بن إبراهيم بموت أبيه، فصالَحَهم على أن يكونَ البلدُ والبحر لعبد الله، وما كان خارجًا عن ذلك يكونُ لعبد الوهاب، وسار عبدُ الله إلى القيروان، فلقيه الناس، وتسلَّمَ الأمرَ، وكانت أيَّامُه أيامَ سُكونٍ ودَعةٍ."},{"id":639,"title":"تخريب مدينة بغداد واستسلام الخليفة العباسي الأمين .","date":["العام الهجري :197","العام الميلادي :812"],"text":"بعد أن عادت الأمور في بغداد للأمين، كان جيشُ المأمون بقيادة طاهر بن الحسين وهَرثمةَ بنِ أعيَنَ قادمًا إلى بغداد، فلمَّا اقتَرَبوا منه عادت الفوضى وخَلَعَت بعضُ الأقاليم الأمين وبايَعَت للمأمون، حتى إنَّ موسم الحج دُعِيَ فيه للمأمون، ثم حاصر الجيشُ بغداد فضَعُفَ أمر الأمين وخاصَّةً أنَّ طاهِرَ بنَ الحسين قد استولى على الضِّياعِ والإنتاجِ، وأجابه كثير من قوَّاد الأمين إلى بيعةِ المأمون، ثم دخل جيشُ المأمون إلى بغداد وحصل القتالُ فيها حتى لم يبقَ مع الأمين إلَّا القليلُ؛ ممَّا اضطَّره إلى طلب الأمانِ من هرثمة بن أعين الذي أمَّنَه وأخذه في سفينةٍ، وقد كان حصل تخريبٌ وتحريقٌ كثيرٌ في بغداد، بدُخولِ الجيشِ وحُصولِ القتالِ، وهذه عادةُ كلِّ فتنةٍ، نسألُ اللهَ السلامةَ."},{"id":640,"title":"وفاة جابر بن حيان عالم الكيمياء  .","date":["العام الهجري :197","العام الميلادي :812"],"text":"هو جابِرُ بنُ حيان بن عبد الله الأزدي أبو الكيمياء، فيلسوفٌ كيميائيٌّ، ولد عام 101هـ كان يُعرَف بالصوفي. من أهل الكوفة، وأصلُه من خراسان، له تصانيف كثيرة، قيل: عددها 232 كتابًا، وقيل: بلغت خمسَمائة. ضاع أكثَرُها، وتُرجِمَ بعضُ ما بقي منها إلى اللاتينية، منها أسرار الكيمياء، وعلم الهيئة، وأصول الكيمياء، وقد اشتملت كتبُه على بيان مركَّبات كيماويَّة كانت مجهولةً قبله. وهو أوَّلُ من وصف أعمالَ التقطيرِ والتبلْوُر والتذويب والتحويل، وصَفَه ابن خلدون في مقدِّمتِه بقوله: \"إمامُ المدوِّنين جابر بن حيان، حتى إنَّهم يخصُّونها به فيُسَمُّونها علمَ جابرٍ\" ويعَدُّ جابرٌ من أعلام العباقرةِ وأوَّلَ رائدٍ للكيمياء، وكان يشارُ إليه بالأستاذ جابر بن حيان. وقال عنه الفيلسوفُ الإنكليزي فرانسيس بيكون: \"إنَّ جابر بن حيان هو أوَّلُ من علَّم عِلمَ الكيمياءِ للعالَم؛ فهو أبو الكيمياء\"، كما قال عنه العالمُ الكيميائي الفرنسي مارسيلان بيرتيلو: \"إنَّ لجابرِ بنِ حيَّان في الكيمياء ما لأُرسطو في المنطِق\" توفي بطوس، وقيل: كانت وفاته سنة 200هـ"},{"id":641,"title":"وقعة الميدان بين اليمانية والنِّزارية في الموصل .","date":["العام الهجري :198","العام الميلادي :813"],"text":"كانت بين اليمانية والنِّزارية وكان سببُها أنَّ عُثمانَ بنَ نُعيم البرجمي صار إلى ديارِ مُضَر، فشكا الأزدَ واليمن، وقال: إنَّهم يغلبونَنا على حُقوقنا واستنصَرَهم، فسار معه إلى الموصِل ما يقارب عشرين ألفًا, فأرسل إليهم عليُّ بن الحسن الهمداني، وهو حينئذٍ متغَلِّبٌ على الموصِل، فسألهم عن حالهم، فأخبَروه، فأجابهم إلى ما يريدون، فلم يقبَلْ عثمان ذلك، فخرج إليهم عليُّ بن الحسَن مِن الموصِل في نحو أربعةِ آلاف رجل، فالتقَوا واقتَتَلوا قتالًا شديدًا عدَّة وقائِعَ، فكانت الهزيمةُ على النزاريَّة، وظفِرَ بهم عليُّ بنُ الحسن، وقتل منهم خلقًا كثيرًا وعاد إلى البلد."},{"id":642,"title":"غزو الحكم بن هشام لسمورة .","date":["العام الهجري :198","العام الميلادي :813"],"text":"همَّت الرُّوم بما لم ينالوا من طلَبِ الثغور، فنكَثوا العهدَ، فتجهَّزَ الحكَمُ بن هشامٍ إليهم حتى جاز جبلَ السارة شماليَّ طليطلة، ففرَّت الرومُ أمامه حتى تجمَّعوا بسمورة، فلما التقى الجمعانِ، نزل النصرُ وانهزم الكفرُ، وتحصَّنوا بمدينة سمورة، وهي كبيرة جدًّا، فحصرها المسلمون بالمجانيق، حتى افتَتَحوها عَنوةً، وملكوا أكثَرَ شوارعِها، واشتغل الجندُ بالغنائم، وانضمَّت الرومُ إلى جهة من البلد، وخرجوا على حمية، فقتلوا خلقًا في خروجهم، فكانت غزوةُ الحكَمِ من أعظم المغازي، لولا ما طرأ فيها من تضييعِ الحَزْم، فقد رامت الرومُ السِّلْم، فأبى عليهم الحكَمُ، ثم خرج من بلادهم خوفًا من الثلوجِ، فلمَّا كان العامُ الآتي، استعدَّ أعظَمَ استعداد، وقصَدَ سمورة، فقتل وسَبى كلَّ ما مر به، ثم نازلها شهرينِ، ثم دخلوها بعد جَهدٍ، وبذلوا فيها السَّيفَ إلى المساء، ثم انحاز المسلمونَ، فباتوا على أسوارها، ثم صَبَّحوهم من الغد، لا يُبقُونَ على مُحتَلِمٍ. فقُتِلَ في سمورة ثلاثمائة ألف نفس، فلما بلغ الخبَرُ مَلِك روميَّة، كتبَ إلى الحكَمِ يرغَبُ في الأمان، فوضع الحكَمُ على الرُّوم ما كان جده عبدالرحمن الداخل وضع عليهم، وزاد عليهم أن يجلِبوا من ترابِ مدينةِ روميَّة نفسِها ما يُصنَعُ به أكوامٌ بشرقيَّ قُرطبة؛ صَغارًا لهم، وإعلاءً لِمَنارِ الإسلام."},{"id":643,"title":"اغتيال الأمين بن هارون الرشيد في السجن .","date":["العام الهجري :198","الشهر القمري : صفر","العام الميلادي :813"],"text":"لَمَّا كان الأمرُ من دخولِ جيشِ المأمون واستيلائِه على بغداد، وأخْذِ الأمينِ الأمانَ مِن هرثمة بن أعيَن، وكان قد سيَّرَه في السفينة، فعَلِمَ بذلك طاهر بن الحسين، فغضب لذلك كثيرًا؛ لأنَّ الأمينَ لم يطلُبْ منه الأمانَ، بل طلبه من هرثمةَ بنِ أعيَن، فقام بإغراقِ السَّفينةِ، ولكنَّ الأمينَ سبح ونجا، وكان بعضُ الجندِ قد أسَروه ووضعوه في أحدِ البُيوتِ، فدسَّ طاهِرٌ إليه بعضَ العجَمِ فقتلوه في البيتِ الذي كان محبوسًا فيه، وقَطَعوا رأسَه، وأرسلوه إلى طاهرِ بنِ الحُسين."},{"id":644,"title":"وفاة الأمين بن هارون الرشيد .","date":["العام الهجري :198","الشهر القمري : صفر","العام الميلادي :813"],"text":"هو محمَّد الأمين بن هارون الرشيد بن محمد المهدي بن المنصور، أبو عبد الله، ويقال: أبو موسى الهاشمي العباسي، وأمه أمُّ جعفر زبيدة بنت جعفر بن أبي جعفر المنصور، كان مولده بالرصافة سنة سبعين ومائة, وأتته الخلافةُ بعد وفاة والده الرشيدِ بوصيةٍ منه له بولايةِ العهد، ثمَّ نازعه أخوه المأمونُ على الخلافة. كان طويلًا سمينًا أبيضَ أقنى الأنفِ صغيرَ العينين، عظيمَ الكراديس، بعيدًا ما بين المنكِبَين. وقد رماه بعضُهم بكثرة اللَّعِب والشُّرب وقِلَّة الصلاة، والإكثار من اقتناءِ السُّودان والخِصيان، وإعطائِهم الأموالَ والجواهر، وأمْرِه بإحضار الملاهي والمغنِّين من سائر البلاد، وذُكِرَ أنه كان كثيرَ الأدبِ فصيحًا يقولُ الشعرَ ويعطي عليه الجوائِزَ الكثيرةَ، وكان شاعرُه أبو نُواس، وقد امتدحه أبو نُواس في بعض أشعارِه بأقبَح في معناه من صنيع الأمين. قُتِلَ بعد حروب دامية بينه وبين أخيه المأمون، قتَلَه قُرَيش الدنداني، وحمَلَ رأسَه إلى طاهر بن الحسين، فنَصَبَه على رمحٍ, وكانت ولايتُه أربع سنين وسبعة أشهر وثمانية أيام."},{"id":645,"title":"تولي المأمون للخلافة العباسية  .","date":["العام الهجري :198","الشهر القمري : صفر","العام الميلادي :813"],"text":"بعد أن تمَّ قتلُ الأمينِ في حَبسِه والاستيلاءِ على بغداد، أُخِذَت البيعةُ بالكاملِ للمأمونِ الذي بقي في مَرْو، وولَّى الحسَنَ بنَ سَهلٍ البصرةَ والكوفة والحجازَ واليمن والأهواز، وولَّى غيرَه المناطق الأخرى."},{"id":646,"title":"وفاة سفيان بن عيينة .","date":["العام الهجري :198","الشهر القمري : جمادى الآخرة","العام الميلادي :814"],"text":"هو محَدِّثُ الحرَمِ المكِّي، الحافِظُ المشهورُ: سُفيان بن عُيَينة بن أبي عمران يكنَّى أبا محمد. وهو مولى لبني عبد الله بن رويبة، وُلِد سنةَ سبعٍ ومائة بالكوفةِ، انتقل إلى مكَّةَ وبقي فيها، قال الشافعي: لولا مالِكٌ وسفيان لذهب عِلمُ الحجاز، كان واسِعَ العِلم، كبيرَ القَدرِ، مع زهدٍ وورَعٍ، له المُسند الجامِعُ، وتفسير القرآن، توفِّي في مكَّة- رحمه الله وجزاه عن الإسلامِ والمسلمين خيرًا."},{"id":647,"title":"العلويون يثورون على العباسيين في الكوفة .","date":["العام الهجري :199","الشهر القمري : جمادى الآخرة","العام الميلادي :815"],"text":"ظهر أبو عبدِ الله محمد بن إبراهيم بن إسماعيل بن إبراهيم بن الحسن بن الحسن بن علي بن أبي طالب، بالكوفةِ، يدعو إلى الرِّضا من آل محمَّد صلَّى الله عليه وسلَّم والعمَل بالكتابِ والسُّنَّة، وهو الذي يُعرَف بابنِ طباطبا، وكان القيِّم بأمرِه في الحرب أبو السَّرايا السَّري بن منصور، وكان سببُ خروجه أنَّه شاع أنَّ الفضلَ بنَ سَهلٍ قد غلب على المأمونِ، وأنَّه يستبِدُّ بالأمر دونه، فغَضِبَ لذلك بنو هاشم ووجوهُ الناس، واجترؤوا على الحسَن بنِ سَهل، وهاجت الفِتَنُ في الأمصار، فكان أوَّلَ مَن ظهر ابنُ طباطبا بالكوفة، وقد اتَّفَق أهلُ الكوفة على موافَقتِه واجتمعوا عليه مِن كُلِّ فجٍّ عميقٍ، وكان النائِبُ عليها من جهةِ الحسَنِ بن سهل سُليمانَ بنَ أبي جعفر المنصور، فبعث الحسَنُ بن سهل لسليمانَ بنِ أبي جعفر يلومُه ويؤنِّبُه على ذلك، وأرسل إليه بعشرةِ آلاف فارسٍ بصحبة زاهرِ بن زهير بن المسيب، فتقاتلوا خارِجَ الكوفةِ، فهَزَمَ أبو السرايا زاهرًا واستباح جيشَه ونهب ما كان معه، فلمَّا كان الغد من الوقعة توفِّيَ ابنُ طباطبا أميرُ الشيعة فجأةً، ويقال: إنَّ أبا السرايا سَمَّه وأقام مكانه غلامًا أمْرَد يقال له محمد بن محمد بن زيد بن علي بن الحسين بن علي بن أبي طالب. وانعزل زاهِرٌ بمن بقِيَ معه من أصحابِه إلى قصر ابن هُبيرة، وأرسل الحسَنُ بن سهل مع عبدوس بن محمد أربعةَ آلافِ فارسٍ، صورة مدد لزاهر، فالتقوا هم وأبو السَّرايا، فهزمهم أبو السرايا ولم يُفلِت من أصحاب عبدوس أحدٌ، وانتشر الطالبيُّون في تلك البلاد، وضرب أبو السرايا الدَّراهمَ والدنانير في الكوفة، ونقَشَ عليه {إِنَّ اللَّهَ يُحِبُّ الَّذِينَ يُقَاتِلُونَ فِي سَبِيلِهِ صَفًّا} ثمَّ بعث أبو السرايا جيوشَه إلى البصرة وواسط والمدائن، فهزموا مَن فيها من النوَّاب ودخلوها قهرًا، وقَوِيَت شوكتهم، فأهمَّ ذلك الحسَنَ بنَ سَهلٍ، وكتب إلى هرثمةَ بنِ أعيَنَ يستدعيه لحربِ أبي السرايا، فتمَنَّعَ ثم قَدِمَ عليه فخرج إلى أبي السرايا فهزم أبا السَّرايا غيرَ مَرَّة وطرده حتى ردَّه إلى الكوفة، ووثب الطالبيون على دُورِ بني العباس بالكوفةِ فنَهَبوها وخَرَّبوا ضِياعَهم، وفعلوا أفعالًا قبيحة، وبعث أبو السَّرايا إلى المدائِنِ فاستجابوا، وبعث إلى أهلِ مكةَ حُسَين بن حسن الأفطس ليقيمَ لهم الموسِمَ، فخاف أن يدخُلَها جهرةً، ولَمَّا سمع نائِبُ مكَّةَ- وهو داود بن عيسى بن موسى بن علي بن عبد الله بن عباس- هرب من مكة طالبًا أرضَ العراق، ثم دخلها الأفطسُ وحجَّ بها من سنته."},{"id":648,"title":"ظهور إبراهيم بن موسى (الجزار) بمكة .","date":["العام الهجري :200","العام الميلادي :815"],"text":"ظهر إبراهيمُ بن موسى بن جعفر بن محمد، وكان بمكَّةَ، فلما بلغَه خبَرُ أبي السرايا وما كان منه سار إلى اليمن، وبها إسحاقُ بن موسى بن عيسى بن موسى بن محمد بن علي بن عبد الله بن عباس عاملًا للمأمون، فلمَّا بلغه قُربُ إبراهيمَ من صنعاء، سار منها نحوَ مكة فأتى المشاش، فعسكَرَ بها واجتمع بها إليه جماعةٌ من أهل مكة هَرَبوا من العلويِّينَ، واستولى إبراهيمُ على اليمن، وكان يسمَّى الجزَّار؛ لكثرة من قتَل باليمن، وسبى، وأخذ الأموال."},{"id":649,"title":"خروج البربر بناحية مورور في الأندلس .","date":["العام الهجري :200","العام الميلادي :815"],"text":"خرج خارجيٌّ من البربر بناحية مورور، من الأندلس، ومعه جماعةٌ، فوصل كتابُ العامل إلى الحكَمِ بنِ هشام بخبَرِه، فأخفى الحكَمُ خبَرَه، واستدعى من ساعته قائدًا من قوَّاده، فأخبَرَه بذلك سرًّا، وقال له: سِرْ مِن ساعتِك إلى هذا الخارجيِّ فأْتِني برأسه، وإلَّا فرأسُك عِوَضَه، وأنا قاعِدٌ مكاني هذا إلى أن تعود. فسار القائِدُ إلى الخارجيِّ، فلما قاربه سأل عنه، فأُخبِرَ عنه باحتياطٍ كثيرٍ، واحترازٍ شديدٍ، ثم ذكر قولَ الحكَمِ: إنْ قتَلْتَه، وإلا فرأسُك عِوَضَه، فحَمَلَ نفسَه على سبيلِ المخاطرةِ فأعمل الحِيلةَ، حتى دخل عليه، وقتَلَه، وأحضَرَ رأسَه عند الحكم، فرآه بمكانِه ذلك لم يتغيَّرْ منه، وكانت غيبتُه أربعةَ أيام. ثم أحسَنَ إلى ذلك القائدِ، ووصله وأعلى محلَّه."},{"id":650,"title":"عبث زيد النار بالبصرة .","date":["العام الهجري :200","العام الميلادي :815"],"text":"كان بالبصرة من الطالبيين زيدُ بنُ موسى بن جعفر بن محمد بن علي بن حسين بن علي بن أبي طالب، ومعه جماعةٌ من أهل بيته، وهو الذي يقال له زيد النار وإنما سمِّيَ زيدَ النارِ؛ لكثرة ما حرَقَ مِن الدُّور بالبصرة من دور بني العبَّاسِ وأتباعهم، وكان إذا أتِيَ برجلٍ مِن المسودة كانت عقوبتُه عنده أن يحرِقَه بالنَّارِ، وانتهب أموالَ تجَّار البصرة، فأخذه عليُّ بن أبي سعيد أسيرًا، وقيل: إنه طلَبَ الأمانَ فأمَّنه."},{"id":651,"title":"مبايعة محمد بن جعفر (الديباج) بمكة .","date":["العام الهجري :200","الشهر القمري : ربيع الأول","العام الميلادي :815"],"text":"لَمَّا وصل الحُسَين بن حسن الأفطس لِمَكَّة من قِبَل أبي السرايا وفعل في مكَّة ما فعل من تغييرِ كسوةِ الكعبةِ وتخريبٍ ونَهبٍ، وصلَه خبرُ هزيمة أبي السرايا، ذهب إلى محمد بن جعفر بن محمد بن علي بن الحسين وبايعه فأقامه، وبايَعه بالخلافةِ، وجمع له النَّاسَ، فبايعوه طوعًا وكَرهًا وسَمَّوه أمير المؤمنين، فبقي شهورًا وليس له من الأمرِ شَيءٌ، ثمَّ لَمَّا وصل عامِلُ اليمن وجيشُ هرثمة بن أعين من الكوفةِ، هرب محمد بن جعفر إلى الجُحفة ثمَّ قُبِضَ عليه وطلَبَ الأمان وقال إنه وصَلَه أنَّ المأمونَ مات فدعا لبيعة نفسِه، فلما صَحَّ الخبَرُ عنده أنَّه لم يمُت خلَعَ نفسَه من الخلافة، ثم بعد ذلك أُرسِلَ إلى المأمون، ثم سار إلى جرجان ومات بها سنة 204هـ وهو المعروفُ بالديباج."},{"id":652,"title":"ثورة الطالبيين ببغداد بعد مقتل هرثمة بن أعين .","date":["العام الهجري :200","الشهر القمري : شعبان","العام الميلادي :816"],"text":"لَمَّا هزَمَ هَرثمةُ بنُ أعين أبا السرايا ومن كان معه من وُلاة الخلافة، وهو محمد بن محمد، وشَى بعضُ الناس إلى المأمون أنَّ هرثمة راسلَ أبا السرايا وهو الذي أمره بالظُّهور، فاستدعاه المأمونُ إلى مروٍ فأمر به فضُرِبَ بين يديه ووُطِئَ بطنُه، ثمَّ رفع إلى الحبس ثم قُتِلَ بعد ذلك بأيام، وانطوى خبَرُه بالكلية. ولَمَّا وصل بغدادَ خبَرُ قتلِه عَبَثَت العامَّة والحربيَّة بالحسن بن سهل نائب العراق، وقالوا: لا نرضى به ولا بعمَّاله ببلادنا، وأقاموا إسحاقَ بن موسى المهدي نائبًا، واجتمع أهلُ الجانبين على ذلك، والتفَّتْ على الحسَنِ بن سهل جماعةٌ من الأمراء والأجناد، وأرسل من وافق العامَّةَ على ذلك من الأمراء يحرِّضُهم على القتال، وجرت الحروبُ بينهم ثلاثةَ أيام في شعبان من هذه السنة، ثم اتفق الحالُ على أن يعطيهم شيئًا من أرزاقهم يُنفِقونها في شهرِ رمضان، فما زال يَمطُلُهم إلى ذي القعدة حتى يُدرِك الزرع، فخرج في ذي القَعدة زيدُ بن موسى الذي يقال له زيدُ النَّار، معه أخو أبي السرايا، وقد كان خروجُه هذه المرة بناحية الأنبار، فبعث إليه عليُّ بنُ هشام نائبُ بغداد عن الحسَنِ بن سهل- والحسَنُ بالمدائن إذ ذاك- فأُخِذَ وأُتِيَ به إلى عليِّ بنِ هشام، وأطفأ اللهُ ثائِرتَه."},{"id":653,"title":"وصول المسلمين إلى وسط بلاد الفرنج بالأندلس .","date":["العام الهجري :200","الشهر القمري : ذي القعدة","العام الميلادي :816"],"text":"جهَّز الحَكَمُ بنُ هِشامٍ أميرُ الأندلس جيشًا مع عبد الكريم بن مُغيث إلى بلاد الفرنج بالأندلس، فسار بالعساكرِ حتى دخل بأرضِهم، وتوسَّط بلادَهم، فخَرَّبَها ونهبَها وهدمَ عِدَّةً مِن حصونها، كلما أهلك موضعًا وصل إلى غيرِه، فاستنفد خزائِنَ مُلوكِهم. فلما رأى مَلِكُهم فِعْلَ المسلمين ببلادِهم، كاتَبَ ملوكَ جميع تلك النواحي مستنصِرًا بهم، فاجتمعت إليه النصرانيَّة مِن كُلِّ صَوبٍ، فأقبل في جموعٍ عظيمة بإزاء عسكرِ المسلمين، بينهم نَهرٌ، فاقتتلوا قتالًا شديدًا عدَّةَ أيَّامٍ، المسلمونُ يريدون يَعبُرون النهر، وهم يمنعونَ المسلمين من ذلك. فلما رأى المسلمونَ ذلك تأخَّروا عن النهر، فعبَرَ الفرنج إليهم، فاقتتلوا أعظمَ قتالٍ، فانهزم الفِرنجُ إلى النهر، فأخذهم بالسَّيفِ والأسر، فمن عبَرَ النهرَ سَلِمَ، وأسرَ جماعةً مِن جنودهم وملوكِهم وقَمامِصَتِهم، وعاد الفرنجُ ولزموا جانب النهر، يمنعون المسلمينَ مِن جوازِه، فبَقُوا كذلك ثلاثة عشر يومًا يقتتلون كلَّ يوم، فجاءت الأمطارُ، وزاد النهر، وتعذَّر جَوازُه، فقفل عبد الكريمِ عنهم سابعَ ذي الحِجَّة."}]
